(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.3"]={"from":72,"a":[["ש\u0003אם כן\u0004 לפטור את המזיק שור של ההקדש \u0003נכתוב קרא להאי \"רעהו\"\u0004 \u0005[שיאמר הכתוב את \"רעהו\" זה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מועד,\u0004 וממילא היינו למדים שכך הוא הדין בשור תם לפוטרו. וכיוון שהוא כתוב אצל תם, לא בא אלא להקל בנוגח שור של רעהו ולפוטרו מחצי נזק.","שנינו במשנה: \u0003שור של ישראל שנגח שור של גוי\u0004 — \u0003פטור\u0004 ושור של גוי שנגח שור של ישראל — חייב נזק שלם. \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ממה נפשך,\u0004 כלומר, בכל דרך שתרצה קשה הלכה זו, שכן \u0003אי\u0004 \u0005[אם]\u0006 האמור בתורה \u0003\"רעהו\"\u0004 הוא \u0003דוקא\u0004 \u0005[מדוייק]\u0006 ודין זה אינו אלא ב\"רעהו\" מישראל, אם כן שור של \u0003גוי כי נגח\u0004 \u0005[כאשר נוגח]\u0006 שור של \u0003ישראל נמי ליפטר\u0004 \u0005[גם כן שייפטר],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003\"רעהו\" לאו\u0004 \u0003דוקא\u0004 \u0005[אינו מדוייק],\u0006 אם כן \u0003אפילו\u0004 של \u0003ישראל כי נגח\u0004 \u0005[כאשר נוגח]\u0006 של \u0003גוי נחייב\u0004 \u0005[יתחייב]!\u0006","\u0003אמר ר' אבהו:\u0004 יש בדבר זה טעם מיוחד, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"עמד וימדד ארץ ראה ויתר גוים\"\u0004 (חבקוק ג, ו), ופירושו: \u0003ראה\u0004 הבורא \u0003שבע מצו‍ת שקיבלו עליהם בני נח\u0004 לקיימם, \u0003כיון שלא קיימו\u0004 אותן — \u0003עמד והתיר ממונן לישראל,\u0004 ולכן במקרים מסויימים אין ישראל חייב בנזקי הגוי.","\u0003ר' יוחנן אמר\u0004 ראייה לענין זה \u0003מהכא\u0004 \u0005[מכאן]:\u0006 נאמר בקשר למתן תורה \u0003\"\u0004ה' מסיני בא... \u0003הופיע מהר פארן\"\u0004 (דברים לג, ב), ופירושו: \u0003מ\u0004הר \u0003פארן\u0004 בשעת נתינת התורה \u0003הופיע,\u0004 כלומר, נתגלה וניתן \u0003ממונם\u0004 של גויים \u0003לישראל.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שור של ישראל שנגח שור של גוי\u0004 — \u0003פטור, שור של גוי שנגח שור של ישראל, בין תם בין מועד\u0004 — \u0003משלם נזק שלם, שנאמר: \"עמד וימדד ארץ ראה ויתר גוים\", ואומר: \"הופיע מהר פארן\".\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 מוסיף \u0003\"ואומר\"\u0004 ואינו מסתפק בראיה מן הפסוק הראשון?","ומסבירים: כך יש להבין, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"עמד וימדד ארץ\" מבעיא ליה\u0004 \u0005[צריך לו]\u0006 \u0003ל\u0004למוד ממנו ענין אחר, \u0003כ\u0004דרך שלמד ממנו \u0003רב מתנה ו\u0004כדרך שלמד ממנו \u0003רב יוסף\u0004 כל אחד לשיטתו, על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת: \u0003\"הופיע מהר פארן\",\u0004 לומר: \u0003מפארן הופיע ממונן לישראל.\u0004 כיון שהזכרנו את הדבר מביאים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 אותה דרשה של \u0003רב מתנה?\u0004 ש\u0003אמר רב מתנה \"עמד וימדד ארץ ראה\u0004 ויתר גוים \u0003\"\u0004כוונתו: \u0003מה ראה\u0004 — \u0003ראה שבע מצו‍ת שנצטוו עליהן בני נח ולא קיימום, עמד והגלה אותם מעל אדמתם,\u0004 שגולים גויים ממקומם מפני חטאיהם.","\u0003ומאי\u0004 \u0005[ומה,\u0006 כיצד\u0005]\u0006 \u0003משמע\u0004 ש\u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"ויתר\" לישנא דאגלויי\u0004 \u0005[לשון הגלייה]\u0006 \u0003הוא?\u0004 — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ויתר גוים\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"לנתר בהן על הארץ\"\u0004 (ויקרא יא, כא), \u0003ומתרגם\u0004 תרגום של פסוק זה: \u0003לקפצא בהון על ארעא\u0004 \u0005[לקפץ בהן על הארץ],\u0006 משמע ש\"נתר\" הוא לשון עקירה ממקום למקום.","\u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 אותה דרשה של \u0003רב יוסף?\u0004 ש\u0003אמר רב יוסף: \"עמד וימדד ארץ ראה\u0004 ויתר גוים \u0003\"\u0004\u0003מה ראה\u0004 — \u0003ראה שבע מצו‍ת שקיבלו עליהם בני נח ולא קיימום, עמד והתירן להם.\u0004","ותוהים: וכי \u0003איתגורי אתגר\u0004 \u0005[הרוויחו]\u0006 בדבר, שמפני שחטאו הותר להם? \u0003אם כן, מצינו\u0004 \u0005[מצאנו]\u0006 \u0003חוטא נשכר! אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא:\u0004 אין הכוונה שהתיר להם במובן זה שאין עבירה בדבר, אלא \u0003לומר שאפילו\u0004 הם \u0003מקיימין אותן\u0004 — \u0003אין\u0004 הם \u0003מקבלין עליהן שכר.\u0004","ושואלים: \u0003ולא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' מאיר אומר: מנין שאפילו גוי ועוסק בתורה שהוא ככהן גדול\u0004 — \u0003תלמוד לומר: \"אשר יעשה אתם האדם וחי בהם\"\u0004 (ויקרא יח, ה), והוא מדייק מן הלשון: \u0003\"\u0004אשר יעשו אותם \u0003כהנים ולוים וישראלים\"\u0004 — \u0003לא נאמר\u0004 בכתוב, \u0003אלא \"\u0004ה\u0003אדם\"\u0004 לאמור המין האנושי בכלל, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן \u0003שאפילו גוי ועוסק בתורה הרי הוא ככהן גדול!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לדבר זה: כוונת רב יוסף היתה ש\u0003אין מקבלים עליהן שכר כ\u0004מי ש\u0003מצווה ועושה, אלא כמי שאינו מצווה ועושה.\u0004 שהרי \u0003אמר ר' חנינא: גדול המצווה ועושה יותר ממי שאינו מצווה ו\u0004בכל זאת \u0003עושה,\u0004 וזהו מעמדם של הגויים.","כהמשך לדין זה מביאים ברייתא: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003וכבר שלחה מלכות רומי שני סרדיוטות\u0004 (אנשי צבא) \u0003אצל חכמי ישראל\u0004 ואמרו להם לפי הוראת המלכות: \u0003למדונו תורתכם. קראו\u0004 אותם סרדיוטות בתורה \u0003ושנו ושלשו. בשעת פטירתן\u0004 (פרידתם) \u0003אמרו להם\u0004 לחכמים: \u0003דקדקנו בכל תורתכם ואמת הוא, חוץ מדבר זה שאתם אומרים שור של ישראל שנגח שור של גוי\u0004 — \u0003פטור, של גוי שנגח שור של ישראל, בין תם בין מועד\u0004 — \u0003משלם נזק שלם.\u0004","וטעמם: \u0003ממה נפשך,\u0004 \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"רעהו\"\u0004 שנאמר בכתוב הוא \u0003דוקא\u0004 — \u0003אפילו\u0004 של \u0003גוי כי נגח\u0004 \u0005[כאשר\u0006 הוא \u0005נוגח]\u0006 את של \u0003ישראל ליפטר\u0004 \u0005[שיהא פטור],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003\"רעהו\"\u0004 שנאמר הוא \u0003לאו\u0004 \u0005[לא]\u0006 \u0003דוקא\u0004 — \u0003אפילו\u0004 של \u0003ישראל כי נגח\u0004 \u0005[כאשר\u0006 הוא \u0005נוגח]\u0006 את של \u0003גוי לחייב\u0004 \u0005[שיהא חייב]!\u0006 והוסיפו: \u0003ו\u0004אולם \u0003דבר זה אין אנו מודיעים אותו למלכות,\u0004 שכיון שראינו שהתורה כולה צודקת היא, אין אנו מגלים למלכות הלכה זו שתהא תואנה עליכם.","ואגב כך מסופר סיפור אחר: \u0003רב שמואל בר\u0004 \u0005[בן]\u0006 \u0003יהודה שכיבא ליה ברתא\u0004 \u0005[מתה לו בת],\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לעולא: קום ניזל נינחמיה\u0004 \u0005[עמוד, נלך\u0006 ו\u0005ננחמנו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי אית לי גבי נחמתא דבבלאי דגידופא הוא\u0004 \u0005[מה יש לי\u0006 לעשות \u0005אצל נחמה של הבבליים שהיא\u0006 בעצם \u0005גידוף\u0006 כלפי מעלה\u0005],\u0006 ומדוע? — \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 בשעת ניחום \u0003\"מאי\u0004 \u0005[מה]\u0006 \u0003אפשר למיעבד\"\u0004 \u0005[לעשות],\u0006 ומכאן מובן לכאורה כי \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אפשר למיעבד\u0004 \u0005[לעשות]\u0006 — \u0003עבדי\u0004 \u0005[\u0006היו \u0005עושים]\u0006 ונלחמים נגד דין שמים, ודבר זה נראה גידוף.","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003הוא,\u0004 עולא, \u0003לחודאי גביה\u0004 \u0005[לבדו אליו]\u0006 לנחמו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא דרשה זו: נאמר \u0003\"ויאמר ה'\u0004 אלי \u0003אל תצר את מואב ואל תתגר בם מלחמה\"\u0004 (דברים ב, ט), ויש להבין: \u0003וכי מה עלה על דעתו של משה, לעשות מלחמה\u0004 על מואב \u0003שלא ברשות\u0004, שהיה צורך בדברי ה' להזהירו מכך? \u0003אלא נשא משה קל וחומר בעצמו,\u0004 וכך \u0003אמר: ומה מדינים שלא באו אלא לעזור את מואב, אמרה תורה\u0004 עליהם \u0003\"צרור את המדינים והכיתם אותם\"\u0004 (במדבר כה, יז),"],["\u0003מואבים עצמן\u0004 שהם שגרמו לדבר, \u0003לא כל שכן\u0004 שיש להילחם בהם?","על כן \u0003אמר לו הקדוש ברוך הוא: לא כשעלתה על דעתך עלתה על דעתי.\u0004 וטעמו של דבר: \u0003שתי פרידות\u0004 (=גוזלות, כלומר, ילדות) \u0003טובות יש לי להוציא מהן,\u0004 את \u0003רות המואביה\u0004 שהיא תהיה אם שושלת בית דוד, \u0003ו\u0004את \u0003נעמה העמונית\u0004 אשת שלמה שממנה נמשכה שושלת בית דוד, ולכן אין להרוג אותם כדי שלא יאבדו אלה.","והוסיף עולא, \u0003והלא דברים קל וחומר: ומה בשביל שתי פרידות טובות\u0004 בלבד \u0003חס הקדוש ברוך הוא על שתי אומות גדולות ולא החריבן, בתו של רבי\u0004 (רב שמואל בר יהודה), \u0003אם כשרה היא וראויה היא לצאת ממנה דבר טוב\u0004 — \u0003על אחת כמה וכמה דהוה\u0004 \u0005[שהיתה]\u0006 \u0003חיה,\u0004 ואם מתה — כך ראוי היה, ואין להצטער על כך.","ואגב שהוזכרו מואב ועמון, מביאים את מה ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אין הקדוש ברוך הוא מקפח שכר כל בריה\u0004 ומשלם לכל אדם על מעשה טוב, \u0003אפילו שכר שיחה נאה,\u0004 כלומר, אפילו על כך שאומרים דבר בלשון נקייה.","ש\u0003אילו בכירה\u0004 שבבנות לוט \u0003דקאמרה\u0004 \u0005[שאמרה]\u0006 וקראה לבנה שילדה מאביה \u0003\"מואב\",\u0004 שיש בכך רמז שהוא בן האב, \u0003אמר לו הקדוש ברוך הוא למשה \"אל תצר את מואב ואל תתגר בם מלחמה\"\u0004 (דברים ב, ט), ויש לדייק מכאן: \u0003מלחמה הוא\u0004 ש\u0003לא\u0004 יעשו איתם, \u0003הא אנגריא\u0004 \u0003עביד בהו\u0004 \u0005[הרי עבודת כפיה\u0006 ושאר דברים \u0005עשה בהם].\u0006","ואילו ה\u0003צעירה דקאמרה\u0004 \u0005[שאמרה]\u0006 וקראה לו \u0003\"בן עמי\"\u0004 שיש בכך רק רמז שהוא ממשפחתה, בשכר שהשתמשה בלשון נקיה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הקדוש ברוך הוא למשה\u0004 \u0003\"וקרבת מול בני עמון אל תצרם ואל תתגר בם\"\u0004 (דברים ב, יט), כלומר, אל תתגר בם בעמונים \u0003כלל,\u0004 אף שלא למלחמה, ש\u0003אפילו אנגריא לא תעביד בהו\u0004 \u0005[עבודת כפיה אל תעשה בהם].\u0006","\u0003ו\u0004עוד בענין זה \u0003אמר ר' חייא בר אבא אמר ר' יהושע בן קרחה: לעולם יקדים אדם לדבר מצוה, שבשביל לילה אחת שקדמתה הבכירה לצעירה\u0004 שהרי התכוונה למצווה, כדי להביא ילדים לעולם — \u0003קדמתה ארבע דורות\u0004 להיכנס מזרעה \u0003לישראל,\u0004 והם: \u0003עובד\u0004 (בנה של רות המואביה), \u0003ישי, דוד ושלמה, ואילו צעירה\u0004 לא נכנס לישראל מזרעה \u0003עד רחבעם\u0004 בן שלמה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ושם אמו נעמה העמנית\"\u0004 (מלכים א יד, לא).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שור של ישראל שנגח שור של כותי\u0004 (שומרוני) — הרי הוא \u0003פטור\u0004 עליו, \u0003ו\u0004אולם שור \u0003של כותי שנגח שור של ישראל, תם\u0004 — \u0003משלם חצי נזק, ומועד\u0004 — \u0003משלם נזק שלם.\u0004 ואין דינו של כותי לגמרי כגוי שאף על התם משלם נזק שלם.","ואילו \u0003ר' מאיר אומר: שור של ישראל שנגח שור של כותי\u0004 — \u0003פטור\u0004 לגמרי, \u0003ושל כותי שנגח שור של ישראל, בין תם בין מועד\u0004 — \u0003משלם נזק שלם\u0004 שדינם כגויים.","ושואלים: \u0003למימרא דסבר\u0004 \u0005[האם לומר,\u0006 ללמוד מכאן \u0005שסבור]\u0006 \u0003ר' מאיר:\u0004 כי ה\u0003כותים גרי אריות הן,\u0004 שעצם התגיירותם של הכותים מתחילתה מחמת אונס היתה, ואין ממש בגרותם, ולכן גם לענין תשלומי נזק דינם כדין גויים?","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו: \u0003כל הכתמים\u0004 (כתמי דם על בגדים, שיש לשער שהם כתמי דם נידה) \u0003הבאים מ\u0004העיר \u0003רקם\u0004 — \u0003טהורים,\u0004 מפני שהתושבים הם גוים, ובגדים מוכתמים אלה שלהם הם, ואינם מטמאים. \u0003ר' יהודה מטמא\u0004 אותם, \u0003מפני ש\u0004לדעתו תושבי רקם \u0003הן גרים, וטועים\u0004 ששכחו את יהדותם, אבל כיון שהם יהודים — דמם מטמא.","והלכה נוספת בענין זה: כתמים שבאו \u0003מבין הגוים טהורים.\u0004 באו בגדים עם כתמים \u0003מבין ישראל ומבין הכותים\u0004 — \u0003ר' מאיר מטמא,\u0004 שר' מאיר סבור שהכותים חשודים על הפקרת כתמיהם. \u0003וחכמים מטהרין, שלא נחשדו ישראל על כתמיהן,\u0004 שאינם מפקירים ומשליכים אותם, כדי שלא יטמאו בהם אחרים, ואף כותים בכלל זה.","\u0003אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003סבר ר' מאיר כותים גרי אמת הם,\u0004 שלולא כן דינם כגויים, שאינם מטמאים כלל. ואם כן כיצד להסביר את דעתו של ר' מאיר בעניין נזיקין?","\u0003אמר ר' אבהו:\u0004 לדעתו של ר' מאיר גרי אמת הם, ומעיקר הדין היו צריכים להיות כישראל, ששור שהזיק אותם — חייב, ואם שור תם שלהם נגח — משלמים חצי נזק בלבד. אלא \u0003קנס הוא שקנס ר' מאיר בממונם\u0004 לתת להם מעמד של גויים, כדי \u0003שלא יטמעו\u0004 (יתערבו) \u0003בהם\u0004 ישראל על ידי נישואים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' זירא\u0004 ממה ששנינו: \u0003ואלו נערות שיש להם קנס,\u0004 שהאונס אותן חייב לשלם קנס ככתוב בתורה, לא רק אם אנס נערה כשירה מישראל אלא גם \u0003הבא על הממזרת ועל הנתינה\u0004 (מצאצאי גבעונים) \u0003ועל הכותית. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי \u0003קנס ר' מאיר בממונם\u0004 לעשותם כגויים, \u0003הכי נמי נקנוס\u0004 \u0005[כך גם כן שיקנוס]\u0006 את הכותית האנוסה שלא תקבל את הקנס האמור בתורה, \u0003כדי שלא יטמעו בהן\u0004 שידעו שאינם כישראל!","\u0003אמר אביי:\u0004 מה שלא ביטלו לדעת ר' מאיר תשלום קנס זה, הוא \u0003כדי\u0004"],["\u0003שלא יהא חוטא\u0004 (האונס) \u0003נשכר.\u0004","ושואלים: אם כדי לקנוס את החוטא, \u0003ונתביה\u0004 \u0005[ושיתן אותו]\u0006 את הקנס \u0003לעניים\u0004 ולא לכותית האנוסה, כדי שלא יטמעו בהם! \u0003אמר רב מרי: משום דהוי\u0004 \u0005[שהוא]\u0006 \u0003ממון שאין לו תובעים,\u0004 מכיון שאינו מחוייב לתת לעני מסויים, יוכל האונס להשתמט ולומר שרוצה לתת לעני אחר, ולכן נשאר בענין זה דין התורה שיתן לכותית האנוסה, כדי שלא יהא חוטא נשכר.","\u0003שור של פקח\u0004 (אדם ברדעת) \u0003שנגח שור של חרש\u0004 או של \u0003שוטה ו\u0004כן של \u0003קטן\u0004 שכל אלה אינם נחשבים בני דעת — הרי זה \u0003חייב\u0004 בנזקין. \u0003ו\u0004אילו שור \u0003של חרש שוטה וקטן שנגח שור של פקח\u0004 — הרי זה \u0003פטור.\u0004","\u0003שור של חרש שוטה וקטן שנגח\u0004 — \u0003בית דין מעמידין להן אפוטרופוס, ומעידין להן\u0004 על השור שנגח \u0003בפני אפוטרופוס\u0004 עד שנעשה השור מועד, שהוא נחשב כבעלים לענין \"והועד בבעליו\".","אם לאחר שנעשה השור מועד באופן זה, \u0003נתפקח החרש,\u0004 או \u0003נשתפה השוטה ו\u0004כן אם \u0003הגדיל הקטן\u0004 — \u0003חזר\u0004 השור \u0003לתמותו,\u0004 אלו \u0003דברי ר' מאיר,\u0004 שלדעתו לא הועד השור אלא לפי שעה בעודו ברשות האפוטרופוס. \u0003ר' יוסי אומר:\u0004 לא כן, אלא \u0003הרי הוא בחזקתו\u0004 שור מועד לנגוח.","והלכה אחרת: \u0003שור האצטדין\u0004 שהוא מלומד להילחם בזירה, אם נגח והרג אדם — \u0003אינו חייב מיתה, שנאמר:\u0004 \"ו \u0003כי יגח\u0004 שור את איש\u0003\"\u0004 (שמות כ״א:כ״ח) ומלשון זה משמע: \u0003ולא שיגיחוהו\u0004 (יגרמו לו לנגוח), ולכן שור האצטדין שמלמדים אותו לנגוח — פטור.","ושואלים: \u0003הא גופא קשיא\u0004 \u0005[\u0006משנתנו \u0005זו עצמה קשה]\u0006 מתוכה. \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 בתחילה: \u0003שור של חרש שוטה וקטן שנגח שור של פקח\u0004 — \u0003פטור. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אין מעמידין אפוטרופוס ל\u0004שור \u0003תם\u0004 של חרש שוטה וקטן, על מנת \u0003לגבות מגופו\u0004 של השור המזיק את נזקו. ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה,\u0006 המשכה\u0005]\u0006 של המשנה: \u0003שור של חרש שוטה וקטן שנגח\u0004 — \u0003בית דין מעמידין להם אפוטרופוס, ומעידין להם בפני אפוטרופוס. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מעמידין להם אפוטרופוס ל\u0004שור \u0003תם\u0004 שלהם שנגח כדי \u0003לגבות מגופו!\u0004","\u0003אמר רבא: הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש להבין את המשנה: אין מעמידים אפוטרופוס לשור תם לגבות מגופו. \u0003ואם הוחזקו\u0004 שוורים אלה \u0003נגחנין,\u0004 ולא קרה הדבר באופן חד פעמי — \u0003מעמידין להם אפוטרופוס ומעידין להן בפני אפוטרופוס ומשוינן להו\u0004 \u0005[ועושים אותם]\u0006 על ידי כך \u0003מועד,\u0004 \u0003דכי הדר ונגח\u0004 \u0005[שכאשר יחזור ויגח]\u0006 יהיה חייב \u0003לשלם\u0004 \u0005[שישלם]\u0006 \u0003מעלייה\u0004 (מן המובחר שבנכסי בעל השור) ולא מגופו.","לעצם הענין שואלים: \u0003מעליית מאן\u0004 \u0005[מי]\u0006 מרכושו של מי משלם על נזקי שור מועד של יתומים קטנים? \u0003ר' יוחנן אמר: מעליית יתומין. ר' יוסי בר חנינא אמר: מעליית אפוטרופוס,\u0004 שהוא משלם עבורם.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב אסי: אין נזקקין לנכסי יתומין\u0004 לגבות מהם כל חוב שהוא, \u0003אלא אם כן רבית אוכלת בהן,\u0004 שאם לווה אביהם מגוי ברבית, שאם לא יפרעו לו מיד יגדל החוב מאוד — אז בית דין דואגים לשלם את החוב מנכסי היתומים. אבל אין עושים כן בכל חוב אחר שעל היתומים.","\u0003ור' יוחנן אמר:\u0004 גובים מהם \u0003או ל\u0004פרעון \u0003שטר שיש בו רבית,\u0004 משום הרבית האוכלת בהם, \u0003או ל\u0004פרעון \u0003כתובת אשה משום מזוני\u0004 \u0005[מזונות],\u0006 שאם היתה אשת אביהם תובעת לקבל את כתובתה מנכסי הבעל שמת, וכל עוד אינה מקבלת כתובה הרי מזונותיה מוטלים על היורשים — במקרה זה גובים את הכתובה מנכסי היתומים, כדי שלא יתמעטו בשל תשלום המזונות. ומכל מקום אף מדברי ר' יוחנן אלה נובע שבכל מקרה אחר אין גובים כל חוב מנכסי היתומים!","ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר\u0004 שמשלמים עבור נזקי שור מועד \u0003מעליית אפוטרופסין,\u0004 ו\u0003ר' יוסי בר חנינא\u0004 הוא ש\u0003אמר\u0004 שמשלמים \u0003מעליית יתומין.\u0004","על כך \u0003אמר רבא: משום דקשיא\u0004 \u0005[שקשה]\u0006 לך הסתירה מדברי \u0003ר' יוחנן\u0004 כאן על דברי \u0003ר' יוחנן\u0004 במקום אחר \u0003משוית ליה\u0004 \u0005[עושה אתה אותו]\u0006 את \u0003ר' יוסי בר חנינא טועה,\u0004 שאתה מייחס לו דעה שאינה להלכה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוסי בר חנינא דיינא\u0004 \u0005[דיין]\u0006 \u0003הוא ונחית לעומקיה דדינא\u0004 \u0005[ויורד לעומק הדין]!\u0006","\u0003אלא, לעולם לא תיפוך\u0004 \u0005[תהפוך]\u0006 את השיטות והשאר אותן כפי שהן, \u0003ו\u0004אולם דינו של \u0003מזיק שאני\u0004 \u0005[שונה]\u0006 שאף שר' יוחנן אומר בדרך כלל שאין גובים מן היתומים, מכל מקום במקרה ששורם הזיק לאחרים — גובים. ומעתה מפרשים את טעמי המחלוקת, \u0003ר' יוחנן אמר:\u0004 גובים את הנזק \u0003מעליית יתומים, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שגובים \u0003מעליית אפוטרופוס\u0004 —"],["\u0003ממנעי\u0004 \u0005[יימנעו]\u0006 אנשים \u0003ולא עבדי\u0004 \u0005[ייעשו]\u0006 אפוטרופסים, שהרי האפוטרופוס עלול להפסיד מנכסיו בגלל היותו אפוטרופוס, אם משלם עבור נזקי שור היתומים. ו\u0003ר' יוסי בר חנינא אמר:\u0004 גובים \u0003מעליית אפוטרופוס, ו\u0004אין לחשוש שאנשים יימנעו מלהיות אפוטרופסים בגלל הפסד ממונם, כי הם \u0003חוזרין ונפרעין מן היתומים לכי גדלי\u0004 \u0005[כאשר\u0006 הם \u0005יגדלו].\u0006","ומעירים: \u0003ו\u0004לעיקרה של השאלה אם \u0003מעמידים להן\u0004 לאלה שאינם בני דעת \u0003אפוטרופין ל\u0004שור \u0003תם\u0004 שנגח כדי \u0003לגבות מגופו, תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שור שנתחרשו\u0004 (שנעשו חרשים) \u0003בעליו, ו\u0004כן שור \u0003שנשתטו בעליו, ו\u0004כן כ\u0003שהלכו בעליו למדינת הים,\u0004 כיצד נוהגים בו אם נגח? \u0003יהודה בן נקוסא אמר\u0004 בשם \u0003סומכוס: הרי הוא בתמותו עד שיעידו בו בפני הבעלים. וחכמים אומרים: מעמידין להן אפוטרופין, ומעידין בהן בפני אפוטרופין,\u0004 ועל ידי כך נעשה השור מועד.","ואם \u0003נתפקח החרש,\u0004 או \u0003נשתפה השוטה,\u0004 או ש\u0003הגדיל הקטן ו\u0004כן אם \u0003באו בעליו\u0004 של השור \u0003ממדינת הים, יהודה בן נקוסא אמר\u0004 בשם \u0003סומכוס: חזר\u0004 השור \u0003לתמותו\u0004 כפי שהיה קודם, \u0003עד שיעידו בו\u0004 שלוש פעמים \u0003בפני בעלים,\u0004 ככתוב בתורה. \u0003ר' יוסי אמר: הרי הוא,\u0004 השור, \u0003בחזקתו\u0004 ומועד הוא.","ובפירוש ברייתא זו \u0003אמרו: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הרי הוא בתמותו\" דקאמר\u0004 \u0005[שאמר]\u0006 \u0003סומכוס? אילימא דלא מייעד\u0004 \u0005[אם תאמר שאינו נעשה מועד]\u0006 \u0003כלל,\u0004 ונשאר לעולם תם — \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף\u0006 הברייתא\u0005]\u0006 בדברי סומכוס עצמו: \u0003חזר לתמותו, מכלל דאייעד\u0004 \u0005[שנעשה מועד]\u0006 קודם לכן!","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הרי הוא בתמותו\"\u0004 — \u0003הרי הוא בתמימותו\u0004 (בשלימותו), ש\u0003לא מחסרינן ליה\u0004 \u0005[מחסרים אנו אותו]\u0006 ואין גובים בפועל מגופו של השור, אלא הניזק ממתין עד שיחזרו הבעלים. \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהוא סבור ש\u0003אין מעמידין אפוטרופוס ל\u0004שור \u0003תם לגבות מגופו. וחכמים\u0004 שחולקים על סומכוס \u0003אומרים: מעמידין להן אפוטרופוס ומעידין להן בפני אפוטרופוס. אלמא\u0004 \u0005[מכאן]\u0006 שלדעתם \u0003מעמידין אפוטרופוס ל\u0004שור \u0003תם לגבות מגופו.\u0004","ושואלים: \u0003וסיפא במאי קמיפלגי\u0004 \u0005[ו\u0006ב\u0005סופה\u0006 של הברייתא, \u0005במה,\u0006 באיזה עיקרון, \u0005נחלקו]?\u0006 ומשיבים: לענין \u0003רשות משנה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 מחלוקת\u0005],\u0006 כלומר, נחלקו האם שינוי בעלות (\"רשות\") גורם גם לשינוי מעמדו של השור. ש\u0003סומכוס סבר\u0004 \u0005[סבור]:\u0006 \u0003רשות משנה, ו\u0004אילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003רשות אינה משנה,\u0004 שדינו של השור נקבע לפי השור עצמו ואינו משתנה עם שינוי בעליו.","ובענין זה מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003שור\u0004 של \u0003חרש\u0004 או של \u0003שוטה ו\u0004כן שור של \u0003קטן שנגח, ר' יעקב משלם חצי נזק.\u0004","ומיד תוהים על הלשון: \u0003ר' יעקב מאי עבידתיה\u0004 \u0005[מה מעשהו],\u0006 מדוע משלם ר' יעקב? \u0003אלא\u0004 תקן הלשון ו\u0003אימא\u0004 \u0005[אמור]\u0006 כך, \u0003ר' יעקב אומר: משלם חצי נזק.\u0004","ומעתה נבדוק: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים],\u0006 באיזה מקרה מדובר כאן? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ב\u0004שור \u0003תם\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, \u0003דכולי עלמא נמי\u0004 \u0005[ש\u0006הרי \u0005לדעת הכל גם כן]\u0006 \u0003חצי נזק הוא\u0004 ש\u0003משלם\u0004 ומה חידש ר' יעקב? \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ב\u0004שור \u0003מועד\u0004 מדובר, יש לברר כיצד היה הדבר, \u0003אי\u0004 \u0005[אם]\u0006 מדובר במקרה \u0003דעבדי ליה\u0004 \u0005[שעשו לו]\u0006 \u0003שמירה\u0004 ושמרוהו כראוי — \u0003כלל כלל לא בעי\u0004 \u0005[צריכים]\u0006 \u0003לשלומי\u0004 \u0005[לשלם],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר ש\u0003לא עבדי ליה\u0004 \u0005[עשו לו]\u0006 \u0003שמירה\u0004 כראוי — \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003נזק בעי שלומי\u0004 \u0005[צריך לשלם]!\u0006","\u0003אמר רבא: לעולם\u0004 תפרש את דברי ר' יעקב שמדובר \u0003ב\u0004שור \u0003מועד, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003דעבדי\u0004 \u0005[שעשו]\u0006 לו \u0003שמירה פחותה\u0004 (כלומר, שמירה רגילה), \u0003ולא עבדי ליה\u0004 \u0005[עשו לו]\u0006 \u0003שמירה מעולה.\u0004","\u0003ור'\u0004 \u0003יעקב סבר לה\u0004 \u0005[סבור ב\u0006ענין \u0005זה]\u0006 \u0003כר' יהודה\u0004 ש\u0003אמר: צד תמות במקומה עומדת.\u0004 כלומר, גם כאשר נעשה השור מועד, לא יצא לגמרי מדין תם שהיה לו מקודם, ומחצית הנזק גובים כאילו היה זה שור תם, ומגופו. \u0003ו\u0004עוד \u0003סבר לה\u0004 \u0005[סבור ב\u0006ענין \u0005זה]\u0006 ר' יעקב \u0003כר' יהודה\u0004 ש\u0003אמר:\u0004 \u0003מועד סגי ליה\u0004 \u0005[די לו]\u0006 \u0003בשמירה פחותה,\u0004 ולכן בזמן ששמר שמירה פחותה — פטור הוא על צד המועד שבו, אך חייב על צד התמות שבו.","\u0003וסבר לה\u0004 \u0005[וסבור בזה]\u0006 ר' יעקב עוד \u0003כרבנן דאמרי\u0004 \u0005[כ\u0006דברי \u0005חכמים שאמרו]:\u0006 \u0003מעמידין אפוטרופוס ל\u0004שור \u0003תם לגבות מגופו.\u0004 ומשום כך ר' יעקב אומר ששור מועד ששמרו שמירה פחותה משלם חצי נזק מגופו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: \u0003ו\u0004האם \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 ר' יהודה ור' יעקב בכך? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שור של חרש שוטה וקטן שנגח, ר' יהודה מחייב, ור' יעקב אומר: חצי נזק הוא\u0004 ש\u0003משלם! אמר רבא בר עולא:\u0004 אין כאן מחלוקת, אלא \u0003מה שמחייב ר' יהודה\u0004 ולא פירש מה מחייב — הוא ש\u0003פירש ר' יעקב\u0004 והסביר כמה חייב לדברי ר' יהודה.","ושואלים: \u0003ול\u0004דעת \u0003אביי\u0004 ש\u0003אמר פליגי\u0004 \u0005[\u0006ש\u0005חלוקים]\u0006 ר' יעקב ור' יהודה, \u0003במאי פליגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005חלוקים\u0006 הם\u0005]?\u0006","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך\u0004 אביי: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003ב\u0004מקרה שהיה שור \u0003מועד ולא נטריה\u0004 \u0005[שמרו]\u0006 \u0003כלל,\u0004 ואז חייבים לשלם נזק שלם.","\u0003ר' יעקב סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יהודה בחדא\u0004 \u0005[ב\u0006ענין \u0005אחד]\u0006 \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו ב\u0006ענין \u0005אחד].\u0006 ופירוט הדברים, \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003כר' יהודה בחדא\u0004 \u0005[ב\u0006ענין \u0005אחד]\u0006 ש\u0003אילו ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003צד תמות במקומה עומדת\u0004 ולזה מסכים ר' יעקב. \u0003ופליג עליה בחדא\u0004 \u0005[ו\u0006אולם \u0005חולק עליו ב\u0006ענין \u0005אחד],\u0006 ש\u0003אילו ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מעמידין להן אפוטרופוס ל\u0004שור \u0003תם לגבות מגופו, ור' יעקב סבר: אין מעמידין, ו\u0004לכן \u0003לא משלם אלא פלגא\u0004 \u0005[החצי]\u0006 של ה\u0003מועד,\u0004 וחציו האחר, צד תמות שבו — אינו משלם, שהרי אין הבעלים שם, ואין יכול לגבות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר אביי לרבינא: בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי דאמר פליגי\u0004 \u0005[שאומר\u0006 ש\u0005חלוקים\u0006 הם\u0005]\u0006 — \u0003שפיר\u0004 \u0005[יפה]\u0006 הפירוש, \u0003אלא ל\u0004דעת \u0003רבא דאמר\u0004 \u0005[שאומר]\u0006 ש\u0003לא פליגי\u0004 \u0005[חלוקים],\u0006 \u0003אדמוקי לה\u0004 \u0005[עד ש\u0006הוא \u0005מעמיד\u0006 ומפרש אותה\u0005],\u0006 את הברייתא הראשונה, \u0003ב\u0004שור \u0003מועד\u0004 — \u0003נוקמא\u0004 \u0005[שיעמיד\u0006 ויפרש אותה\u0005]\u0006 \u0003ב\u0004שור \u0003תם,\u0004"],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 — \u0003דעבד ליה\u0004 \u0005[שעשה לו]\u0006 \u0003שמירה פחותה ולא עבד ליה\u0004 \u0005[עשה לו]\u0006 \u0003שמירה מעולה, אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' אליעזר בן יעקב\u0004 — ש\u0003לא עביד ליה\u0004 \u0005[עשה לו]\u0006 \u0003שמירה כלל.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר בן יעקב אומר: אחד תם ואחד מועד ששמרן שמירה פחותה\u0004 — \u0003פטורין,\u0004 ואינו חייב אלא אם כן לא שמרם כלל. \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003ר' יעקב\u0004 — ש\u0003מעמידין להן אפוטרופין ל\u0004שור \u0003תם לגבות מגופו!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 לכך התכוון רבא כאשר העמיד את דברי ר' יעקב במועד — לומר \u0003חדא דאית ביה תרתי טעמא\u0004 \u0005[\u0006דבר \u0005אחד שיש בו שני טעמים]\u0006 כשיטת ר' יהודה; שצד תמות במקומה עומדת, ושדי למועד בשמירה פחותה.","\u0003רבינא\u0004 עצמו \u0003אמר\u0004 פירוש אחר להסביר את המחלוקת בברייתא: לענין \u0003רשות משנה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003כגון דהוה\u0004 \u0005[שהיה]\u0006 שור \u0003מועד,\u0004 שהועד בזמן שהיה ברשות האפוטרופוס, \u0003ונתפקח החרש, ונשתפה השוטה, והגדיל הקטן,\u0004 וחזר לרשותם\u0003. ר' יהודה סבר: הרי הוא בחזקתו,\u0004 אף שעבר לרשות אחרת, ולכך הוא מחייבו נזק שלם. ו\u0003ר' יעקב סבר: רשות משנה,\u0004 שכיון שעבר לרשות אחרת חזר לדין שור תם, ואינו משלם אלא חצי נזק.","ועוד בענין אחריותם של אפוטרופסים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אפוטרופסים משלמין\u0004 כל נזק שהזיק שור מועד של היתומים \u0003מן העלייה,\u0004 \u0003ו\u0004אולם \u0003אין\u0004 הם \u0003משלמין כופר\u0004 אם הרג השור אדם.","ושואלים: \u0003מאן תנא\u0004 \u0005[מי הוא\u0006 התנא ש\u0005שנה]\u0006 כי \u0003כופרא\u0004 \u0005[הכופר]\u0006 מיועד להיות \u0003כפרה\u0004 לבעל השור, \u0003ויתמי לאו\u0004 \u0005[ויתומים לא]\u0006 \u0003בני כפרה נינהו\u0004 \u0005[הם],\u0006 שהרי הם קטנים ואין להם אחריות, ולפיכך אין האפוטרופוס משלם כופר?","\u0003אמר רב חסדא:\u0004 שיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין זה של כופר: כוונת הכתוב \u0003\"\u0004אם כופר יושת עליו \u0003ונתן פדיון נפשו\"\u0004 (שמות כא, ל) לומר: מה שמשלם הוא \u0003דמי ניזק, ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר:\u0004 משלם \u0003דמי מזיק.\u0004","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003דרבנן סברי: כופרא ממונא\u0004 \u0005[שחכמים סבורים\u0006 ש\u0005הכופר\u0006 חוב \u0005ממון]\u0006 \u0003הוא\u0004 כמו כל שאר תשלומי נזק, וצריך לשלם ליורשי ההרוג פיצויים על הנזק שנגרם — דמי הניזק, \u0003ור' ישמעאל בנו של ר' יוחנן בן ברוקה סבר\u0004 \u0005[סבור]:\u0006 \u0003כופרא\u0004 \u0005[כופר]\u0006 \u0003כפרה\u0004 הוא, לפי שגרם להרוג נפש, והוא מתחייב בנפשו — מבחינת אחריות בדיני שמים, אבל אינו מומת בבית דין אלא משלם דמי עצמו, ומכפר בכך על מה שחטא?","ודוחים, \u0003אמר רב פפא:\u0004 \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003כופרא\u0004 \u0005[הכופר]\u0006 \u0003כפרה הוא, והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006ענין \u0005זה נחלקו],\u0006 \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003בדניזק שיימינן\u0004 \u0005[מעריכים אנו]\u0006 את סכום הכסף הראוי לשם הכפרה, \u0003ור' ישמעאל בנו של ר' יוחנן בן ברוקה סבר\u0004 \u0005[סבור]:\u0006 \u0003בדמזיק שיימינן\u0004 \u0005[מעריכים אנו]\u0006 את הכפרה, אף שהכל, ואף חכמים, מודים שכפרה היא.","ומסבירים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]?\u0006 \u0003נאמרה\u0004 לשון \u0003\"שיתה\" למטה\u0004 (הלאה) (\"אם כופר יושת עליו\". שמות כא, ל), \u0003ונאמרה\u0004 לשון \u0003\"שיתה\" למעלה\u0004 (מקודם לכן) בחובל אשה הרה וגורם להפלת וולדה (\"ענוש ייענש כאשר ישית עליו בעל האשה\". שמות כא, כב), והרי זה בא להקיש זו לזו: \u0003מה להלן\u0004 כשנותן דמי ולדות מובן כי ההערכה נעשית \u0003בדניזק\u0004 בדמי הוולדות שהוזקו, \u0003אף כאן\u0004 בכופר ההערכה נעשית \u0003בדניזק. ו\u0004אילו","\u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה סבר\u0004 \u0005[סבור]:\u0006 \u0003\"ונתן פדיון נפשו\" כתיב\u0004 \u0005[נאמר],\u0006 משמע — פדיון נפשו של בעל השור.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 משיבים על כך: \u0003אין\u0004 \u0005[כן],\u0006 אמנם \u0003\"פדיון נפשו\" כתיב\u0004 \u0005[נאמר],\u0006 ונועד הדבר לשמש כפרה לבעל השור, \u0003מיהו\u0004 \u0005[ואולם]\u0006 \u0003כי שיימינן\u0004 \u0005[כאשר אנו מעריכים]\u0006 כמה צריך לתת כפדיון נפש — \u0003ב\u0004של \u0003ניזק שיימינן\u0004 \u0005[אנו מעריכים].\u0006","אגב כך מביאים מעשה, היה \u0003משבח ליה\u0004 \u0005[אותו]\u0006 \u0003רבא ל\u0004פני \u0003רב נחמן בדרב\u0004 \u0005[את רב]\u0006 \u0003אחא בר יעקב\u0004 ש\u0003אדם גדול הוא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: לכשיבא לידך,\u0004 כשיזדמן אצלך, \u0003הביאהו לידי\u0004 שיבוא לבקרני.","\u0003כי אתא לגביה\u0004 \u0005[כאשר בא אליו]\u0006 לבסוף רב אחא בר יעקב, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003בעי מינאי מילתא\u0004 \u0005[שאל ממני דבר].\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 שאלה זו: \u0003שור של שני שותפין\u0004 שהרג את הנפש \u0003כיצד משלמין כופר?\u0004","אם תאמר ש\u0003משלם האי\u0004 \u0005[\u0006שותף \u0005זה]\u0006 \u0003כופר\u0004 מלא, \u0003ו\u0004כן \u0003האי\u0004 \u0005[ו\u0006שותף \u0005זה]\u0006 \u0003כופר\u0004 מלא — והלא \u0003כופר אחד אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 שיש לשלם \u0003ולא שני כופרין.\u0004 ואם תאמר כי משלם \u0003האי\u0004 \u0005[\u0006שותף \u0005זה]\u0006 \u0003חצי כופר, והאי\u0004 \u0005[וזה]\u0006 \u0003חצי כופר,\u0004 הרי \u0003כופר שלם אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שיש לשלם \u0003ולא חצי כופר!\u0004","\u0003אדיתיב\u0004 \u0005[עד שישב]\u0006 רב נחמן \u0003וקא מעיין\u0004 \u0005[והיה מעיין]\u0006 \u0003בה,\u0004 בשאלה זו, למצוא לה פתרון, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא בר יעקב שיש לו שאלה נוספת. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003חייבי ערכין,\u0004 מי שהתחייבו בנדר לתת להקדש את ערכם או את ערך חבירם ואין להם לשלם — \u0003ממשכנין אותן,\u0004 שנוטלים מרכושם וממשכנים עד שישלמו. \u0003חייבי חטאות ואשמות\u0004 שנתחייבו להביא קרבן חטאת או אשם, אף שגם הם מחוייבים — \u0003אין ממשכנין אותן\u0004 עד שיביאו קרבנם, שכן סומכים אנו על כך שרצונם להתכפר. ומעתה יש לשאול: \u0003חייבי כופרין\u0004 \u0003מאי\u0004 \u0005[מה\u0006 דינם\u0005]?\u0006","האם נאמר \u0003כיון\u0004 ש\u0003כפרה הוא\u0004, לכן \u0003כחטאת ואשם דמי\u0004 \u0005[נחשב],\u0006 ומכיון שכן \u0003מחמר חמיר עילויה ולא בעי משכוניה\u0004 \u0005[חמור עליו\u0006 הדבר בעיניו \u0005ו\u0006לכן \u0005אין צריך למשכנו]\u0006 כדי להבטיח לנו שישלם כופר זה, כי בוודאי ישתדל בעצמו להגיע לכפרה, גם בלא כפיה זו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלחבריה\u0004 \u0005[שלחבירו]\u0006 \u0003הוא דבעי מיתבא ליה\u0004 \u0005[שצריך לתת לו]\u0006 את הכופר, ואינו כחטאת ואשם שמקריב לשמים, הרי אף הכופר חוב \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003הוא\u0004 בעיניו \u0003ולא לגבוה הוא, ולא חמיר עליה\u0004 \u0005[חמור עליו\u0006\u0005]\u0006 ולא ישתדל לשלם, \u0003ו\u0004לכן \u0003בעי משכוניה\u0004 \u0005[וצריך למשכנו].\u0006","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לתת טעם אחר מדוע אין הכופר חמור בעיניו, כי \u0003כיון\u0004 ש\u0003הוא\u0004 עצמו \u0003לא חטא, וממוניה\u0004 \u0005[ו\u0006רק \u0005ממונו,\u0006 שורו\u0005]\u0006 \u0003הוא דאזיק\u0004 \u0005[שהזיק]\u0006 — \u0003לא חמיר מילתא עילויה, ובעי משכוניה\u0004 \u0005[אין הדבר חמור עליו ו\u0006משום כך \u0005צריך למשכנו]\u0006 שישלם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003שבקן, אסתגר בקמייתא\u0004 \u0005[הנח לי,\u0006 הרי \u0005נסגרתי ב\u0006שאלה \u0005הראשונה]\u0006 ואיני מוצא לה פתרון, ואינך צריך לשאול אותי שאלות קשות נוספות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אף שהשואל שור מחבירו הריהו מתחייב באחריות נזקיו, אם \u0003שאלו\u0004 \u0003בחזקת\u0004 שהוא \u0003תם, ונמצא\u0004 השור \u0003מועד,\u0004 ונגח והזיק — \u0003בעלים משלמין חצי נזק, ושואל\u0004 \u0003משלם חצי נזק.\u0004","\u0003הועד\u0004 השור \u0003בבית שואל\u0004 שנגח בהיותו שם שלוש פעמים והעידו בו בפני בית דין, \u0003והחזירו לבעלים\u0004 ואחר כך נגח — \u0003בעלים משלמין חצי נזק\u0004 שהרי לא אצלם הועד, ולגביהם הוא עדיין תם, \u0003ושואל\u0004 — \u0003פטור מכלום,\u0004 שהרי אין עוד השור ברשותו. ומעתה מבארים את פרטי הדברים.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003שאלו בחזקת\u0004 שהוא \u0003תם ונמצא\u0004 שהוא \u0003מועד\u0004 — \u0003בעלים משלמין חצי נזק, ושואל\u0004 — \u0003חצי נזק.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 ישלם השואל בכלל? \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 למשאיל: \u0003תורא שאילי\u0004 \u0005[שור שאלתי],\u0006 \u0003אריא\u0004 \u0005[אריה]\u0006 \u0003לא שאילי\u0004 \u0005[שאלתי]\u0006 ולא ידעתי שמועד הוא והריהו כארי טורף, ולא קיבלתי עלי כלל שמירה של שור כזה!","\u0003אמר רב: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003שהכיר בו\u0004 השואל \u0003שהוא נגחן,\u0004 ונמצא שבשעת שאילה ידע שהוא עלול להזיק.","ומקשים עוד: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 השואל לבעלים: אף שידעתי שהוא נגחן, מכל מקום \u0003תם שאילי\u0004 \u0005[שאלתי]\u0006 \u0003מועד לא שאילי\u0004 \u0005[שאלתי],\u0006 ולא קיבלתי עלי שמירה של שור מועד, שמשלמים עליו נזק שלם!","ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הבעלים: \u0003סוף סוף אי\u0004 \u0005[אם]\u0006 \u0003תם הוה\u0004 \u0005[היה]\u0006 — בכל זאת \u0003פלגא נזקא בעית שלומי\u0004 \u0005[חצי נזק\u0006 היית \u0005צריך לשלם],\u0006 \u0003השתא נמי זיל שלים פלגא נזקא\u0004 \u0005[עכשיו גם כן לך שלם חצי נזק].\u0006","ושואלים: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 השואל למשאיל: \u0003אי\u0004 \u0005[אם]\u0006 \u0003תם הוה\u0004 \u0005[היה]\u0006 הרי הנזק בתם \u0003משתלם מגופו\u0004 של השור המזיק, ואני לא הייתי צריך לשלם מממוני!","ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל השור: \u0003סוף סוף, את לאו תורא בעית שלומי לדידי\u0004 \u0005[אתה,\u0006 וכי \u0005לא שור\u0006 שלם היית \u0005צריך לשלם לי]?\u0006 שהרי כשואל היה עליך להחזיר לי את השור בשלימותו, ואם היו גובים מגופו היה עליך להחזיר לי שור שלם, ונמצא שבכל מקרה היה עליך תשלום נזק זה, ואם כן אינך מפסיד יותר כאשר השור מועד.","ושואלים: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 השואל:"],["\u0003אם תם\u0004 השור — \u0003הוה מודינא ומפטרינא\u0004 \u0005[הייתי מודה ונפטר]!\u0006 שהרי כלל הוא שהמודה בקנס פטור, שאין משלמים את הקנס אלא על פי עדים, וחצי נזק של תם קנס הוא. ועכשיו שמועד הוא — איני יכול להיפטר בדין זה!","ומוסיפים: \u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003פלגא נזקא ממונא\u0004 \u0005[חצי נזק ממון]\u0006 הוא, ולא קנס, ואינו נפטר על ידי הודאה, \u0003נימא ליה\u0004 \u0005[שיאמר לו\u0006 השואל\u0005]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003תם הוא\u0004 השור — \u0003הוה מעריקנא ליה לאגמא\u0004 \u0005[הייתי מבריח אותו לאגם]\u0006 שלא ימצאו אותו בידי, ולא היו יכולים לגבות את הנזק, שהרי אינו נגבה אלא מגוף השור! אבל שור מועד שאין גובים מגופו אלא מרכוש בעליו אין כל תועלת בהברחתו כדי להיפטר. ולפי זה לכאורה יש לשואל טענות טובות לפטור עצמו מן התשלום, ומדוע משלם הוא חצי נזק?","\u0003אלא\u0004 שיש להסביר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון דאקדים בי דינא ותפסיה\u0004 \u0005[שהקדים בית הדין ותפסו\u0006 את השור לגבות ממנו\u0005]\u0006 קודם שהודה הוא בעצמו בדבר, וקודם שיכול היה להבריחו לאגם. ובמקרה כזה אין השואל יכול לטעון דבר לפוטרו מתשלום.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שבמקרה כזה מדובר, \u0003בעלים אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלמים חצי נזק? נימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הבית לשואל: \u0003אתפסתיה לתוראי בידא מאן דלא מצינא לאשתעויי דינא בהדיה\u0004 \u0005[התפסת\u0006 מסרת \u0005את שורי בידי מי שאיני יכול להתדיין עמו],\u0006 שכיון שהשור נמצא ברשות בית דין אינני יכול שוב להתמקח ולהתפשר, אלא הם יגבו הכל, ואתה הוא שגרמת לכך שאצטרך לשלם! ומתרצים: \u0003משום דאמר ליה\u0004 \u0005[ש\u0006יכול היה השואל \u0005לומר לו]:\u0006 \u0003אי אהדרתיה ניהלך, לאו מינך הוו שקלי ליה\u0004 \u0005[אילו הייתי מחזיר אותו לך,\u0006 וכי \u0005לא ממך היו לוקחים אותו]?!\u0006 ואם כן לא עשיתי דבר.","ושואלים: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 המשאיל בתשובה לטענה זו: \u0003אי אהדרתיה ניהליה, הוה מעריקנא ליה לאגמא\u0004 \u0005[אילו היית מחזיר אותו לי, הייתי מבריח אותו לאגם]\u0006 ולא היו יכולים לקחתו! ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[ש\u0006היה יכול \u0005לומר לו]\u0006 השואל: \u0003סוף סוף, לאו\u0004 \u0005[\u0006וכי \u0005לא]\u0006 \u0003מעלייה\u0004 מן הנכסים שלך. \u0003הוו משתלמי\u0004 \u0005[היו\u0006 מקבלים את \u0005התשלום]?\u0006 שהרי מועד משלם מן העלייה ולא מגופו.","ושואלים: \u0003הניחא היכא דאית ליה נכסי\u0004 \u0005[זה נוח כשיש לו נכסים]\u0006 לבעל הבית חוץ מן השור, ואז אפשר לגבות מרכושו, ואולם \u0003היכא דלית ליה נכסי, מאי איכא למימר\u0004 \u0005[היכן שאין לו נכסים, מה יש לומר]?\u0006 הרי גרם לו השואל נזק!","ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[ש\u0006היה יכול \u0005לומר לו]\u0006 השואל: \u0003כי היכא דמשתעבדנא לדידך, הכי נמי משתעבדנא להאיך\u0004 \u0005[כשם שאני משועבד לך\u0006 בחובה להחזיר לך את המגיע לך, \u0005כך גם כן משועבד אני לזה\u0006 הניזק\u0005]\u0006 שאתה חייב לו כסף, \u0003מ\u0004דברי \u0003ר' נתן.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: מנין לנושה בחבירו\u0004 חוב של \u0003מנה, וחבירו\u0004 גם כן נושה \u0003בחבירו\u0004 מנה, \u0003מנין שמוציאין מזה,\u0004 מן הלווה האחרון, \u0003ונותנים לזה,\u0004 למלווה הראשון, ואין צורך להחזיר ללווה השני כדי שהוא עצמו יחזיר למלווה — \u0003תלמוד לומר\u0004 בקשר להשבת גזילה: \u0003\"ונתן לאשר אשם לו\"\u0004 (במדבר ה, ז), כלומר, יש שהגזלן (או מי שחייב דבר לחבירו) משיבו למי שהבעלים חייב לו דבר (\"לאשר אשם לו\").","עוד שנינו בברייתא: אם \u0003הועד\u0004 השור \u0003בבית\u0004 ה\u0003שואל והחזירו לבעלים\u0004 והזיק שם — ה\u0003בעלים משלמין חצי נזק, ושואל פטור מכלום.\u0004","ומתקשים: ב\u0003סיפא\u0004 \u0005[סופה]\u0006 של הברייתא למדים אנו כי \u0003רשות משנה,\u0004 שאם הועד השור ברשות אחרת, וחוזר לרשות בעליו — אינו נחשב כמועד, ולכן משלמים על נזק שור זה רק חצי נזק. ואילו ב\u0003רישא\u0004 \u0005[\u0006ב\u0005ראש]\u0006 של אותה ברייתא, כאשר הועד בבית הבעלים והזיק בבית השואל, למדים אנו כי \u0003רשות אינה משנה,\u0004 שהרי משלמים על נזקו נזק שלם!","\u0003אמר ר' יוחנן: תברא\u0004 \u0005[שבורה\u0006 חצויה\u0005]\u0006 היא משנה זו, ואינה כשיטה אחת, אלא \u0003מי ששנה זו לא שנה זו\u0004 וכל פיסקה נאמרה לפי שיטה אחרת.","\u0003רבה אמר: מדרישא\u0004 \u0005[מכיון ש\u0006ב\u0005תחילתה\u0006 של הברייתא\u0005]\u0006 \u0003רשות אינה משנה\u0004 — \u0003סיפא נמי\u0004 \u0005[\u0006ב\u0005סופה גם כן]\u0006 \u0003רשות אינה משנה. וסיפא היינו טעמא\u0004 \u0005[ו\u0006ב\u0005סופה זהו הטעם]\u0006 שחוזר לתמותו — \u0003משום דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 בעל הבית לשואל: \u0003לאו כל כמינך דמייעדת ליה לתוראי\u0004 \u0005[אין זה בכוחך לעשות את שורי מועד],\u0006 שלא לשם כך נתתיו לך, ואתה הוא שפשעת בו. ולכן אין בעל הבית חייב לשלם על נזקים שבאו מחמת שואל זה.","\u0003רב פפא אמר\u0004 להיפך: \u0003מדסיפא\u0004 \u0005[מכיון ש\u0006ב\u0005סופה]\u0006 של הברייתא \u0003רשות משנה, רישא נמי\u0004 \u0005[\u0006ב\u0005ראשה גם כן]\u0006 יש להבין ש\u0003רשות משנה, ורישא היינו טעמא\u0004 \u0005[ו\u0006ב\u0005תחילה זהו הטעם]\u0006 שהשור ממשיך להיות מועד גם בבית השומר, \u0003משום\u0004 ש\u0003כל מקום שהולך\u0004 — \u0003שם בעליו עליו,\u0004 והרי הועד השור בבעליו (ראה שמות כא, כט), ואינו מופקע מרשות בעליו על ידי ההשאלה.","שנינו במשנה כי \u0003שור\u0004 \u0003האצטדין אינו חייב מיתה,\u0004 כיון שאחרים גורמים לו שיגח. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: שור רגיל שהרג אדם (ולא נסקל בבית דין) דינו שאינו קרב על גבי המזבח, ואולם שור האצטדין שהרג את האדם, \u0003מהו\u0004 דינו \u0003לגבי\u0004 \u0005[אצל,\u0006 לענין\u0005]\u0006 \u0003מזבח,\u0004 האם כשר הוא להקריבו כקרבן?","\u0003רב אמר: כשר, ושמואל אמר: פסול.\u0004 ומפרטים: \u0003רב אמר כשר\u0004 משום שלדעתו \u0003אנוס הוא\u0004 השור, במה שהרג אדם, שכך לימדוהו. \u0003ושמואל אמר פסול,\u0004 כי מכל מקום \u0003הרי נעבד בו עבירה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו על הכתוב \"מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\" (ויקרא א, ב): הביטוי \u0003\"מן הבהמה\"\u0004 בא \u0003להוציא\u0004 מכלל המובאים לקרבן \u0003את\u0004 בעל החיים \u0003הרובע\u0004 אשה \u0003ואת הנרבע\u0004 לאדם, \u0003\"מן הבקר\"\u0004 — בא \u0003להוציא את הנעבד\u0004 כעבודה זרה, \u0003\"\u0004ו\u0003מן הצאן\"\u0004 — \u0003להוציא את המוקצה\u0004 שהקצוהו = ייחדוהו לעבודה זרה, \u0003\"ומן הצאן\"\u0004 שיש בו מיעוט נוסף בגלל הוא\"ו הנוספת — \u0003להוציא את הנוגח.\u0004","\u0003אמר ר' שמעון: אם נאמר\u0004 מיעוט בתורה לענין \u0003רובע למה נאמר\u0004 עוד מיעוט לענין \u0003נוגח, ואם נאמר\u0004 מיעוט ל\u0003נוגח למה נאמר\u0004 עוד מיעוט לענין \u0003רובע?\u0004 הלא שניהם שווים בכך שעשו מעשים שבגללם הורגים אותם!","ומסבירים: \u0003מפני שיש ברובע\u0004 חומר \u0003שאין בנוגח, ויש בנוגח שאין ברובע.\u0004","\u0003רובע עשה בו אונס כרצון,\u0004 שגם אם הבהמה הנרבעת לא עשתה דבר זה מרצונה, מכל מקום דינה כעושה זאת מרצון, ואילו \u0003נוגח לא עשה בו אונס כרצון,\u0004 שכן שור שנגח לאונסו פטור. ומצד אחר \u0003נוגח\u0004 — \u0003משלם\u0004 בעליו \u0003כופר, רובע\u0004 והרג אדם — \u0003אינו משלם את הכופר. לפיכך הוצרך לומר רובע והוצרך לומר נוגח.\u0004","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]:\u0006 \u0003רובע\u0004 — \u0003עשה בו אונס כרצון, נוגח\u0004 — \u0003לא עשה בו אונס כרצון. למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003לאו\u0004 \u0005[האם לא\u0006 נאמר\u0005]\u0006 \u0003ל\u0004ענין \u0003קרבן,\u0004 ששור האצטדין שדינו כאנוס, שהרי הביאוהו לידי כך — כשר, וכדברי רב?","ודוחים: \u0003לא,\u0004 שם מדובר \u0003לקטלא\u0004 \u0005[ל\u0006ענין \u0005מיתה],\u0006 שאין ממיתים אותו אם הרג באונס.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להבין את הענין, \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שמדובר כאן \u0003לקרבן,\u0004 ואומרת הברייתא כי אם היה כתוב רק פסול רובע לא היינו למדים לנוגח, כי \u0003נוגח לא עשה בו אונס כרצון\u0004 — הרי \u0003לאו\u0004 \u0005[לא]\u0006 ה\u0003אונס דידיה כתיב\u0004 \u0005[שלו שנאמר]\u0006 \u0003ולאו\u0004 \u0005[ולא]\u0006 ה\u0003רצון דידיה כתיב\u0004 \u0005[שלו נאמר]\u0006 לענין פסול לקרבן, שהרי הדבר לא נתפרש בכתוב כלל! \u0003אלא לאו לקטלא\u0004 \u0005[האם לא\u0006 מדובר \u0005ל\u0006ענין \u0005מיתה]\u0006 שנאמרה במקרא, ונתפרש בה שיש חילוק בין אונס ורצון, כפי שנאמר במשנה: \"כי יגח\" — ולא שיגיחוהו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003נוגח\u0004 — \u0003משלם את הכופר, רובע\u0004 — \u0003אינו משלם את הכופר.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 בו לא יתחייב בעליו של הרובע בכופר? \u0003אילימא\u0004 \u0005[אם לומר]\u0006 ש\u0003רבעה וקטלה\u0004 \u0005[והרגה]\u0006 תוך כדי רביעה — \u0003מה לי\u0004 אם \u0003קטלה בקרנא\u0004 \u0005[הרגה בקרן]\u0006 \u0003מה לי\u0004 אם \u0003קטלה\u0004 \u0005[הרגה]\u0006 \u0003ברביעה!\u0004","\u0003ואלא\u0004 תאמר ש\u0003רבעה ולא קטלה\u0004 \u0005[הרגה],\u0006 אם כן \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003לא משלם כופר משום\u0004 ש\u0003לא קטלה\u0004 \u0005[הרגה]\u0006 \u0003הוא,\u0004 ולא מפני ההבדל בין רביעה להריגה!","\u0003אמר אביי: לעולם\u0004 תפרש ש\u0003רבעה ולא קטלה\u0004 \u0005[הרגה],\u0006 \u0003דאתיוה לבי דינא וקטלוה\u0004 \u0005[שהביאוה\u0006 את האשה הנרבעת \u0005לבית דין והרגוה]\u0006 בגלל עבירה זו, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006"],["\u0003כמאן דקטלה דמי\u0004 \u0005[כמי שהרגה נחשב]\u0006 שהרי בגלל בהמה זו נגרמה הריגתה של האשה, ויתחייב בעליו כופר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו כן.","\u0003רבא אמר: לעולם\u0004 תפרש ש\u0003רבעה וקטלה\u0004 \u0005[והרגה]\u0006 בעצם הרביעה, \u0003ודקא קשיא\u0004 \u0005[ומה שהיה קשה]\u0006 \u0003לך: מה לי קטלה\u0004 \u0005[הרגה]\u0006 \u0003בקרנים מה לי קטלה\u0004 \u0005[הרגה]\u0006 \u0003ברביעה\u0004 — יש לתרץ: \u0003קרן\u0004 כשנוגח \u0003כוונתו להזיק, האי\u0004 \u0005[זה]\u0006 הרובע \u0003כוונתו להנאת עצמו הוא.\u0004","ושואלים: \u0003במאי פליגי\u0004 \u0005[במה נחלקו],\u0006 כלומר, מה הן המסקנות השונות הנובעות משני הסברים אלה? ומשיבים: \u0003ב\u0004מקרה של \u0003רגל שדרסה על גבי תינוק בחצר הניזק\u0004 והרגתו, יש הבדל בין שני ההסברים: \u0003ל\u0004דעת \u0003אביי\u0004 — \u0003משלם כופר,\u0004 שהרי מדבריו עולה שכופר משלם בכל מקרה שהרג, גם אם לא היתה כוונתו להזיק, ו\u0003ל\u0004דעת \u0003רבא\u0004 — \u0003לא משלם כופר.\u0004","ולעיקר מחלוקת רב ושמואל מעירים, \u0003תניא כוותיה דרב\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006שיטתו \u0005של רב]:\u0006 \u0003שור האיצטדין\u0004 שהרג אדם — \u0003אינו חייב מיתה, וכשר לגבי מזבח, מפני שהוא כמעושה\u0004 כמי שהוא אנוס לעשות את מה שהוא עושה.","\u0003שור שנגח את האדם ומת\u0004 האדם, אם היה השור \u0003מועד\u0004 — \u0003משלם\u0004 בעל השור \u0003כופר, ותם\u0004 — \u0003פטור מן הכופר. ו\u0004מכל מקום \u0003זה וזה\u0004 (שור מועד ושור תם) \u0003חייבין מיתה\u0004 על שהרגו את הנפש. \u0003וכן\u0004 הוא הדין \u0003בבן\u0004 (ילד), \u0003וכן בבת\u0004 (ילדה) אם הרגם השור. \u0003נגח\u0004 השור \u0003עבד או אמה\u0004 ומתו — \u0003נותן\u0004 לבעליו \u0003שלשים סלעים,\u0004 \u0003בין שהוא\u0004 העבד \u0003יפה\u0004 (שווה) \u0003מאה מנה\u0004 (מטבע של מאה דינרי כסף) \u0003ובין שאינו יפה אלא דינר אחד.\u0004","ושואלים: \u0003וכי מאחר דמתם קטלינן ליה\u0004 \u0005[ש\u0006כבר \u0005מ\u0006היותו \u0005תם הורגים אנו אותו]\u0006 אם הרג אדם, אפשרות זו של \u0003מועד\u0004 שהרג אדם \u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה\u0006 אותה\u0005]?\u0006","\u0003אמר רבה: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה \u0003כגון שאמדוהו לשלשה בני אדם,\u0004 שהשור תקף שלושה בני אדם, באופן שאנו מעריכים שאם לא היו נמלטים ממנו בוודאי היה הורגם.","\u0003רב אשי אמר: אומדנא לאו\u0004 \u0005[אומדן לא]\u0006 \u0003כלום הוא,\u0004 כיוון שבפועל לא הרגם, ואין יכולים לראותו כשור מועד רק מפני שהתכוון לכך. \u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שסיכן,\u0004 שנגח והביא עד לסכנת מוות \u0003לשלשה בני אדם,\u0004 אבל עדיין לא מתו עד לאחר שננגח השלישי, ולכן עדיין לא הומת השור.","\u0003רב זביד אמר:\u0004 כאן מדובר \u0003כגון שהרג שלשה בהמות,\u0004 והרי הוא מועד, ואינו מומת על כך.","ותוהים: \u0003ו\u0004כי \u0003מועד לבהמה הוי\u0004 \u0005[הריהו]\u0006 \u0003מועד לאדם?\u0004 הרי בזה אין אף אחד חולק שאינו מועד! \u0003אלא אמר רב שימי: כגון שהרג שלשה גוים.\u0004","ותמהים: \u0003ו\u0004כי \u0003מועד לגוים הוי\u0004 \u0005[הריהו]\u0006 \u0003מועד לישראל? אלא אמר ר' שמעון בן לקיש: כגון שהרג שלשה בני אדם טרפה,\u0004 שאותם בני אדם (מישראל) היו חולים או פצועים באופן שברור שימותו תוך זמן קצר, ולכן אין השור נידון למוות לפי שאין המתתם נחשבת כהריגה ממש, ומכל מקום הרי נתברר שהוא מועד לנגוח ולהרוג בני אדם.","ותמהים: \u0003ומועד לטרפה הוי\u0004 \u0005[הריהו]\u0006 \u0003מועד ל\u0004אדם \u0003שלם? אלא אמר רב פפא:\u0004 מדובר כאן במקרה ש\u0003קטל וערק לאגמא\u0004 \u0005[שהרג וברח לאגם],\u0006 ש\u0003קטל וערק לאגמא\u0004 \u0005[שהרג וברח לאגם]\u0006 כך שנעשה השור מועד, אבל לא הצליחו לתפסו עד לאחר שהרג בהיותו מועד.","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: כגון שהוזמו זוממי זוממין,\u0004 כלומר, שהעדים שהעידו על שלוש הנגיחות הראשונות הוזמו, ולכן לא הומת השור על פי עדותם, ולבסוף באו עדים שהעידו שהעדים שהזימו את הראשונים עדי שקר היו, כך שכל העדויות הראשונות חזרו ואושרו בבת אחת, ונמצא השור מועד עכשיו.","ושואלים: אפשרות זו לעשות את השור מועד לאדם כשהוזמו המזימים, \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 אנו מניחים כי \u0003לייעודי תורא בעינן\u0004 \u0005[לעשות את השור מועד אנו רוצים]\u0006 בהעדה על הנגיחות — \u0003שפיר\u0004 \u0005[יפה]\u0006 שנתברר שאכן נגח שלוש פעמים. \u0003אלא אי לייעודי גברא בעינן\u0004 \u0005[אם\u0006 בהעדה של השור \u0005לעשות את האדם,\u0006 בעל השור, \u0005מועד אנו רוצים]\u0006, \u0003מימר אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 לדיין, כאשר מתברר ששורו נגח כשהוא מועד: \u0003לא הוה ידענא\u0004 \u0005[ידעתי]\u0006 שהועד שורי, כי העדים הראשונים הוזמו בשעתם! ומשיבים: \u0003כגון דאמרי\u0004 \u0005[שאומרים]\u0006 העדים: \u0003כל אימת דקטיל תוריה, גביה הוה קאי\u0004 \u0005[כל\u0006 פעם \u0005שהרג שורו,\u0006 הוא \u0005היה עומד לידו]\u0006 ובוודאי ידע.","\u0003רבינא אמר:\u0004 מדובר כאן \u0003במכירין\u0004 העדים \u0003את בעל השור ואין מכירין את השור,\u0004 שבנגיחות הראשונות העידו ששורו נגח אך לא העידו בשור עצמו, ולכן לא הומת עדיין השור, ולבסוף הכירו שהוא השור שכבר נגח כמה פעמים.","ושואלים: אם כן מדוע הוא מועד? \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]?\u0006 שהרי אין הבעלים יודע איזה הוא השור הנגח! ומשיבים: \u0003משום דאמרי ליה\u0004 \u0005[שאומרים לו]:\u0006 \u0003תורא נגחנא אית\u0004 \u0005[שור נגחן יש]\u0006 \u0003לך בבקרך\u0004 \u0005[בעדרך]\u0006 \u0003איבעי לך נטורי כולי בקרך\u0004 \u0005[צריך אתה לשמור\u0006 את \u0005כל עדרך].\u0006","שנינו במשנה: \u0003וזה וזה חייבין מיתה כו'.\u0004 ובענין זה מוסיפים: נאמר בתורה על שור הנוגח אדם: \"סקול יסקל השור, ולא יאכל את בשרו, ובעל השור נקי\" (שמות כא, כח), ועל כך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ממשמע שנאמר \"סקל יסקל השור\" איני יודע שנבילה היא,\u0004 שהרי נסקל ולא נשחט, \u0003ו\u0004הרי \u0003נבילה אסורה באכילה, מה תלמוד לומר\u0004 \u0003\"\u0004ו\u0003לא יאכל את בשרו\"?\u0004 אלא \u0003מגיד לך הכתוב שאם שחטו\u0004 שחיטה כשרה \u0003לאחר שנגמר דינו\u0004 אף שלא נסקל — מכל מקום \u0003אסור באכילה.\u0004","\u0003אין לי אלא\u0004 ששור זה אסור \u0003באכילה,\u0004 שאסור \u0003בהנאה מנין? תלמוד לומר \"ובעל השור נקי\".\u0004","ושואלים: \u0003מאי משמע?\u0004 \u0005[מה המשמעות],\u0006 כיצד נובעת מן המילים משמעות זו? \u0003שמעון בן זומא אומר: כאדם שאומר לחבירו \"יצא איש פלוני נקי מנכסיו ואין לו בהם הנאה של כלום\",\u0004 אף כאן פירוש \"נקי\" הוא שאין לבעל השור כל הנאה משור זה.","ושואלים: \u0003וממאי\u0004 \u0005[וממה,\u0006 ומנין\u0005]\u0006 יודעים אנו שהלשון \u0003\"\u0004ו\u0003לא יאכל את בשרו\"\u0004 באה \u0003להיכא\u0004 \u0005[להיכן,\u0006 למקרה\u0005]\u0006 ש\u0003שחטו אחר שנגמר דינו\u0004 ולהשמיענו \u0003שאסור באכילה? אימא דהיכא\u0004 \u0005[אמור שהיכן]\u0006 ש\u0003שחטו לאחר שנגמר דינו\u0004 — \u0003שרי\u0004 \u0005[מותר]\u0006 \u0003באכילה הוא, והאי\u0004 \u0005[ו\u0006כתוב \u0005זה]\u0006 \"ו \u0003לא יאכל את בשרו\" להיכא דסקליה מסקל\u0004 \u0005[להיכן שסקלוהו בסקילה],\u0006 לומר ש\u0003אסור בהנאה הוא,\u0004 ו\u0003כ\u0004דברי \u0003ר' אבהו,\u0004 ש","\u0003אמר ר' אבהו אמר ר' אלעזר: כל מקום שנאמר\u0004 בתורה \u0003\"לא יאכל\"\u0004 או \u0003\"לא תאכל\"\u0004 או \u0003\"לא תאכלו\"\u0004 — \u0003אחד איסור אכילה ואחד איסור הנאה במשמע,\u0004","\u0003עד שיפרט לך הכתוב\u0004 ויפרש שמותר ליהנות ממנו, \u0003כדרך שפרט לך בנבילה: לגר בנתינה, ולגוי במכירה!\u0004 שלאחר שנאמר \"לא תאכלו כל נבלה\" (דברים יד, כא), הוסיפה התורה היתר מפורש בהנאה: \"לגר אשר בשעריך תתננה ואכלה, או מכור לנכרי\", ומשמע מכאן שללא היתר מפורש זה אסור היה הדבר אף בהנאה כיון שנאמר \"לא תאכלו\".","ודוחים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 של ר' אבהו, אמורים \u0003היכא דנפיק ליה\u0004 \u0005[היכן שיוצא לו]\u0006 \u0003איסור אכילה ואיסור הנאה\u0004 שניהם \u0003מקרא\u0004 \u0005[מפסוק]\u0006 \u0003מ\u0004ביטוי כגון \u0003\"לא יאכל\", אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003איסור אכילה\u0004 עצמו \u0003מ\"סקל יסקל\" נפקא\u0004 \u0005[יוצא],\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר כי \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"לא יאכל את בשרו\"\u0004 לענין \u0003איסור הנאה\u0004 בלבד \u0003הוא,\u0004 אם כן \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 במפורש: \u0003\"לא יהנה\". אי נמי\u0004 \u0005[או גם כן]\u0006 שייכתב רק \u0003\"לא יאכל\",\u0004 המילים \u0003\"את בשרו\" למה לי?\u0004 אלא בא הכתוב לומר \u0003דאף על גב דעבדיה\u0004 \u0005[שאף על פי שעשה אותו]\u0006 \u0003כעין בשר, דשחטיה\u0004 \u0005[ששחטו]\u0006 לאחר שנידון לסקילה, והוכשר לאכילה — מכל מקום \u0003אסור\u0004 באכילה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא: אימא הני מילי\u0004 \u0005[אמור\u0006 ש\u0005דברים אלה\u0006 אמורים\u0005]\u0006"],["\u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003בדק\u0004 אבן \u0003צור\u0004 ומצא שאין בה פגימות \u0003ושחט בו,\u0004 שאפשר לומר אז \u0003דעבדיה\u0004 \u0005[שעשה אותו],\u0006 שקיים בשור, \u0003כעין סקילה,\u0004 שלכאורה מה לי אם הרגו בזריקת אבן עליו או בשחיטתו באבן. \u0003אבל היכא דשחטיה\u0004 \u0005[היכן ששחטו]\u0006 \u0003בסכין\u0004 שהיא של מתכת — \u0003לא\u0004 יהיה אסור בהנאה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחייה: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003סכין כתיבא באורייתא\u0004 \u0005[כתובה בתורה]?\u0006 וכי מפורש ששחיטה צריכה להיות דווקא בסכין, שרצונך להבחין בין שחיטה בצור או בסכין? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003השוחט במגל יד\u0004 או \u0003ב\u0004אבן \u0003צור ו\u0004כן \u0003בקנה\u0004 — \u0003שחיטתו כשירה\u0004 אם היו אלה חלקים וראויים לשחיטה.","ושואלים: \u0003ו\u0004לשיטת ר' אבהו \u0003השתא דנפקא ליה\u0004 \u0005[עכשיו שיוצא לו,\u0006 שהוא לומד\u0005]\u0006 \u0003איסור אכילה ואיסור הנאה מ\"\u0004 ו\u0003לא יאכל את בשרו\"\u0004 (שמות כא, כח), אם כן \u0003\"\u0004ו\u0003בעל השור נקי\"\u0004 (שמות כא, כח) \u0003למה לי?\u0004 ומשיבים: דבר זה בא ללמד \u0003ל\u0004אסור \u0003הנאת עורו. דסלקא דעתך אמינא\u0004 \u0005[ש\u0006כן \u0005יעלה על דעתך לומר]:\u0006 דווקא \u0003בשרו הוא\u0004 ש\u0003אסור בהנאה\u0004 כאמור \"לא יאכל את בשרו\", אבל \u0003עורו נשתרי\u0004 \u0005[יהא מותר]\u0006 \u0003בהנאה,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב \u0003\"\u0004ו\u0003בעל השור נקי\"\u0004 שאסור ליהנות מהשור כולו.","ושואלים: \u0003ולהנך תנאי דמפקי ליה להאי\u0004 \u0005[ולאותם התנאים המוציאים אותו, את\u0006 הביטוי \u0005הזה]\u0006 \u0003\"בעל השור נקי\" לדרשה אחרינא\u0004 \u0005[אחרת],\u0006 \u0003[כדבעינן למימר קמן\u0004 \u0005[כפי שאנו רוצים לומר הלאה]\u0006\u0003],\u0004 דין זה של איסור \u0003הנאת עורו מנא להו\u0004 \u0005[מנין להם]?\u0006","ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם]\u0006 הדבר מן הביטוי \u0003\"את בשרו\",\u0004 \"את\" זו לשון ריבוי היא, ובאה לרבות \u0003את הטפל לבשרו,\u0004 שאף הוא אסור בהנאה, \u0003מאי ניהו\u0004 \u0005[ומה הוא]\u0006 זה — \u0003עורו.\u0004","ומסבירים: \u0003והאי תנא\u0004 \u0005[ותנא זה]\u0006 שאינו לומד כך, אלא מ\"בעל השור נקי\" — \u0003\"את\" לא דריש\u0004 \u0005[דורש],\u0006 שאינו סבור ש\"את\" היא לשון ריבוי.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שמעון העמסוני, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003נחמיה העמסוני, היה דורש כל \"אתין\" שבתורה\u0004 (כל מקום שכתוב בה \"את\") ולומד מהם לרבות דבר נוסף, \u0003כיון שהגיע ל\"את ה' אלהיך תירא\"\u0004 (דברים ו, יג) \u0003פירש\u0004 (חדל), שלא מצא מקום לדרוש ולהוסיף דבר שיש לירוא אותו כמו יראה את ה', ולכן הפסיק לדרוש עוד באופן זה. \u0003אמרו לו תלמידיו: רבי, כל\u0004 אותן דרשות \u0003\"אתין\" שדרשת\u0004 עד עתה \u0003מה תהא עליהן? אמר להם: כשם שקבלתי שכר על הדרישה\u0004 שדרשתי, \u0003כך קבלתי שכר על הפרישה,\u0004 שאני פורש מלדרוש. ואם כן, שיטתו האחרונה היא שאין דורשים \"את\" לרבות.","ומוסיפים: ולא היה חכם שיכול היה להסביר מה יכול \"את\" זה לרבות, \u0003עד שבא ר' עקיבא ולימד: \"את ה' אלהיך תירא\",\u0004 \"את\" זה בא \u0003לרבות תלמידי חכמים,\u0004 שיהא מורא רבו כמורא שמים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \u0003\"ובעל השור נקי\"\u0004 האמור בשור שהרג אדם, \u0003ר' אליעזר אומר:\u0004 כוונתו ש\u0003נקי\u0004 (פטור) מלשלם \u0003חצי כופר,\u0004 שאף על פי שתם שהזיק משלם מחצית הנזק, מכל מקום תם שהרג אדם אינו משלם כופר כלל.","\u0003אמר לו ר' עקיבא:\u0004 מה צורך לכתוב מיוחד בענין זה? \u0003והלא הוא עצמו\u0004 תם \u0003אין משתלם\u0004 כל נזקיו \u0003אלא מגופו,\u0004 ואף כאן יכול בעל השור לומר \u0003\"הביאהו לבית דין וישלם לך\",\u0004 ומשום שהשור נסקל — ממילא אין ממה לקבל תשלום. ולפי זה אין צורך בכתוב מיוחד שישמיענו דין זה, שהרי אין כל חידוש בדבר!","\u0003אמר לו ר' אליעזר: כך אני בעיניך, שדיני,\u0004 מה שאני לומד ודן מן הכתוב, הוא \u0003בזה\u0004 באותו שור \u0003שחייב מיתה?\u0004 ברור שבכגון זה אין צריך לכתוב מפורש. \u0003אין דיני אלא כ\u0004שיודעים אנו \u0003שהמית\u0004 השור \u0003את האדם על פי\u0004 עדותו של \u0003עד אחד או על פי\u0004 הודאתם של ה\u0003בעלים,\u0004 שאין די בעדות זו כדי לסוקלו, והיה איפוא מקום לחייבו בכופר.","ותוהים: אם \u0003על פי בעלים\u0004 הוא — אם כן אינו מתחייב כלל בכופר, שהרי \u0003מודה בקנס הוא,\u0004 והלכה היא שמודה בקנס פטור, ולשם מה נצרך כתוב מיוחד להשמיענו שפטור?!","ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 ר' אליעזר כי \u0003כופרא\u0004 \u0005[הכופר]\u0006 שניתן על הריגת שור אדם לשם \u0003כפרה\u0004 הוא ניתן, ואינו נחשב כתשלום קנס. ולכן יכול הייתי לומר שגם במקרה שאין עדות מלאה משלם כופר כדי שתהיה לו כפרה, ולכן היה צורך ללימוד מיוחד שהתם אינו משלם חצי כופר.","ומביאים, \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו ענין: \u0003אמר לו ר' אליעזר: עקיבא, כך אני בעיניך, שדיני בזה שחייב מיתה? אין דיני אלא במתכוון\u0004 השור \u0003להרוג את הבהמה והרג את האדם,\u0004 או במתכוון \u0003לגוי והרג ישראל,\u0004 או במתכוון \u0003לנפלים והרג בן קיימא.\u0004 שכיון שמתכוון למי שאין בו דין מיתה — אי אפשר לסוקלו על מה שעשה בפועל, שכן אין השור מתחייב אלא כשמזיק בכוונה, ואולם בכל זאת הרג אדם מישראל, ולכן הוצרך לומר שפטור מלשלם חצי כופר.","שתי ברייתות אלה מביאות שתי תשובות שונות שענה ר' אליעזר לר' עקיבא, וכיון שאמר לו שני דברים, השאלה היא: \u0003הי\u0004 \u0005[איזה]\u0006 מן ההסברים \u0003אמר ליה ברישא\u0004 \u0005[לו מתחילה]?\u0006 \u0003רב כהנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר:\u0004 את ההסבר שמדובר ב\u0003מתכוון\u0004 להרוג מי שאין בו דין מיתה \u0003אמר ליה ברישא\u0004 \u0005[לו בתחילה],\u0006 ואחר כך את ההסבר השני, שמדובר בממית על פי עד אחד או הבעלים. \u0003רב טביומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: המית אמר ליה ברישא\u0004 \u0005[לו בראשונה].\u0006","ומסבירים את טעמיהם, \u0003רב כהנא משמיה דרבא אמר: מתכוון אמר ליה ברישא\u0004 \u0005[לו בתחילה]\u0006 ואף שנימוק זה עדיף מן הנימוק השני (שיש עליו קושיה כאמור לעיל), מכל מקום הוסיף עליו אותו נימוק. \u0003משל לציד ששולה דגים מן הים,\u0004"],["\u0003משכח רברבי\u0004 \u0005[מוצא\u0006 דגים \u0005גדולים]\u0006 — \u0003שקיל\u0004 \u0005[נוטל],\u0006 \u0003זוטרי\u0004 \u0005[קטנים]\u0006 — \u0003שקיל\u0004 \u0005[נוטל],\u0006 כלומר, למרות שהנימוק הראשון היה מספיק, הוסיף גם טעם אחר, למרות שאינו מעולה כמו הראשון.","ואילו \u0003רב טביומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר:\u0004 את הנימוק של \u0003\"המית\" אמר ליה ברישא\u0004 \u0005[לו בתחילה],\u0006 \u0003משל לצייד ששולה דגים מן הים, משכח זוטרי\u0004 \u0005[מוצא\u0006 דגים \u0005קטנים]\u0006 — \u0003שקיל\u0004 \u0005[נוטל],\u0006 \u0003משכח רברבי\u0004 \u0005[מוצא\u0006 דגים \u0005גדולים]\u0006 — \u0003שדי זוטרי ושקיל רברבי\u0004 \u0005[זורק\u0006 את \u0005הקטנים ונוטל\u0006 את \u0005הגדולים].\u0006 כלומר, שתחילה אמר תשובה ראשונה ואחר כך עלה בדעתו הסבר טוב יותר.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 על הכתוב \"ו \u0003בעל השור נקי\"\u0004 (שמות כא, כח) \u0003ר' יוסי הגלילי אומר:\u0004 כוונת הכתוב היא \u0003נקי מדמי ולדות,\u0004 שאם שור תם גרם לאשה שתפיל — אינו משלם חצי נזק עבור הוולדות.","\u0003אמר לו ר' עקיבא:\u0004 אין צורך לכתוב זה כדי ללמדנו לימוד זה, ש\u0003הרי הוא אומר\u0004 בדין תשלום דמי וולדות עצמו: \u0003\"\u0004ו\u0003כי ינצו אנשים ונגפו אשה\u0004 הרה ויצאו ילדיה... ענוש יענש\u0003\"\u0004 (שמות כא, כב) ואפשר לדייק: \u0003אנשים,\u0004 שנזכרו במפורש בכתוב, מתחייבים בדמי ולדות, \u0003ולא שוורים.\u0004","ושואלים: \u0003שפיר קאמר\u0004 \u0005[יפה אומר]\u0006 \u0003ר' עקיבא,\u0004 ומה עונה על כך ר' יוסי הגלילי?","\u0003אמר רב עולא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 בכל זאת \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 אף כתוב זה ללמדנו שפטור השור מדמי ולדות, שכן בלעדיו \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה בדעתך לומר]\u0006 כי דיוק זה יש להגבילו: \u0003אנשים\u0004 חייבים בדמי ולדות — \u0003ולא שוורים הדומין לאנשים,\u0004 \u0003מה אנשים מועדין\u0004 (שהרי אדם מועד הוא לעולם), \u0003אף שוורים\u0004 דווקא \u0003מועדין,\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה שור \u0003תם\u0004 — \u0003מיחייב\u0004 \u0005[יהא חייב]\u0006 בדמי ולדות, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 בשור תם \"ו \u0003בעל השור נקי\"\u0004 — שאף הוא \u0003פטור\u0004 מדמי ולדות.","\u0003אמר רבא\u0004 בתמיהה על תירוץ זה: \u0003יציבא בארעא וגיורא בשמי שמיא\u0004 \u0005[התושב\u0006 נתון \u0005בארץ והגר בשמי השמים]?!\u0006 כלומר, הרי זה בניגוד למדרגתם של התם והמועד, וכיצד אפשר להעלות כלל סברה כזאת שמועד יהיה פטור ותם יהיה חייב? הלוא ברור שמרובה חיובו של מועד מחיובו של תם!","\u0003אלא אמר רבא,\u0004 כך יענה ר' יוסי הגלילי לשאלת ר' עקיבא: \u0003איצטריך\u0004 \u0005[צריך]\u0006 הכתוב להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה בדעתך לומר]:\u0006 \u0003אנשים\u0004 חייבים בדמי ולדות — \u0003ולא שוורים הדומין לאנשים, מה אנשים מועדין\u0004 — \u0003אף שוורים מועדין, וקל וחומר ל\u0004שוורים \u0003תמין דפטירי\u0004 \u0005[ש\u0006הם \u0005פטורים],\u0006 לכן \u0003הדר כתב רחמנא\u0004 \u0005[חזרה\u0006 ו\u0005כתבה התורה]\u0006 בשור תם \u0003\"\u0004ו\u0003בעל השור נקי\"\u0004 לומר כי דווקא \u0003תם פטור\u0004 מדמי ולדות \u0003ו\u0004אולם \u0003מועד חייב.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 לפי הסבר זה, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בושת נמי נימא הכי\u0004 \u0005[גם כן נאמר כך]:\u0006 \u0003אנשים\u0004 — \u0003ולא שוורים הדומין לאנשים, מה אנשים מועדין אף שוורים מועדין, וקל וחומר ל\u0004שוורים \u0003תמין דפטירי\u0004 \u0005[שפטורים]\u0006 מבושת, לכן \u0003הדר כתב רחמנא\u0004 \u0005[חזרה\u0006 ו\u0005כתבה התורה]\u0006 \u0003\"\u0004ו\u0003בעל השור נקי\"\u0004 ונלמד משם כי \u0003תם פטור\u0004 מבושת \u0003ומועד חייב!\u0004","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן]\u0006 הדין לדעת ר' יוסי הגלילי, \u0003אי הכי ליתני\u0004 \u0005[אם כך שישנה]\u0006 בברייתא \u0003\"\u0004ו\u0003בעל השור נקי\", ר' יוסי הגלילי אומר: פטור מדמי ולדות ו\u0004גם \u0003מבושת!\u0004","\u0003אלא\u0004 רבא חזור בו מאופן זה של הסבר דברי ר' יוסי הגלילי. \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[אומרים שניהם]:\u0006 מהמשך הכתוב \"ולא יהיה אסון ענוש יענש\" יכולים היינו לדייק: \u0003אנשים\u0004 אם \u0003אין אסון באשה,\u0004 שהיא עצמה לא נהרגה — \u0003יענשו\u0004 בעונש ממון, ומכאן נלמד שאם \u0003יש אסון באשה,\u0004 שהיא מתה על ידיהם — \u0003לא יענשו\u0004 בממון, בדמי הוולדות, לפי שיש בכך חיוב מיתה. אך דין זה הוא דווקא באנשים, \u0003ולא\u0004 ב\u0003שוורים\u0004 — \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003יש אסון\u0004 — \u0003יענשו\u0004 בדמי הוולדות\u0003.\u0004 וכדי לבטל הבנה זו \u0003הדר כתב רחמנא\u0004 \u0005[חזרה,\u0006 ו\u0005כתבה התורה]\u0006 \u0003\"\u0004ו\u0003בעל השור נקי\",\u0004 ש\u0003פטור\u0004 מכל מקום.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אדא בר אהבה: אטו\u0004 \u0005[וכי]\u0006 \u0003באסון תליא מילתא\u0004 \u0005[תלוי הדבר]\u0006 אם משלמים? הלא \u0003בכוונה\u0004 להזיק \u0003תליא מילתא\u0004 \u0005[תלוי הדבר]!\u0006","\u0003אלא אמר רב אדא בר אהבה,\u0004 כך היה מקום לדייק בכתוב: \u0003אנשים כי\u0004 \u0005[כאשר]\u0006 \u0003נתכונו\u0004 להזיק \u0003זה לזה, אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003שיש אסון באשה\u0004 שנהרגה — מכל מקום \u0003יענשו\u0004 בדמי ולדות, ו\u0003כי\u0004 \u0005[כאשר]\u0006 \u0003נתכונו לאשה עצמה\u0004 להורגה — \u0003לא יענשו\u0004 בדמי ולדות, משום שהם חייבים מיתה. \u0003ולא\u0004 כן דינם של \u0003שוורים,\u0004 ש\u0003אפילו נתכונו לאשה עצמה\u0004 להורגה — \u0003יענשו.\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"\u0004ו\u0003בעל השור נקי\"\u0004 ללמד \u0003דפטירי\u0004 \u0005[ש\u0006שוורים \u0005פטורים]\u0006 מדמי ולדות.","ומעירים: \u0003וכן, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב חגי מדרומא\u0004 \u0005[מן הדרום],\u0006 \u0003אתא ואייתי מתניתא בידיה כוותיה\u0004 \u0005[בא והביא ברייתא בידו כשיטתו]\u0006 של \u0003רב אדא בר אהבה,\u0004 שכך הכתוב נדרש.","ועוד באותו כתוב \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 על מה שנאמר \u0003\"\u0004ו\u0003בעל השור נקי\", ר' עקיבא אומר:\u0004 בא כתוב זה ללמדנו ששור תם שהרג עבד \u0003נקי מדמי עבד,\u0004 שאין בעליו חייבים לשלם עליו כשור מועד."],["ותוהים: \u0003ונימא\u0004 \u0005[ויאמר\u0006 ויקשה\u0005]\u0006 \u0003ר' עקיבא לנפשיה\u0004 \u0005[לעצמו\u0006 על שיטתו זו\u0005]\u0006 כדרך שהוא הקשה לר' אליעזר שדרש ממילים אלו עצמן ששור תם פטור מחצי כופר (לעיל בבא קמא מא,ב): מה צורך בלימוד מיוחד לענין זה? והרי גם בלעדיו היינו יודעים הלכה זו, \u0003והלא\u0004 בשור תם \u0003עצמו אין משתלם\u0004 הנזק \u0003אלא מגופו,\u0004 אם כן \u0003הביאהו לבית דין וישלם לך!\u0004 והרי כאשר הרג השור אדם נוטלים את השור וסוקלים אותו ואסור הוא בהנאה, וכיצד איפוא יכול שור תם לשלם את דמי העבד שהרג?","\u0003אמר רב שמואל בר רב יצחק:\u0004 דברי ר' עקיבא נאמרו \u0003כשקדם בעליו ושחטו\u0004 לפני שנגמר דינו לסקילה, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לישתלם מיניה\u0004 \u0005[שיקח\u0006 \u0005תשלום ממנו],\u0006 מן הבשר, שכן טרם נאסר השור בהנאה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003הואיל ובר קטלא\u0004 \u0005[ובן מוות]\u0006 \u0003הוא, אף על גב דשחטיה\u0004 \u0005[אף על פי ששחטו]\u0006 — \u0003לא לישתלם מיניה\u0004 \u0005[יקבל תשלום ממנו].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדוע הקשה לר' אליעזר? \u0003לר' אליעזר נמי\u0004 \u0005[גם כן]\u0006 אפשר לפרש שמדובר באותו אופן \u0003כשקדם ושחטו!\u0004","ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אפשר להסביר. \u0003ו\u0004מה שהקשה לו ר' עקיבא, הרי זה משום ש\u0003סבר: דלמא אית ליה טעמא אחרינא דעדיף מהאי ונימא ליה\u0004 \u0005[שמא יש לו\u0006 לר' אליעזר \u0005טעם אחר\u0006 \u0005שעדיף מ\u0006טעם \u0005זה ויאמר לו].\u0006 ואכן מצא ר' אליעזר נימוק אחר, ולא השתמש בנימוק הזה.","ושואלים: \u0003ור' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003לישני ליה\u0004 \u0005[שיתרץ לו]\u0006 באופן זה \u0003שקדם ושחטו\u0004 ומדוע תירץ באופן אחר? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה ר' אליעזר \u0005לומר]\u0006 \u0003לך: התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 במקרה שהעמיד הוא את הדברים, ש\u0003נתכוון להרוג את הבהמה והרג את האדם,\u0004 כיון שה\u0003שור לאו בר קטלא\u0004 \u0005[לא בן מוות]\u0006 \u0003הוא כלל, דסלקא דעתך אמינא ניחייב\u0004 \u0005[שיעלה על דעתך לומר שיתחייב]\u0006 וישלם מגופו — \u0003אצטריך קרא למעוטי\u0004 \u0005[הוצרך הכתוב למעטו]\u0006 שאינו משלם חצי כופר מגופו. \u0003אבל הכא דמעיקרא בר קטלא הוה\u0004 \u0005[כאן, שמתחילה בן מוות הוא]\u0006 — \u0003לא צריך קרא\u0004 \u0005[כתוב]\u0006 ללמדנו שאינו משלם חצי כופר מגופו \u0003אף על גב דשחטיה\u0004 \u0005[אף על פי ששחטו],\u0006 שהדבר מובן מאליו.","ומקשים: \u0003ול\u0004שיטת \u0003ר' עקיבא נמי\u0004 \u0005[גם כן],\u0006 \u0003ודאי הכי הוה\u0004 \u0005[כך הוא],\u0006 שאין צורך לכתוב מיוחד ללמד שפטור אם עבר ושחטו!","\u0003אלא\u0004 יש לדחות מה שאמרנו בהסבר דברי ר' עקיבא, ולומר כפי ש\u0003אמר רב אסי: האי מילתא מפי דגברא רבה שמיע לי\u0004 \u0005[דבר זה מפיו של אדם גדול שמעתי אותו]\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 אדם גדול זה — \u0003ר' יוסי בר' חנינא,\u0004 וכך אמר: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ואמר ר' עקיבא\u0004 במשנה לעיל: \u0003אף תם שחבל באדם משלם במותר נזק שלם,\u0004 שלדעתו לגבי נזקי שור באדם אין חילוק בין תם לבין מועד, אם כן \u0003משתלם נמי\u0004 \u0005[גם כן]\u0006 \u0003[דמי עבד]\u0004 שהמית \u0003מעלייה,\u0004 כלומר, שלא יגבה תשלום זה מגוף השור התם, אלא יגבה אותו מנכסי הבעלים, ונמצא שאין מקום לפוטרו בטענת \"הביאהו לבית דין\" — על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \"ו \u0003בעל השור נקי\",\u0004 ללמדנו שפטור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב אסי: והא תבריה\u0004 \u0005[והרי\u0006 כבר \u0005שבר]\u0006 \u0003ר' עקיבא לגזיזיה\u0004 \u0005[את אגרופו],\u0006 כלומר, ר' עקיבא עצמו חזר בו מדעתו זו ואינו סבור כן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' עקיבא אומר: יכול ישלם\u0004 התם נזקי אדם \u0003מן העלייה\u0004 — \u0003תלמוד לומר: \"כמשפט הזה יעשה לו\"\u0004 (שמות כא, לא) ללמד כי \u0003מגופו משלם\u0004 התם בכל מקרה, \u0003ואינו משלם\u0004 כלל \u0003מן העלייה!\u0004 ואם כן אין לתרץ כך אף לדעת ר' עקיבא.","\u0003 אלא אמר רבא:\u0004 כך יש להסביר את שיטת ר' עקיבא, \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 כתוב זה ללמדנו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ומחמירני\u0004 בנזקי שור מועד \u0003בעבד יותר מבן חורין, שבן חורין\u0004 אם היה \u0003יפה\u0004 (שווה) \u0003סלע\u0004 — \u0003נותן\u0004 המזיק דמי כופר \u0003סלע,\u0004 היה שווה \u0003שלשים\u0004 סלעים — \u0003נותן שלשים, ו\u0004אילו \u0003עבד,\u0004 אפילו היה \u0003יפה\u0004 (שווה) רק \u0003סלע\u0004 — \u0003נותן שלשים\u0004 סלעים\u0003,\u0004 שכך קבעה תורה קנס. וכיון שהחמירה בו התורה, הייתי אומר \u0003משתלם נמי\u0004 \u0005[גם כן]\u0006 בשור תם \u0003דמי עבד מן העלייה,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"\u0004ו\u0003בעל השור נקי\"\u0004 לומר שאינו גובה דמי עבד בשור תם.","ומעירים, \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא\u0004 בהסבר דברי ר' עקיבא \u0003\"\u0004ו\u0003בעל השור נקי\"\u0004 — \u0003ר' עקיבא אומר: נקי מדמי עבד.\u0004","והוא נושא ונותן: \u0003והלא דין הוא,\u0004 שלכאורה אפשר היה ללמוד את הדבר מן הסברה בלא להזדקק לפסוק: \u0003הואיל וחייב\u0004 הכתוב \u0003בעבד\u0004 תשלומים \u0003וחייב בבן חורין, מה כשחייב בבן חורין\u0004 — \u0003חלקת בו בין תם למועד\u0004 שתם אינו משלם כופר, \u0003אף כשחייב בעבד נחלק בו בין תם למועד.\u0004","\u0003ועוד,\u0004 אפשר לומר \u0003קל וחומר: ומה בן חורין שנותן כל שוויו\u0004 — \u0003חלקת בו בין תם למועד, עבד שאינו נותן אלא שלשים\u0004 ולא יותר, אפילו היה שווה יותר — \u0003אינו דין שנחלוק בו בין תם למועד\u0004 וייפטר התם?","והוא עצמו דוחה: \u0003לא,\u0004 אפשר לומר להיפך: \u0003מחמירני בעבד יותר מבן חורין, שבן חורין יפה סלע\u0004 — \u0003נותן סלע\u0004 בלבד, היה שווה \u0003שלשים\u0004 — \u0003נותן שלשים, ועבד\u0004 אפילו היה \u0003יפה\u0004 \u0003סלע\u0004 — \u0003נותן שלשים\u0004 סלעים, ואם כן, \u0003יכול יהא\u0004 שור תם \u0003חייב\u0004 לשלם דמי עבד? \u0003תלמוד לומר:\u0004 \"ו \u0003בעל השור נקי\",\u0004 ללמד: \u0003נקי מדמי עבד.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בשור מועד \"ואם שור נגח הוא... \u0003והמית איש או אשה\u0004 השור יסקל\" (שמות כא, כט), \u0003אמר ר' עקיבא: וכי מה בא זה ללמדנו? אם לחייב על\u0004 הריגת \u0003האשה כ\u0004הריגת \u0003איש\u0004 — \u0003הרי כבר נאמר\u0004 בשור תם \u0003\"\u0004ו\u0003כי יגח שור את איש או את אשה\u0004 ומת סקל יסקל השור","\u0003\"\u0004(שמות כא, כח)! \u0003אלא להקיש\u0004 (להשוות) \u0003אשה לאיש\u0004 לענין אחר: \u0003מה איש\u0004 — תשלומי \u0003נזקיו\u0004 משולמים \u0003ליורשיו, אף אשה\u0004 — נזקיה משולמים \u0003ליורשיה\u0004 ולא לבעלה.","ושואלים: \u0003ו\u0004האם \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' עקיבא:\u0004 שאשה \u0003לא ירית לה\u0004 \u0005[יורש אותה]\u0006 ה\u0003בעל? והתניא:\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על מה שנאמר \u0003\"וירש אתה\"\u0004 (במדבר כז, יא) — \u0003מכאן שהבעל יורש את אשתו,\u0004 אלו \u0003דברי ר' עקיבא!\u0004","\u0003אמר ריש לקיש: לא אמר\u0004 ר' עקיבא שנזקיה ליורשיה ולא לבעלה \u0003אלא בכופר, הואיל ואין משתלם\u0004 הכופר \u0003אלא לאחר מיתה\u0004 של האדם שנפגע על ידי השור, \u0003והוה ליה\u0004 \u0005[והרי זה]\u0006 דבר שבחייה לא היה נכס ממשי אלא רק \u0003ראוי, ו\u0004כלל הוא ש\u0003אין הבעל נוטל\u0004 חלק בנכסי האשה \u0003ב\u0004דבר \u0003ה\u0004\u0003ראוי\u0004 לה \u0003כ\u0004מו שהוא נוטל \u0003במוחזק\u0004 בידה. כגון ירושה הראויה לאשה, שאם נפלה לה לאחר מותה — אינה מגיעה לבעל אלא ליורשי האשה.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם],\u0006 מה ההוכחה שמשלם כופר רק לאחר מיתה (ולא בחיים, אף אם ברור שעומד הוא למות)? — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והמית איש או אשה השור יסקל וגם בעליו יומת. אם כפר יושת עליו\"\u0004 (שמות כא, כט–ל), הרי שחיוב הכופר תלוי בסקילת השור, וזה אינו נסקל עד שימות האדם שנגח, כפי שאמר הכתוב.","ושואלים: \u0003ו\u0004האם \u0003בנזקין לא אמר ר' עקיבא\u0004 שנזקיה משולמים ליורשיה ולא לבעל, כמו בכופר?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכה את האשה ויצאו ילדיה,\u0004 שהפילה את וולדה — \u0003נותן נזק וצער\u0004 של האשה \u0003לאשה\u0004 עצמה, \u0003ודמי ולדות לבעל. אין הבעל\u0004 חי — \u0003נותן\u0004 את חלקו (דמי הוולדות) \u0003ליורשיו,\u0004 \u0003אין האשה\u0004 קיימת — \u0003נותנת\u0004 חלקה (הצער והנזק) \u0003ליורשיה. היתה\u0004 האשה \u0003שפחה\u0004 כנענית \u0003ונשתחררה,\u0004 ומשנשתחררה נישאה לעבד משוחרר, ונתעברה ממנו,"],["\u0003או\u0004 היתה \u0003גיורת\u0004 שהיתה מעוברת מגר, ומתו הבעל והאשה, ואין להם יורשים — הרי זה \u0003זכה\u0004 בעל השור ואינו משלם, כיון שאין יורשים. ומכל מקום מפורש בברייתא זו שהבעל אינו יורש את נזקיה, אלא יורשיה, ואף בתשלומי נזקים שצריכה היתה לקבל עוד בחייה!","\u0003אמר רבה:\u0004 הברייתא עוסקת \u0003בגרושה,\u0004 וכיון שנתגרשה שוב אין הבעל זוכה במה שמגיע לה. \u0003וכן אמר רב נחמן:\u0004 הברייתא עוסקת \u0003בגרושה.\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ומקשים על כך: אם \u0003גרושה\u0004 היא \u0003נמי תיפלוג\u0004 \u0005[גם כן תחלוק]\u0006 \u0003בדמי ולדות,\u0004 אם היתה בחיים, שהרי איש זה שגירשה שוב אינו בעלה, ומדוע יהו דמי הוולדות שלו?","\u0003אמר רב פפא:\u0004 גזירת \u0003התורה\u0004 היא, ש\u0003זכתה דמי ולדות ל\u0004זה ש\u0003בעל\u0004 אותה, \u0003אפילו בא עליה בזנות\u0004 ואינו בעלה החוקי. שאף שאין לו זכות כלל בנכסיה, מכל מקום דמי ולדות שלו הם ולא של האשה כלל, שזכותו בהם מכח הבעילה ולא מכח זיקת הנישואין. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 והדגיש \u0003\"כאשר ישית עליו בעל האשה\"\u0004 (שמות כא, כב), לומר שהכל ניתן למי שבעלה. והוא הדין בגרושה.","ושואלים: מפני מה מפרשים רבה ורב נחמן ברייתא זו בגרושה? הלא היו יכולים לתרץ לפי שיטת עצמם במקום אחר, שמדובר כאן בתשלומים שלא היו בגדר \"מוחזק\" ביד האשה בחייה, אלא רק בגדר \"ראוי\" להגיע לידיה, ואותם אין הבעל יורש. \u0003ונוקמה\u0004 \u0005[ונעמיד,\u0006 נסביר, \u0005אותה]\u0006 את ההלכה זו \u0003ל\u0004שיטת \u0003רבה כגון שגבו\u0004 בית הדין \u0003מעות\u0004 עבור הנזק והצער, \u0003ול\u0004דעת \u0003רב נחמן\u0004 מדובר \u0003כגון שגבו קרקע.\u0004 שאף לענין זכותו של בכור לקבל פי שנים בנחלת האב, הבכור אינו נוטל פי שנים בראוי כמו במוחזק.","ובמקרה שהיו אחרים חייבים כסף לאביהם, \u0003אמר רבה: גבו קרקע\u0004 עבור החוב — \u0003יש לו\u0004 לבכור פי שנים, שהרי זה כנכסים שהיו כבר בחזקת האב, אבל \u0003גבו מעות\u0004 — \u0003אין לו,\u0004 שלא היה זה אלא בגדר \"ראוי\". \u0003ורב נחמן אמר:\u0004 אם \u0003גבו מעות\u0004 — \u0003יש לו,\u0004 אבל אם \u0003גבו קרקע\u0004 — \u0003אין לו!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003הני מילי לבני מערבא אליבא דרבנן\u0004 \u0005[דברים אלה\u0006 נאמרו \u0005ל\u0006שיטת \u0005בני ארץ ישראל ולפי\u0006 דברי \u0005חכמים]\u0006 שצמצמו את זכות הבכור בנכסי האב, עד שאמרו שאינו נוטל פי שנים בשבח שהשביחו הנכסים לאחר מותו.","אבל \u0003כי קאמרי הכא\u0004 \u0005[כאשר אמרו\u0006 \u0005כאן]\u0006 שברייתא זו עוסקת בגרושה, הרי זה \u0003כ\u0004שיטת \u0003רבי\u0004 שהבכור נוטל אף בשבח שהשביחו הנכסים אחר מות האב. ולשיטתו בוודאי שכל תשלום שצריך היה האב לקבל הריהו בגדר מוחזק, בין במעות ובין בקרקע, והוא הדין לבעל שזכאי לתשלומי הנזק והצער של אשתו. ולכן העמידו הלכה זו באשה גרושה.","\u0003אמר ר' שמעון בן לקיש: שור שהמית את העבד שלא בכוונה\u0004 — \u0003פטור משלשים שקלים, שנאמר: \"כסף שלשים שקלים יתן לאדניו והשור יסקל\"\u0004 (שמות כא, לב), ללמדנו שתלוי דין תשלום שלושים שקל בדין סקילת השור, ובאופן זה: \u0003כל זמן שהשור\u0004 דינו \u0003בסקילה\u0004 — \u0003הבעלים משלמין שלשים שקלים\u0004 דמי נזק, \u0003אין השור בסקילה,\u0004 כגון שהרג שלא בכוונה — \u0003אין הבעלים משלמין שלשים שקלים.\u0004","ובדומה לכך \u0003אמר רבה: שור שהמית\u0004 אדם \u0003בן חורין שלא בכוונה\u0004 — \u0003פטור מכופר, שנאמר \"השור יסקל וגם בעליו יומת. אם כפר יושת עליו\"\u0004 (שמות, כא, כט–ל), ללמדנו: \u0003כל זמן שהשור בסקילה\u0004 — \u0003בעלים משלמין כופר, אין השור בסקילה\u0004 — \u0003אין בעלים משלמין כופר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבה ממה ששנינו: מי שהודה ואמר \u0003\"המית שורי את פלוני\", או\u0004 שאמר \u0003\"\u0004המית שורי את \u0003שורו של פלוני\"\u0004 — \u0003הרי זה משלם על פי עצמו.\u0004 משמע שאין מדובר כאן בקנס שהמודה בו פטור, אלא בענין שיכול לחייב את עצמו על פי הודאתו, כשאר נזקי ממון. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן בתשלום \u0003כופר?\u0004 ונמצא שאף שאין השור מתחייב מיתה (שהרי אין אפשרות להמיתו על ידי עדות בעליו בלבד) מכל מקום חייב בתשלום כופר, ומכאן שאין לתלות דין תשלום כופר בסקילת השור!","ומשיבים: \u0003לא,\u0004 מדובר כאן בתשלום \u0003דמים.\u0004 שאף שאינו מחוייב בכופר, מכל מקום כיון שלפי הודאתו הזיק שורו — חייב לשלם מה שהזיק לפי דמי הנזק. אבל כופר עצמו אינו משתלם במקום שאין ממיתים את השור.","הקשה לו אביי לרבא: \u0003אי\u0004 \u0005[אם]\u0006 מדובר כאן בתשלום \u0003דמים, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה משנה: מי שהודה ואמר \u0003\"המית שורי את עבדו של פלוני\"\u0004 — \u0003אינו משלם על פי עצמו. ואי\u0004 \u0005[ואם]\u0006 אין מדובר כאן כדבריך בקנס, אלא בתשלום \u0003דמים\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 ישלם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לאביי: \u0003יכילנא לשנויי\u0004 \u0005[יכול הייתי לתרץ]\u0006 \u0003לך\u0004 כך: \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילה,\u0006 בקטע הראשון\u0005]\u0006 העוסק בשור שהמית בן חורין מדובר בתשלום \u0003דמים, וסיפא\u0004 \u0005[וסופו]\u0006 העוסק בשור שנגח עבד, מדבר בתשלום \u0003קנס, מיהו שנוייא דחיקא\u0004 \u0005[אבל תירוץ דחוק]\u0006 \u0003לא משנינא\u0004 \u0005[מתרץ אני]\u0006 \u0003לך,\u0004 ולכן יש לתרץ בדרך אחרת: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר בתשלום \u0003דמים.\u0004"],["\u0003מיהו\u0004 \u0005[ואולם]\u0006 יש להבחין בין שני המקרים; כשהרג השור \u0003בן חורין\u0004 יש מקרה ש\u0003משלם\u0004 בעליו \u0003כופר על פי\u0004 הודאת \u0003עצמו, והיכי דמי\u0004 \u0005[וכיצד הוא הדבר בדיוק]?\u0006 \u0003דאי אתו סהדי ואסהידו ביה דקטל\u0004 \u0005[שאם באו עדים והעידו בו\u0006 בשור \u0005שהרג]\u0006 אדם בן חורין וחייב סקילה, \u0003ו\u0004אולם \u0003לא ידעי אי\u0004 \u0005[אינם יודעים אם]\u0006 \u0003תם הוה\u0004 \u0005[היה]\u0006 השור \u0003אי\u0004 \u0005[או]\u0006 \u0003מועד הוה\u0004 \u0005[היה],\u0006 \u0003ואמר מריה\u0004 \u0005[אדוניו]\u0006 של השור ש\u0003מועד הוא,\u0004 שהואיל והשור בסקילה \u0003משלם כופר על פי עצמו,\u0004 שהרי הכופר הוא כפרה ולא קנס, ומשלם על פי הודאתו. משום כך, גם \u0003היכא דליכא\u0004 \u0005[היכן שאין]\u0006 \u0003עדים\u0004 ואין השור חייב בסקילה על הריגת האדם, מכל מקום \u0003משלם דמים\u0004 על פי הודאתו.","ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עבד ש\u0004לעולם \u0003אינו משלם קנס\u0004 (שלושים שקלים) \u0003על פי עצמו, והיכי דמי\u0004 \u0005[וכיצד הוא הדבר בדיוק],\u0006 כלומר, היכן היה מקום לחייבו על פי הודאתו? \u0003דאי אתו\u0004 \u0005[שאם באו]\u0006 \u0003עדים ואסהידו ביה דקטל\u0004 \u0005[והעידו בו,\u0006 בשור, \u0005שהרג]\u0006 עבד, \u0003ולא ידעי אי\u0004 \u0005[ואינם יודעים אם]\u0006 \u0003תם הוה\u0004 \u0005[היה]\u0006 השור \u0003אי\u0004 \u0005[או]\u0006 \u0003מועד הוה\u0004 \u0005[היה]\u0006 \u0003ואמר מריה\u0004 \u0005[בעליו]\u0006 ש\u0003מועד הוא,\u0004 אף שהשור חייב סקילה — \u0003לא משתלם קנס על פי עצמו\u0004 ששלושים שקלים של עבד הם קנס, והרי הוא כמודה בקנס ופטור. על כן גם \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003עדים\u0004 — \u0003לא משלם דמים\u0004 על פי הודאתו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב שמואל בר רב יצחק\u0004 מברייתא שנאמר בה כלל: \u0003כל שחייב בבן חורין חייב בעבד, בין בכופר בין במיתה.\u0004","ויש לתהות על הלשון: \u0003כופר בעבד מי איכא\u0004 \u0005[האם יש]?\u0006 הלא אין כופר אלא בבן חורין! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן בחיוב בתשלום \u0003דמים,\u0004 וקשה לרבה, שאמר שאין משלם דמים על העבד בהודאת עצמו!","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003הוא,\u0004 רב שמואל בר רב יצחק, \u0003מותיב לה\u0004 \u0005[הקשה את\u0006 הקושיה \u0005הזו]\u0006 \u0003והוא מפרק לה\u0004 \u0005[תירץ אותה],\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה\u0004 בתירוץ: \u0003הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש להבין את הברייתא: \u0003כל שחייב בבן חורין,\u0004 והכוונה — כאשר נגח השור \u0003בכוונה על פי עדים\u0004 שחייב לשלם \u0003כופר\u0004 — הרי בכגון זה \u0003חייב בעבד קנס. וכל שחייב בבן חורין, שלא בכוונה על פי עדים,\u0004 שחייב לשלם \u0003דמים\u0004 — \u0003חייב\u0004 אף \u0003בעבד, שלא בכוונה על פי עדים, דמים.\u0004 אבל בהודאת עצמו אינו משלם דמים על העבד, אף שמשלם דמים על הריגת בן חורין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרבה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמשלם דמים במקום שאין חיוב כופר, \u0003אשו\u0004 שהצית \u0003שלא בכוונה על פי עדים\u0004 וגרם שיישרף אדם — \u0003נשלם\u0004 \u0005[ישלם]\u0006 לפחות \u0003דמים!\u0004","ושואלים: \u0003ומנא ליה\u0004 \u0005[ומניין לו]\u0006 \u0003לרבא\u0004 שאכן \u0003לא משלם\u0004 דמים גם כשהצית שלא בכוונה?","\u0003אילימא מדתנן\u0004 \u0005[אם תאמר מ\u0006מה \u0005ששנינו\u0006 במשנה\u0005]:\u0006 \u0003היה גדי כפות לו\u0004 לגדיש שאותו אדם הבעיר \u0003ועבד סמוך לו ונשרף עמו\u0004 — הרי זה המצית את הגדיש \u0003חייב\u0004 בתשלומים על הגדי והגדיש. היה \u0003עבד כפות לו וגדי סמוך לו ונשרף עמו\u0004 — \u0003פטור,\u0004 ומשמע שאין חיוב דמים על שגרם לשריפת העבד — מכאן אין ראיה, כי","\u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ריש לקיש:\u0004 שם מדובר \u0003כגון שהצית\u0004 את האש \u0003בגופו של עבד\u0004 עצמו, \u0003דקם ליה בדרבה מיניה\u0004 \u0005[שעומד הוא ב\u0006עונש \u0005גדול,\u0006 חמור, \u0005ממנו],\u0006 שכיוון שחייב מיתה על הריגת העבד — שוב איננו חייב בתשלומים, ולכן אין להוכיח מכאן.","\u0003ואלא\u0004 תאמר שמוכיח \u0003מהא\u0004 \u0005[מזו]\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003חומר באש מבבור\u0004 — \u0003שהאש מועדת לאכול בין דבר הראוי לה בין דבר שאין ראוי לה,\u0004 שעל כל מה שהזיקה — משלם, \u0003מה שאין כן בבור,\u0004 שלא על כל דבר שניזק משלמים נזקי בור. \u0003ואילו\u0004 הבדל זה, \u0003שהאש משלמת שלא בכוונה דמים, מה שאין כן בבור\u0004 — \u0003לא קתני\u0004 \u0005[שנה]\u0006 — אף מכאן אין להוכיח,","\u0003דלמא תנא\u0004 \u0005[שמא שנה]\u0006 \u0003ושייר\u0004 ולא מנה את כל ההבדלים!","\u0003אלא\u0004 יש להבין כך: \u0003רבא גופיה אבעויי מבעיא ליה\u0004 \u0005[עצמו מסתפק לו\u0006 הדבר\u0005]\u0006 ולא שהקשה על רבה באופן החלטי, אלא שאל שאלה: \u0003אשו שלא בכוונה, מי\u0004 \u0005[האם]\u0006 \u0003משלם דמים, או לא?\u0004","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שור הוא\u0004 ש\u0003בכוונה משלם כופר,\u0004 על כן אם היה הדבר \u0003שלא בכוונה משלם דמים, אבל אשו\u0004 שגם אם הציתה \u0003בכוונה לא משלם כופר, שלא בכוונה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא משלם דמים. או דלמא\u0004 \u0005[שמא]\u0006 נדון באופן אחר: \u0003כיון דגבי\u0004 \u0005[אצל]\u0006 \u0003שורו שלא בכוונה אף על גב דליכא\u0004 \u0005[אף על פי שאין]\u0006 \u0003כופר,\u0004 מכל מקום \u0003משלם דמים,\u0004 אם כן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אשו נמי\u0004 \u0005[גם כן]\u0006 \u0003אף על גב\u0004 ש\u0003בכוונה לא משלם כופר, שלא בכוונה מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003משלם דמים?\u0004","ומסכמים: \u0003ולא ידעינן\u0004 \u0005[ואין אנו יודעים]\u0006 כיצד לפתור את הבעיה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ובענין זה שאמר רבה, ששור שהמית שלא בכוונה פטור מכופר, מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 די היה שתאמר התורה \u0003\"כפר\u0004 יושת עליו\u0003\"\u0004 (שמות כא, ל), ו\u0003מה תלמוד לומר \"אם כפר\"\u0004 — \u0003לרבות\u0004 שישלם \u0003כופר\u0004 גם על מה שהרג שורו \u0003שלא בכוונה, כ\u0004פי שמשלם \u0003כופר\u0004 בהריגה \u0003בכוונה.\u0004 והרי זה שלא כדברי רבה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב דימי: \u0003אלא מעתה,\u0004 לפי דרשה זו של ר' יוחנן, לגבי קנס של \u0003עבד נמי\u0004 \u0005[גם כן]\u0006 נדרוש כך: די היה שייכתב \"עבד יגח השור\", \u0003מה תלמוד לומר \"אם עבד\u0004 יגח השור או אמה כסף שלושים שקלים יתן לאדוניו\u0003\"\u0004 (שמות כא, לב) — \u0003לרבות עבד שלא בכוונה כעבד בכוונה! וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך הוא,\u0006 שכן הדין\u0005]\u0006 — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: שור שהמית את העבד שלא בכוונה\u0004 — \u0003פטור משלשים שקלים!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי לאביי: \u0003גברא אגברא קא רמית\u0004 \u0005[\u0006וכי \u0005מאדם על אדם אתה מקשה]?\u0006 ייתכן שאף שריש לקיש סבור שאינו משלם, ר' יוחנן סבור שמשלם!","ומספרים שאכן כך דרש ר' יוחנן, שכן \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 כך בשם \u0003ר' יוחנן:\u0004 די היה שיאמר \u0003\"עבד\", מה תלמוד לומר \"אם עבד\"\u0004 — \u0003לרבות\u0004 נגיחת \u0003עבד שלא בכוונה כ\u0004נגיחת \u0003עבד בכוונה.\u0004","ושואלים: \u0003ולריש לקיש נמי\u0004 \u0005[גם כן]\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003מ\u0004אחר שאת הריבוי \u0003\"עבד\" \"אם עבד\"\u0004 הוא \u0003לא דריש\u0004 \u0005[דורש],\u0006 נאמר כי \u0003\"כפר\" \"אם כפר\" נמי לא דריש\u0004 \u0005[גם כן אינו דורש],\u0006 וגם כופר על שלא בכוונה אינו משלם!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא,\u0004 אין זו השוואה נכונה, את הריבוי \u0003\"עבד\" \"אם עבד\"\u0004 ריש לקיש \u0003לא דריש\u0004 \u0005[דורש],\u0006 אבל \u0003\"כפר\" \"אם כפר\"\u0004 — \u0003דריש\u0004 \u0005[דורש].\u0006","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 הדבר, שבמקום אחד הוא דורש \"אם\" לרבות, ובמקום אחר אינו דורש? ומשיבים: \u0003\"עבד\" \"אם עבד\" לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003במקום\u0004 חיוב \u0003תשלומין,\u0004 אלא לענין נגיחה (\"אם עבד יגח השור\"), ואינו בא אלא כפתיחה לדין העבד. לעומת זאת \u0003\"כפר\" \"אם כפר\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003במקום תשלומין\u0004 ודי היה שייאמר \"כופר ישלם\", ולכן ראוי ללמוד מכאן לרבות תשלום כופר שלא בכוונה.","שנינו במשנה: \u0003וכן בבן או בבת.\u0004 ובאותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"או בן יגח או בת יגח\"\u0004 (שמות כא, לא) — \u0003לחייב על הקטנים כגדולים\u0004 בא הכתוב.","ולכאורה: \u0003והלא דין הוא,\u0004 שאפשר ללמוד את הדבר מן הסברה בלבד, ובדרך זו: \u0003הואיל וחייב\u0004 הכתוב מיתה ב\u0003אדם\u0004 שפגע \u0003באדם\u0004 והרגו, \u0003וחייב\u0004 הכתוב מיתה ב\u0003שור\u0004 שפגע \u0003באדם\u0004 והרגו, נלמד זה מזה: \u0003מה כשחייב אדם באדם לא שנא\u0004 \u0005[אינו שונה,\u0006 לא חילק\u0005]\u0006 \u0003בין\u0004 הורג \u0003קטנים ל\u0004הורג \u0003גדולים, אף כשחייב שור באדם\u0004 — \u0003לא תחלוק בו בין קטנים לגדולים!\u0004","\u0003ועוד, קל וחומר הוא: ומה אדם באדם, שלא עשה בו קטנים כגדולים,\u0004 שהרי קטן שהרג פטור, ובכל זאת \u0003חייב בו על הקטנים כגדולים,\u0004 שחייב מיתה גם אם הרג קטן,"],["\u0003שור\u0004 שחבל \u0003באדם\u0004 והרגו, \u0003שעשה בו\u0004 דין שוורים \u0003קטנים כגדולים,\u0004 שהרי שור קטן שהרג חייב כשור גדול, \u0003אינו דין שחייב\u0004 סקילה \u0003על הקטנים\u0004 שהמית ילד או ילדה, \u0003כגדולים?\u0004 ואם כן מה צורך בפסוק זה ללמדנו הלכה הנלמדת מסברה?","ודוחים: \u0003לא\u0004 ניתן היה ללמוד דבר זה מן הסברה, שכן \u0003אם אמרת\u0004 שהדין כן ב\u0003אדם באדם\u0004 שחייב אף על קטנים, דבר זה משום חומרה יתירה שיש בו, \u0003שכן\u0004 אדם המזיק \u0003חייב בארבעה דברים\u0004 נוספים על עצם הנזק (צער, בושת, ריפוי ושבת), \u0003תאמר בשור שאינו חייב בארבעה דברים\u0004 ולכן אין ללמוד מן ההשוואה — משום כך \u0003תלמוד לומר\u0004 מן הכתוב: \u0003\"או בן יגח או בת יגח\"\u0004 (שמות כא, לא) \u0003לחייב על הקטנים כגדולים.\u0004","\u0003ואין לי\u0004 דין זה \u0003אלא במועדין, בתם מנין\u0004 שנסקל אם הרג קטן או קטנה?","ומשיבים: \u0003דין\u0004 (סברה) \u0003הוא: הואיל וחייב\u0004 הכתוב סקילה \u0003ב\u0004שור שהרג \u0003איש ואשה, וחייב\u0004 גם \u0003ב\u0004הריגת \u0003בן ובת, מה כשחייב ב\u0004הריגת \u0003איש ואשה\u0004 — \u0003לא חלקת בו בין תם למועד\u0004 שנסקל השור עליהם, \u0003אף כשחייב בבן ובת\u0004 — \u0003לא תחלוק בו בין תם למועד.\u0004","\u0003ועוד, קל וחומר\u0004 הוא: ו\u0003מה איש ואשה שכן הורע כחם בנזקין,\u0004 שהרי הגדולים חייבים לשלם על מה שהזיקו — \u0003לא חלקת בו\u0004 בדין השור שהרגם \u0003בין תם למועד, בן ובת שיפה כחם בנזקין,\u0004 שהרי הם שהזיקו אינם חייבים — \u0003אינו דין שלא תחלוק בהן\u0004 אם נהרגו על ידי שור \u0003בין תם למועד?\u0004","\u0003אמרת\u0004 \u0005[אומר אתה]\u0006 כנגד זה: \u0003וכי דנין קל מחמור להחמיר עליו? אם החמיר\u0004 הכתוב \u0003במועד החמור\u0004 וחייב על הקטנים כגדולים \u0003תחמיר בתם הקל?\u0004 ואם כן אין כאן לימוד.","\u0003ועוד\u0004 יש טעם אחר לפרוך את הנימוק שאמרנו, שכן אפשר לומר גם סברה אחרת: \u0003אם אמרת\u0004 בשור תם שחייב סקילה \u0003באיש ואשה\u0004 — \u0003שכן חייבין\u0004 הם \u0003במצות\u0004 ומשום כך הם חשובים, \u0003תאמר בבן ובת שפטורין מן המצות.\u0004","ואם כן אין ללמוד דין זה מן הסברה, ולכן \u0003תלמוד לומר\u0004 מן הכתוב: \u0003\"או בן יגח או בת יגח\",\u0004 ומכפל המלה \"יגח\" למדים גם \u0003נגיחה בתם\u0004 וגם \u0003נגיחה במועד,\u0004 גם \u0003נגיחה למיתה\u0004 וגם \u0003נגיחה לנזקין,\u0004 שעל כולם חייב אם נגח קטנים.","\u0003שור שהיה מתחכך בכותל ו\u0004מתוך כך \u0003נפל\u0004 הכותל \u0003על האדם\u0004 והרגו, או במקרה ש\u0003נתכוין\u0004 השור \u0003להרוג את הבהמה והרג את האדם,\u0004 או שהתכוון \u0003ל\u0004הרוג \u0003גוי והרג בן ישראל,\u0004 וכן אם התכוון \u0003ל\u0004הרוג \u0003נפלים\u0004 (שאף שהם חיים לפי שעה, מכל מקום עומדים הם למות בזמן קרוב, ואין ההורגם חייב מיתה) \u0003והרג בן קיימא\u0004 — בכל המקרים האלה \u0003פטור\u0004 השור ממיתה.","\u0003אמר שמואל:\u0004 אמנם \u0003פטור\u0004 השור \u0003ממיתה,\u0004 שהרי לא נתכוון להרוג, \u0003ו\u0004אולם \u0003חייב\u0004 בעליו \u0003ב\u0004תשלום \u0003כופר\u0004. \u0003ורב אמר: פטור מזה ומזה.\u0004","על דברי שמואל שואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 חייב בכופר? \u0003הא\u0004 \u0005[הרי]\u0006 שור זה \u0003תם הוא\u0004 לענין נזק זה, ומדוע יהא חייב בכופר? ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב\u0004 בענין אחר: מדובר \u0003ב\u0004שור שהיה \u0003מועד ליפול על בני אדם בבורות, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ב\u0004שור שהיה \u0003מועד להתחכך על בני אדם בכתלים,\u0004 כלומר, להתחכך בכתלים ולהפילם על בני אדם.","ותוהים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שהיה מועד לעשות כן — הרי בוודאי מתכוון הוא לעשות זאת, ולכן \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא! בשלמא התם\u0004 \u0005[נניח שם]\u0006 בשור המועד ליפול על בני אדם בבורות, אפשר לומר \u0003דחזא ירוקא\u0004 \u0005[שראה ירק]\u0006 על פי הבור \u0003ונפל\u0004 ולא התכוון להרוג, \u0003אלא הכא\u0004 \u0005[כאן]\u0006 שהתחכך והפיל כותל על אדם, והיה מועד בכך, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003במתחכך בכותל להנאתו\u0004 ולא במתכוון להזיק. ושואלים: \u0003ומנא ידעינן\u0004 \u0005[ומניין יודעים אנו]\u0006 שלא להזיק התכוון? ומשיבים: \u0003דבתר\u0004 \u0005[ש\u0006אף \u0005לאחר]\u0006 ש\u0003נפל\u0004 הכותל \u0003קא מתחכך ביה\u0004 \u0005[\u0006ממשיך השור ו\u0005מתחכך בו]\u0006 ורואים איפוא שהיתה כוונתו מתחילה לחיכוך בלבד."],["ומקשים עוד: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 יש לשאול על שמואל: הלא \u0003צרורות נינהו\u0004 \u0005[הם]\u0006 שהמיתו את האדם. שאין זה נזק שגרם השור בגופו, אלא דבר שנגרם על ידי צרורות, אבנים שבאו מכוחו, ואין חייבים בכופר על נזק בלתי ישיר! \u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא:\u0004 מדובר במקרה \u0003דקאזיל\u0004 \u0005[שהולך]\u0006 ונדחף הכותל על ידי דחיפת השור \u0003מיניה מיניה\u0004 \u0005[ממנו ממנו],\u0006 שבתוך כדי הדחיפה פוגע הכותל באדם.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל ותיובתא\u0004 \u0005[ו\u0006היא \u0005קושיה חמורה]\u0006 לשיטתו של \u0003רב,\u0004 ששנינו: \u0003יש\u0004 ש\u0003חייב במיתה ובכופר, ויש\u0004 ש\u0003חייב בכופר ופטור ממיתה, ויש\u0004 ש\u0003חייב במיתה ופטור מן הכופר, ויש\u0004 ש\u0003פטור מזה ומזה.\u0004","ומפרטים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 שור \u0003מועד\u0004 שהרג אדם \u0003בכוונה\u0004 — \u0003חייב במיתה ובכופר. מועד\u0004 שהרג \u0003שלא בכוונה\u0004 — \u0003חייב בכופר ופטור ממיתה. תם\u0004 שהרג \u0003בכוונה\u0004 — \u0003חייב במיתה ופטור מכופר. תם\u0004 שהרג \u0003שלא בכוונה\u0004 — \u0003פטור מזה ומזה.\u0004 הרי שנינו במפורש כדברי שמואל, ששור מועד שהרג אדם שלא בכוונה פטור ממיתה וחייב בכופר, ולא כדברי רב שפטור מזה ומזה.","\u0003ו\u0004מוסיפה הברייתא: על \u0003הנזקין\u0004 שגרם שור \u0003שלא בכוונה\u0004 בלא להמית את הנפגע, \u0003ר' יהודה מחייב, ור' שמעון פוטר.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 הוא דין נזקין של שור \u0003מכופרו\u0004 (תשלום כופר שלו), \u0003מה כופרו\u0004 של השור אם נגח \u0003שלא בכוונה חייב\u0004 — \u0003אף\u0004 על \u0003הנזקין נמי\u0004 \u0005[גם כן]\u0006 אם נגח \u0003שלא בכוונה חייב.\u0004","\u0003ור' שמעון יליף מקטליה\u0004 \u0005[מ\u0006עונש \u0005הריגתו]\u0006 של ה\u0003שור; מה\u0004 בענין \u0003קטליה\u0004 \u0005[הריגתו]\u0006 אם המית \u0003שלא בכוונה\u0004 — \u0003פטור\u0004 ממיתה, \u0003אף נזקין\u0004 אם הזיק \u0003שלא בכוונה\u0004 — \u0003פטור.\u0004","ושואלים: \u0003ור' יהודה נמי נילף מקטליה\u0004 \u0005[גם כן שילמד מהריגתו]!\u0006 ומשיבים: לדעתו \u0003דנין\u0004 (למדים) \u0003תשלומין מתשלומין\u0004 (נזקים מכופר) \u0003ואין דנין תשלומין ממיתה.\u0004","ושואלים: \u0003ור' שמעון נמי נילף\u0004 \u0005[גם כן שילמד]\u0006 \u0003מכופרו!\u0004 ומשיבים: \u0003דנין חיוביה\u0004 \u0005[חיובו]\u0006 של ה\u0003שור מחיוביה\u0004 \u0005[מחיובו]\u0006 של ה\u0003שור\u0004 כמזיק, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003כופר דחיוביה\u0004 \u0005[שחיובו]\u0006 של ה\u0003בעלים הוא,\u0004 משום כפרה, ואין ללמוד ממנו לחיוב שמוטל על השור כמזיק.","שנינו במשנה שאם \u0003נתכוין להרוג את הבהמה והרג את האדם,\u0004 וכיוצא בזה נתכוון להרוג מי שאינו חייב מיתה עליו, ובפועל הרג מי שחייב מיתה עליו — הרי זה \u0003פטור.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נתכוין\u0004 השור \u0003להרוג את\u0004 אדם \u0003זה\u0004 שחייבים על מיתתו \u0003והרג את\u0004 אדם \u0003זה\u0004 — \u0003חייב.\u0004 ואם כן \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' שמעון\u0004 היא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: אפילו נתכוין\u0004 השור \u0003להרוג את\u0004 אדם \u0003זה והרג את\u0004 אדם \u0003זה\u0004 — \u0003פטור.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון?\u0004 ומסבירים: ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"השור יסקל וגם בעליו יומת\"\u0004 (שמות כא, כט) וההיקש מלמדנו: \u0003כמיתת בעלים,\u0004 כלומר, כדרך שאדם שהרג אדם חייב מיתה — \u0003כך מיתת השור\u0004 שהרג אדם, \u0003מה בעלים\u0004 אינו חייב מיתה \u0003עד דמיכוין ליה\u0004 \u0005[שיתכוון אליו]\u0006 לזה שהרגו, \u0003אף שור נמי\u0004 \u0005[גם כן]\u0006 אינו נהרג \u0003עד דמיכוין ליה\u0004 \u0005[שיתכוון אליו].\u0006","ושואלים: \u0003ובעלים גופייהו מנלן\u0004 \u0005[עצמם מניין לנו]\u0006 שאין מתחייב אלא אם כן הרג את זה שהתכוון אליו? ומשיבים: ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וארב לו וקם עליו\u0004 והכהו נפש ומת\u0003\"\u0004 (דברים יט, יא) וממה שנאמר \"לו\" הוא למד: \u0003עד שיתכוין לו\u0004 לאותו אדם שאכן הרגו.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' שמעון ומחייבים בכגון זה, \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"וארב לו\" מאי עבדי ליה\u0004 \u0005[מה\u0006 הם \u0005עושים בו,\u0006 לומדים ממנו\u0005]?\u0006 ומשיבים: \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 חכמי \u0005בית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ינאי:\u0004 הכוונה היא \u0003פרט לזורק אבן לגו\u0004 \u0005[לתוך]\u0006 מקום שמצויים בו בני אדם, ולא על כולם חייב מיתה, והרגה האבן אחד מהם.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דאיכא\u0004 \u0005[אם תאמר שיש]\u0006 באותו מקום \u0003תשעה גוים ואחד ישראל ביניהם\u0004 — \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 מסקנה זו להלכה לא מטעם זה, אלא מטעם אחר, כיון \u0003דרובא\u0004 \u0005[שהרוב]\u0006 \u0003גוים נינהו\u0004 \u0005[הם]\u0006 ואינו חייב על הריגתם. \u0003אי נמי פלגא ופלגא\u0004 \u0005[או גם כן\u0006 אם היו \u0005מחצה ומחצה]\u0006 ישראל וגוים, מכל מקום הרי ספק נפשות הוא לגבי הריגתו של הרוצח ביד בית הדין, וכלל הוא: \u0003ספק נפשות להקל!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 במקום \u0003תשעה ישראלים ואחד גוי, דאף על גב דרובא\u0004 \u0005[שאף עך פי שהרוב]\u0006 \u0003ישראלים נינהו\u0004 \u0005[הם],\u0006 ואם כן יש להחשיב את זריקת האבן כמכוונת להמית אחד מן הרוב, ולדעת חכמים חייב במקרה כזה — מכל מקום \u0003כיון דאיכא חדא גוי בינייהו\u0004 \u0005[שיש גוי אחד ביניהם]\u0006 \u0003הוי ליה\u0004 \u0005[הרי הוא]\u0006 כ\u0003קבוע,\u0004 \u0003ו\u0004כלל הוא: \u0003כל קבוע כמחצה על מחצה דמי\u0004 \u0005[נחשב],\u0006 \u0003וספק נפשות להקל,\u0004 ודבר זה למדו חכמים ממה שנאמר: \"וארב לו\".","\u0003שור\u0004 של \u0003האשה, ו\u0004כן \u0003שור\u0004 של \u0003היתומים, שור האפוטרופוס\u0004 (של היתומים), \u0003שור המדבר\u0004 שהוא הפקר, \u0003שור\u0004 שברשות \u0003ההקדש,\u0004 או \u0003שור הגר שמת ואין לו יורשין\u0004 ולכן אין לו בעלים — \u0003הרי אלו חייבין מיתה\u0004 אם הרגו אדם. \u0003ר' יהודה אומר: שור המדבר, שור ההקדש, שור הגר שמת\u0004 — \u0003פטורין מן המיתה, לפי שאין להם בעלים.\u0004","בהלכות אלו שנשנו במשנה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת שור הנוגח אדם (שמות כא, כח–לב) \u0003\"שור\" \"שור\" שבעה\u0004 פעמים, והרי זה בא \u0003להביא\u0004 (להוסיף) על המקרה הרגיל של שור שנגח והמית אדם עוד ששה חיובים נוספים והם: \u0003שור האשה, שור היתומים, שור האפוטרופוס, שור המדבר, שור ההקדש, שור הגר שמת ואין לו יורשין. ר' יהודה אומר: שור המדבר, שור ההקדש, שור הגר שמת ואין לו יורשין\u0004 — כל אלה \u0003פטורין מן המיתה, לפי שאין להם בעלים.\u0004","\u0003אמר רב הונא: פוטר היה ר' יהודה אפילו\u0004 במקרה ש\u0003נגח\u0004 השור והרג \u0003ולבסוף הקדיש\u0004 אותו בעליו, או ש\u0003נגח ולבסוף הפקיר\u0004 אותו בעליו, שבשעת העמדה בבית דין אין לו בעלים.","ושואלים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק רב הונא שכך היא דעת ר' יהודה? \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 ר' יהודה במשנה \u0003תרתי\u0004 \u0005[שני]\u0006 דברים, \u0003שור המדבר, ושור הגר שמת ואין לו יורשין.\u0004 ונברר: \u0003שור הגר שמת מאי ניהו\u0004 \u0005[מה הוא]\u0006 מבחינת מעמדו החוקי? שהלא \u0003כיון\u0004 ש\u0003אין לו יורשין הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003שור הפקר,\u0004 ואם כן, \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003שור המדבר היינו\u0004 \u0005[זהו]\u0006 \u0003שור הגר שמת ואין לו יורשין,\u0004 ולא היה לו לר' יהודה להשמיע את שניהם? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אפילו\u0004 ב\u0003נגח ולבסוף הקדיש,\u0004 או \u0003נגח ולבסוף הפקיר\u0004 שהוא פטור, כשור של הגר, שלאחר שנגח מת בעליו ונעשה הפקר. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא דעת ר' יהודה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 במפורש: \u0003יתר על כן אמר ר' יהודה, אפילו נגח ולבסוף הקדיש, נגח ולבסוף הפקיר\u0004 — \u0003פטור, שנאמר: \"והועד בבעליו... והמית...\u0004 השור יסקל\u0003\"\u0004 (שמות כא, כט), לומר: \u0003עד שתהא מיתה והעמדה\u0004 של השור \u0003בדין שוין\u0004 כולם \u0003כאחד,\u0004 שיש לשור בעלים.","ושואלים: וכי \u0003גמר דין לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהא בבעלים? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"השור יסקל\" גמר דין הוא! אלא אימא\u0004 \u0005[אמור\u0006 ותקן כך\u0005]:\u0006 \u0003עד שתהא מיתה והעמדה בדין וגמר דין שוין\u0004 כולם \u0003כאחד.\u0004","\u0003שור\u0004 שהרג \u0003ש\u0004לאחר שדנוהו בבית הדין \u0003הוא יוצא\u0004 (עומד) \u0003ליסקל, והקדישו בעליו\u0004 — \u0003אינו מוקדש,\u0004 ששור זה אסור בהנאה ואין לו דמים, ואם \u0003שחטו\u0004 — \u0003בשרו אסור\u0004 באכילה והנאה. \u0003ואם עד שלא\u0004 (לפני ש) \u0003נגמר דינו הקדישו בעליו\u0004 — הרי זה \u0003מוקדש, ואם שחטו\u0004 לפני שנגמר דינו — \u0003בשרו מותר.\u0004","ועוד בנוגע לבעלות על השור המזיק: \u0003מסרו\u0004 הבעלים את השור \u0003לשומר חנם ו\u0004כן \u0003לשואל\u0004 או \u0003לנושא שכר\u0004 (שומר שכר) \u0003ולשוכר\u0004 והזיק השור כשהיה ברשותם — \u0003נכנסו\u0004 אלה \u0003תחת הבעלים\u0004 לגבי אחריותם לשור. כיצד? \u0003מועד\u0004 — \u0003משלם נזק שלם, ותם\u0004 — \u0003משלם חצי נזק.\u0004","ועוד בענין זה שנדון בתחילת המשנה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שור שהמית,\u0004 אם \u0003עד שלא נגמר דינו, מכרו\u0004 —"],["הרי הוא \u0003מכור\u0004 והריהו של הקונה לכל דבר, אם \u0003הקדישו\u0004 — הרי זה \u0003מוקדש,\u0004 וחלים עליו דיני הקדש, אם \u0003שחטו\u0004 — \u0003בשרו מותר\u0004 באכילה, וכן אם \u0003החזירו שומר לבית בעליו\u0004 לפני שנגמר דינו — הרי זה \u0003מוחזר\u0004 ואין לבעלים עוד תביעה עליו.","ואולם \u0003משנגמר דינו,\u0004 אם \u0003מכרו\u0004 — \u0003אינו מכור,\u0004 לפי שאינו עוד שלו, וכן אם \u0003הקדישו\u0004 — \u0003אינו מוקדש,\u0004 ואם \u0003שחטו\u0004 — \u0003בשרו אסור,\u0004 אם \u0003החזירו שומר לבית בעליו\u0004 — \u0003אינו מוחזר,\u0004 שהרי שור זה כהרוג הוא. \u0003ר' יעקב אומר: אף משנגמר דינו\u0004 אם \u0003החזירו שומר לבעליו\u0004 — \u0003מוחזר.\u0004","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר שב\u0006ענין \u0005זה חלוקים\u0006 הם\u0005],\u0006 \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003אין אומרין באיסורי הנאה \"הרי שלך לפניך\",\u0004 שאם החפץ נאסר בהנאה אין השומר יכול לומר לבעל החפץ: הרי החפץ שהפקדת בידי מוחזר לידיך, ואין לך עוד תביעה עלי, שלא נעשה כל שינוי חיצוני בגוף הדבר. \u0003ור' יעקב סבר\u0004 \u0005[סבור]:\u0006 \u0003אומרין באיסורי הנאה \"הרי שלך לפניך\"?\u0004","\u0003אמר רבה: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אומרין באיסורי הנאה \"הרי שלך לפניך\",\u0004 ש\u0003אם כן\u0004 כדבריך שבנושא זה חלקו — \u0003נפלוג\u0004 \u0005[שיחלקו]\u0006 \u0003לענין חמץ בפסח,\u0004 שהוא איסור הנאה מובהק, אם אומרים \"הרי שלך לפניך\".","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה אחרת, והיא: האם \u0003גומרין דינו של שור שלא בפניו\u0004 של השור \u0003קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים],\u0006 \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003אין גומרין דינו של שור אלא בפניו,\u0004 ולפיכך אין יכול השומר להחזירו לבעלים לאחר שנגמר דינו ולהיפטר, משום \u0003דאמר ליה\u0004 \u0005[ש\u0006\u0005יכול\u0006 הבעלים \u0005לומר לו\u0006 לשומר\u0005]:\u0006 \u0003אי אהדרתיה ניהלי\u0004 \u0005[אם היית מחזירו,\u0006 את השור, \u0005לי]\u0006 לפני שהועמד בדין — \u0003הוה מערקנא ליה לאגמא\u0004 \u0005[הייתי מבריח אותו לאגם]\u0006 ולא היו יכולים לדון אותו בסקילה, \u0003השתא אתפשתיה לתוראי בידא דלא יכילנא לאשתעויי דינא בהדיה\u0004 \u0005[עכשיו מסרת את שורי ביד של מי שאיני יכול להתדיין עימו].\u0006","\u0003ור' יעקב סבר\u0004 \u0005[סבור]:\u0006 \u0003גומרין דינו של שור\u0004 אף \u0003שלא בפניו,\u0004 ומשום כך יכול השומר להיפטר, \u0003דאמר ליה\u0004 \u0005[שיכול\u0006 השומר \u0005לומר לו]\u0006 לבעלים בתשובה על טענתו: \u0003סוף סוף\u0004 הרי \u0003מיגמר הוו גמרי ליה לדינא\u0004 \u0005[היו גומרים את דינו]\u0006 של השור בכל מקום שהוא, ונמצא אם כן שלא אני גרמתי לשורך שייסקל בכך שלא החזרתי לך אותו קודם העמדתו בדין.","ומבררים: לדרך זו \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים],\u0006 מהו המקור לדינם? — נאמר \u0003\"השור יסקל וגם בעליו יומת\"\u0004 (שמות כא, כט), ללמדנו: \u0003כמיתת הבעלים\u0004 (אדם) — \u0003כך מיתת השור.\u0004 \u0003מה בעלים\u0004 אם הרגו, אין הם נידונים למיתה אלא \u0003בפניהם\u0004 — \u0003אף שור\u0004 אינו נידון אלא \u0003בפניו.\u0004","\u0003ור' יעקב\u0004 אומר שאין להשוות בין אדם לשור לענין זה, שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בעלים\u0004 צריך לדונם בפניהם כי \u0003בני טענה נינהו\u0004 \u0005[הם],\u0006 שאם יש להם לטעון יטענו ויגנו על עצמם. \u0003אלא שור\u0004 האם \u0003בר טענתא\u0004 \u0005[בן טענה]\u0006 \u0003הוא?\u0004 הרי אין השור יכול לטעון, ומה לי בפניו ומה לי שלא בפניו.","שנינו במשנה: \u0003מסרו\u0004 בעליו של השור \u0003לשומר חנם ולשואל\u0004 לנושא שכר (שומר דבר בשכר) ולשוכר — נכנסו תחת (במקום) הבעלים. ובאותו ענין עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעה נכנסו\u0004 בהתחייבות \u0003תחת הבעלים, ואלו הן: שומר חנם והשואל, נושא שכר\u0004 \u0003והשוכר.\u0004 \u0003הרגו\u0004 השוורים אדם בזמן שהיו ברשותם של אלה, אם השוורים היו \u0003תמין\u0004 בזמן שהרגו — הריהם \u0003נהרגין ופטורין מן הכופר,\u0004 ואם הרגו כשהם \u0003מועדין\u0004 — \u0003נהרגין ומשלמין את הכופר, וחייבין\u0004 השומרים בין בשור תם ובין במועד \u0003להחזיר דמי שור לבעליו, חוץ משומר חנם.\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 על כך בתמיהה \u0005:\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דנטריה\u0004 \u0005[אם ששמרו]\u0006 כראוי ובכל זאת הרג השור — \u0003אפילו כולהו נמי ליפטרו\u0004 \u0005[\u0006\u0005כולם גם כן ייפטרו]\u0006 מתשלום דמי שור לבעלים, ולא רק שומר חנם, שהרי עשו מה שהיה עליהם לעשות, \u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003לא נטריה\u0004 \u0005[שמרו]\u0006 — \u0003אפילו שומר חנם ניחייב\u0004 \u0005[שיתחייב],\u0006 שהרי הוא צריך לשומרו!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — באופן \u0003דנטריה\u0004 \u0005[ששמרו]\u0006 \u0003שמירה פחותה\u0004 (מזערית) \u0003ולא נטריה\u0004 \u0005[שמרו]\u0006 \u0003שמירה מעולה.\u0004 וזהו ההבדל בין שומר חנם לשאר השומרים: \u0003שומר חנם כלתה לו\u0004 חובת \u0003שמירתו,\u0004 שמאחר שאינו מקבל שכר על השמירה מילא את אחריותו גם בשמירה כזו, אבל \u0003הנך\u0004 \u0005[האחרים]\u0006 שיש להם אחריות גדולה יותר \u0003לא כלתה\u0004 חובת \u0003שמירתן.\u0004","ומבררים את הנאמר בברייתא. \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא ברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר,\u0004"],["ש\u0003דאמר: שוכר כשומר חנם דמי\u0004 \u0005[נחשב]\u0006 לענין אחריות — \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003חוץ משומר חנם והשוכר,\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר: שוכר כנושא שכר דמי\u0004 \u0005[נחשב]\u0006 — \u0003ניתני\u0004 \u0005[שישנה]:\u0006 \u0003חוץ משומר חנם,\u0004 אבל לשיטתו צריך היה להוסיף עוד ולשנות: \u0003וכולן במועדין פטורין לענין כופר,\u0004 שהרי ר' יהודה סבור (במשנה הבאה) ששור מועד די לו בשמירה פחותה. ואם כן, ברייתא זו לפי איזו שיטה היא?","\u0003אמר רב הונא בר חיננא: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' אליעזר היא,\u0004 שחלק על ר' יהודה בדין שור מועד ו\u0003אמר:\u0004 מועד \u0003אין לו שמירה אלא סכין.\u0004 כלומר, אין שום שמירה למועד שתהא מועילה להסיר מן הבעלים (ולענייננו, מן השומרים) את האחריות ואת חובת הכופר, \u0003ו\u0004אולם \u0003לענין שוכר סבר לה\u0004 \u0005[סבור הוא]\u0006 כשיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: שוכר כנושא שכר דמי\u0004 \u0005[נחשב].\u0006","\u0003אביי אמר: לעולם\u0004 תפרש את הברייתא \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 ומה שהיה קשה לך בדינו של השוכר — יש לשנות את גרסת הברייתא, \u0003ו\u0004כמו שהיה \u0003מחליף רבה בר אבוה\u0004 את גירסת הברייתא ביחס לדעות ושמות אומריהן, \u0003ותני\u0004 \u0005[וכך היה שונה]:\u0006 \u0003שוכר כיצד משלם? ר' מאיר אומר: כשומר שכר,\u0004 ו\u0003ר' יהודה אומר: כשומר חנם.\u0004","\u0003אמר ר' אלעזר: מסר\u0004 הבעלים את \u0003שורו לשומר חנם, הזיק\u0004 השור — \u0003חייב\u0004 השומר בתשלומי הנזק, \u0003הוזק\u0004 השור — \u0003פטור.\u0004","ומבררים, \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דקביל עליה\u0004 \u0005[אם\u0006 מדובר כאן \u0005שקיבל\u0006 השומר \u0005עליו]\u0006 את \u0003שמירת נזקיו\u0004 — \u0003אפילו הוזק נמי ליחייב\u0004 \u0005[גם כן שיתחייב],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003לא קביל עליה\u0004 \u0005[קיבל עליו]\u0006 \u0003שמירת נזקיו\u0004 — \u0003אפילו הזיק נמי ליפטר\u0004 \u0005[גם כן שייפטר]\u0006 מכל תשלום!","\u0003אמר רבא: לעולם\u0004 תפרש שמדובר כאן \u0003שקיבל עליו שמירת נזקיו, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003כגון שהכיר בו\u0004 השומר בשור \u0003שהוא נגחן. וסתמא דמילתא\u0004 \u0005[וסתמו של דבר]\u0006 מניחים אנו כי בשור כזה ש\u0003לא אזיל איהו ומזיק אחריני\u0004 \u0005[ילך הוא,\u0006 השור, \u0005ויזיק אחרים]\u0006 — \u0003קביל עליה\u0004 \u0005[קיבל עליו\u0006 אחריות לשמירתו\u0005],\u0006 שהרי הכיר בו שהוא נגחן, אבל \u0003דאתי אחריני ומזקי ליה לדידיה\u0004 \u0005[שיבואו אחרים ויזיקו אותו עצמו],\u0006 את השור הנגחן — \u0003לא אסיק אדעתיה\u0004 \u0005[העלה על דעתו],\u0006 וממילא לא קיבל עליו להתחייב בשמירה על כך.","\u0003קשרו בעליו\u0004 את השור \u0003במוסרה\u0004 (חבל) \u0003ונעל בפניו\u0004 את הדלת \u0003כראוי, ויצא\u0004 השור \u0003והזיק, אחד\u0004 שור \u0003תם ואחד\u0004 שור \u0003מועד\u0004 — \u0003חייב,\u0004 שאין זו שמירה מספיקה ועדיין אחראי הוא על נזקיו, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר:\u0004 אם היה זה שור \u0003תם\u0004 — \u0003חייב, ו\u0004אולם \u0003מועד\u0004 — \u0003פטור, שנאמר\u0004 בחיוב שור מועד: \u0003\"ולא ישמרנו בעליו\"\u0004 (שמות כא, לו), \u0003ו\u0004אילו במקרה זה שבמשנה \u0003שמור הוא זה,\u0004 שהרי נקט אמצעים מסויימים של שמירה עבורו.","\u0003ר' אליעזר אומר: אין לו\u0004 למועד \u0003שמירה אלא סכין\u0004 (כאשר שוחטים אותו), כלומר, לגבי מועד כל שמירה אינה פוטרת את הבעלים מאחריות לנזקים.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר?\u0004 — \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003סתם שוורים לאו\u0004 \u0005[לא]\u0006 \u0003בחזקת שימור קיימי\u0004 \u0005[עומדים],\u0006 שאין דרך אנשים לשמור שווריהם, \u0003ואמר רחמנא\u0004 \u0005[ואמרה תורה]:\u0006 \u0003תם ניחייב\u0004 \u0005[יהיה חייב]\u0006 עליו, \u0003דניבעי ליה\u0004 \u0005[שנצריך לו]\u0006 לפחות \u0003שמירה פחותה\u0004 (מזערית) בחבל, \u0003הדר אמר רחמנא\u0004 \u0005[חזרה\u0006 ו\u0005אמרה תורה]\u0006 \u0003\"ולא ישמרנו\" גבי\u0004 \u0005[אצל]\u0006 \u0003מועד,\u0004 לומר \u0003דניבעי ליה\u0004 \u0005[שנצריך לו]\u0006 לא \u0003שמירה\u0004 פחותה בלבד אלא \u0003מעולה, ויליף\u0004 \u0005[ולמד]\u0006 בגזירה שווה \u0003נגיחה לתם נגיחה למועד,\u0004 ללמוד מכאן שגם שור תם וגם שור מועד צריכים שמירה מעולה. ולכן כל מי ששמר את שורו שמירה שאינה מעולה — חייב באחריות.","ואילו \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003סתם שוורים בחזקת שימור קיימי\u0004 \u0005[עומדים],\u0006 שאנשים שומרים עליהם שמירה כלשהי, פחותה, ובכל זאת \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003תם נשלם\u0004 \u0005[ישלם],\u0006 ומכאן נלמד \u0003דניבעי ליה\u0004 \u0005[שנצריך עבורו]\u0006 \u0003שמירה מעולה. הדר אמר רחמנא\u0004 \u0005[חזרה\u0006 ו\u0005אמרה תורה]\u0006 \u0003\"ולא ישמרנו\" גבי\u0004 \u0005[אצל]\u0006 \u0003מועד,\u0004 להדגיש שוב: \u0003דנעביד ליה\u0004 \u0005[שיעשה לו]\u0006 \u0003שמירה מעולה,\u0004 אם כן \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003ריבוי אחר ריבוי,\u0004 \u0003ו\u0004כלל בידינו ש\u0003אין ריבוי אחר ריבוי אלא למעט,\u0004 וכוונתו: \u0003מיעט הכתוב לשמירה מעולה,\u0004 שאצל מועד אין צורך בשמירה מעולה, אלא בשמירה כלשהי יוצא מידי אחריותו, שיותר מכן אינו יכול לשמור.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 הלא נאמרה \u0003נגיחה לתם\u0004 ו\u0003נגיחה למועד\u0004 להשוות את דיניהם — מכל מקום \u0003הא מיעט רחמנא\u0004 \u0005[הרי מיעטה התורה]\u0006 במועד, בהדגשה \u0003\"ולא ישמרנו\":\u0004 \u0003לזה,\u0004 למועד, \u0003ולא לאחר,\u0004 לתם.","ושואלים: \u0003והא מיבעי ליה\u0004 \u0005[והרי צריך אותו]\u0006 \u0003ללאו,\u0004 לעצם ההלכה שמתחייב על שלא שמרו שמירה מעולה! ומשיבים: \u0003אם כן,\u0004 שרק לכך נצרך הכתוב \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"ולא ישמור\" מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"ולא ישמרנו\"?\u0004 — כוונתו להדגיש: \u0003לזה ולא לאחר.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 שיש בה שיטה רביעית, \u0003ר' אליעזר בן יעקב אומר: אחד תם ואחד מועד ששמרו שמירה פחותה\u0004 — \u0003פטור.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — מצד אחד \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר: מועד בשמירה פחותה סגי ליה\u0004 \u0005[די לו],\u0006 \u0003ו\u0004מצד אחר \u0003יליף\u0004 \u0005[ולמד]\u0006 \u0003נגיחה לתם ונגיחה למועד\u0004 בגזירה שווה, ומכאן הוא מסיק שכשם ששור מועד די לו בשמירה פחותה — כך שור תם די לו בשמירה פחותה.","ובבירור דעתו של ר' יהודה \u0003אמר רב אדא בר אהבה: לא פטר ר' יהודה אלא צד\u0004 (חלק) \u0003העדאה שבו.\u0004 שמה שאמר ר' יהודה ששור מועד פטור עליו אם שמרו שמירה כלשהי — הרי זה רק לגבי מחצית הנזק הנוספת שמתחייב בה בהיותו מועד, \u0003אבל צד תמות במקומה עומדת,\u0004 שהחיובים החלים עליו בהיותו תם לא פקעו, ואם לא שמר את השור המועד שמירה מעולה — יהיה חייב לשלם כתם, חצי נזק.","\u0003אמר רב:\u0004 שור שהיה \u0003מועד ל\u0004נגוח ב\u0003קרן ימין\u0004 — \u0003אינו מועד לקרן שמאל.\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אליבא דמאן\u0004 \u0005[לפי שיטת מי]\u0006 אמר זאת? \u0003אי אליבא\u0004 \u0005[אם לפי שיטת]\u0006 \u0003ר' מאיר\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' מאיר: \u0003אחד תם ואחד מועד שמירה מעולה בעי\u0004 \u0005[צריך\u0006 הוא\u0005]!\u0006 \u0003אי אליבא\u0004 \u0005[אם לפי שיטת]\u0006 \u0003ר' יהודה, מאי אריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003קרן שמאל? אפילו ב\u0004קרן \u0003ימין נמי\u0004 \u0005[גם כן]\u0006 \u0003אית ביה\u0004 \u0005[יש בו]\u0006 בשור \u0003צד תמות ואית ביה\u0004 \u0005[ויש בו]\u0006 \u0003צד מועדת!\u0004 שהרי נשאר צד תמות בכל מועד, אפילו באותה קרן!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לעולם\u0004 דעתו \u0003כר' יהודה, ולא סבירא ליה\u0004 \u0005[ואינו סבור]\u0006 כשיטתו של \u0003רב אדא בר אהבה,\u0004 שצד תמות אינו בטל, \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]:\u0006 \u0003כי האי גוונא\u0004 \u0005[באופן זה]\u0006 \u0003הוא דמשכחת ביה\u0004 \u0005[שאתה מוצא בו]\u0006 בשור \u0003צד תמות ומועדת,\u0004 כגון שהוא מועד לקרן אחת ולא לשניה,"],["\u0003אבל מועד לגמרי לא משכחת ביה\u0004 \u0005[אין אתה מוצא בו]\u0006 \u0003צד תמות כלל,\u0004 שאם היה כבר מועד לנגיחה בשתי הקרניים אין בו עוד צד תמות. שנינו במשנה ש\u0003ר' אליעזר אומר: אין לו\u0004 לשור מועד \u0003שמירה אלא סכין. אמר רבה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשור מועד \u0003\"ולא ישמרנו\"\u0004 (שמות כא, כט), ומשמעו: \u0003שוב\u0004 מעתה \u0003אין\u0004 מועילה \u0003לו\u0004 כל \u0003שמירה ל\u0004שור \u0003זה,\u0004 והריהו אחראי לכל נזקיו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003אלא מעתה\u0004 שאתה מפרש בדרך זו, מה \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 בבור \u0003\"ולא יכסנו\"\u0004 (שמות כא, לג) \u0003נמי\u0004 \u0005[גם כן]\u0006 תפרש על דרך זו — \u0003שוב אין לו כיסוי לזה,\u0004 שבור שנתגלה שוב אין מועיל לו כיסוי לפטור את בעליו מנזקיו?","","","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 ש\u0005כך\u0006 הוא \u0005גם כן]\u0006 הדין, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כסהו\u0004 את הבור \u0003כראוי ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור.\u0004 משמע שגם בור שנפתח יש לו כיסוי!","\u0003אלא\u0004 \u0003אמר אביי:\u0004 יש לדחות הסבר זה של רבה בשיטת ר' אליעזר, ולומר כך: \u0003היינו טעמיה\u0004 \u0005[זהו טעמו]\u0006 של \u0003ר' אליעזר, כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: מניין שלא יגדל אדם כלב רע בתוך ביתו, ואל יעמיד סולם רעוע בתוך ביתו\u0004 — \u0003שנאמר: \"ולא תשים דמים בביתך\"\u0004 (דברים כב, ח), ומשום כך גם אסור לו לאדם להחזיק שור מועד בביתו, שכיוון שיודע בו שהוא מזיק צריך לבערו מן העולם. והוא שאמר ר' אליעזר שאין לו שמירה, אלא צריך לשוחטו, שלא יזיק.","","\u0003שור שנגח את הפרה\u0004 והמיתה \u0003ונמצא עוברה\u0004 של הפרה מת \u0003בצדה,\u0004 \u0003ואין ידוע אם עד שלא\u0004 (לפני ש) \u0003נגחה ילדה,\u0004 ומת הוולד מעצמו ולא על ידי הנגיחה, \u0003אם משנגחה ילדה\u0004 והנגיחה היא שגרמה שימות הוולד, הרי במקרה כזה \u0003משלם\u0004 בעליו של השור הנוגח \u0003חצי נזק\u0004 אם היה זה שור תם \u0003ל\u0004נזק \u0003פרה, ורביע\u0004 (רבע) \u0003נזק\u0004 משלם \u0003ל\u0004נזק ה\u0003ולד,\u0004 שמפני הספק משלם חצי הסכום מן המחצית שמשלם תם, שיש ספק אם הוא זה שגרם למות הוולד.","\u0003וכן\u0004 מקרה נוסף שיש בו ספק דומה: \u0003פרה\u0004 תמה \u0003שנגחה את השור ונמצא\u0004 אחר כך \u0003ולדה בצדה\u0004 חי או מת, \u0003ואין ידוע אם עד שלא נגחה\u0004 את השור \u0003ילדה\u0004 ולא היה אז הוולד חלק מגופה בשעת הנגיחה, \u0003אם משנגחה ילדה\u0004 — הרי במקרה זה שמשלמים את הנזק מגופו של המזיק כדין שור תם — \u0003משתלם חצי נזק מן הפרה\u0004 ככל שור תם, \u0003ו\u0004רק \u0003רביע נזק מן הולד,\u0004 שאם אין בדמי הפרה כדי לשלם כל מחצית הנזק כדי להשלים את הסכום — אין גובים חצי דמי הולד אלא רק רבע מהם, מפני הספק.","\u0003אמר רב יהודה אמר שמואל:\u0004 משנתנו \u0003זו\u0004 כ\u0003דברי סומכוס,\u0004 ש\u0003אמר:\u0004 \u0003ממון המוטל בספק,\u0004 שאי אפשר לברר למי הוא שייך — \u0003חולקין\u0004 אותו ביניהם הצדדים המתדיינים עליו. \u0003אבל חכמים אומרים: זה כלל גדול בדין: המוציא מחבירו עליו הראיה,\u0004 ואין חולקים במקרה של ספק, אלא התובע ומבקש להוציא מידי חבירו הוא שצריך להוכיח את דבריו.","ושואלים: \u0003למה לי למימר\u0004 \u0005[לומר]\u0006 \u0003\"זה כלל גדול בדין\"?\u0004 ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, ש\u0003אפילו\u0004 כאשר \u0003ניזק\u0004 שהוא התובע \u0003אומר: ברי\u0004 (וודאי) לי שכך היה הדבר, \u0003ומזיק\u0004 שהוא הנתבע \u0003אומר: שמא,\u0004 שהמזיק אינו מכחיש בוודאות, אלא אומר שהוא אינו בטוח, וייתכן שלא כך היה — אף במקרה זה \u0003המוציא מחבירו עליו הראיה,\u0004 ואין אומרים שכיוון שהניזק טוען טענת וודאי — אין טענת הספק של המזיק מועילה לפוטרו.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נאמר \"זה כלל גדול בדין\" \u0003לכי הא דאתמר\u0004 \u0005[לכמו זה שנאמר]:\u0006 \u0003המוכר שור לחבירו ונמצא\u0004 השור \u0003נגחן, רב אמר: הרי זה מקח טעות,\u0004 משום שיכול הקונה לטעון שהוא קנה שור לעבודה, ואין השור ראוי לכך מפני שהוא נגחן. \u0003ושמואל אמר: יכול שיאמר לו\u0004 המוכר \u0003ל\u0004צורך \u0003שחיטה מכרתיו לך.\u0004","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 חולקים כאן בסברה? \u0003וניחזי\u0004 \u0003אי גברא דזבין לרדיא, אי גברא דזבין לנכסתא\u0004 \u0005[ונראה אם\u0006 הקונה הוא \u0005איש שקונה\u0006 שוורים \u0005לחרישה,\u0006 או \u0005אם\u0006 הוא \u0005איש שקונה\u0006 שוורים \u0005לשחיטה]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003בגברא דזבין להא ולהא\u0004 \u0005[באיש שקונה\u0006 שוורים \u0005לזה ולזה],\u0006 לחרישה ולשחיטה, ולא ברור לשם מה עתה קנה. ושואלים: ובכל זאת, \u0003וניחזי\u0004 \u0005[ונראה]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 שילם בתמורה \u0003דמי\u0004 שור ל\u0003רדיא\u0004 \u0005[חרישה]\u0006 שהם מרובים — הרי קנהו \u0003לרדיא\u0004 \u0005[לחרישה]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 שילם בתמורה \u0003דמי נכסתא\u0004 \u0005[\u0006שור \u0005לשחיטה]\u0006 — קנהו \u0003לנכסתא\u0004 \u0005[לשחיטה]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאוקיר בישרא וקאי בדמי רדיא\u0004 \u0005[שהתייקר\u0006 מחיר \u0005הבשר ועומד\u0006 מחירו של שור לשחיטה \u0005ב\u0006אותו \u0005מחיר\u0006 של שור ל\u0005חרישה].\u0006 ובזה נחלקו רב ושמואל, אם יכול הקונה לטעון שמיקח טעות הוא, או שיכול המוכר לטעון כי לשחיטה נמכר, ועל הקונה ששילם להביא ראיה לדבריו.","","","ועל כך \u0003אמרי\u0004 \u0005[אומרים]:\u0006"],["לדברי רב שאמר שמיקח טעות הוא, משמע כי מוטל על המוכר להשיג מעות ולהשיב לו את כספו, ואינו יכול להשאיר את שורו ביד הקונה כפיצוי, אף שהוא שווה בדיוק מה ששילם לו. ועל כך יש לתמוה: \u0003ואי ליכא לאשתלומי מיניה\u0004 \u0005[ו\u0006גם \u0005אם אין\u0006 אפשרות \u0005לגבות תשלום ממנו]\u0006 מן המוכר, שהוציא כבר את הכסף ואין לו ממה לשלם, \u0003לישקליה לתורא בזוזי\u0004 \u0005[\u0006מדוע \u0005ש\u0006לא \u0005יקח\u0006 הקונה \u0005אותו, את השור\u0006 עצמו \u0005ב\u0006עבור \u0005הכסף],\u0006 \u0003דאמרי אנשי\u0004 \u0005[ש\u0006הרי כך \u0005אומרים אנשים]\u0006 בפתגם עממי: \u0003ממרי רשוותך פארי אפרע\u0004 \u0005[מן החייב לך,\u0006 אפילו \u0005סובין היפרע],\u0006 שכל דבר יפה כדי לפרוע בו חוב!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר הלכה זו אלא במקום \u0003דאיכא לאשתלומי מיניה\u0004 \u0005[שיש\u0006 אפשרות \u0005לגבות\u0006 \u0005התשלום\u0006 בכסף \u0005ממנו,\u0006 מן המוכר\u0005]\u0006 והקונה תובע את כספו. וחוזרים לבאר את המחלוקת.","\u0003רב אמר: הרי זה מקח טעות,\u0004 וטעמו, אומרים אנו ככלל: \u0003זיל בתר רובא\u0004 \u0005[לך אחר הרוב],\u0006 \u0003ורובא דאינשי לרדיא\u0004 \u0005[ורוב בני אדם לחרישה]\u0006 \u0003הוא דזבני\u0004 \u0005[שקונים].\u0006 \u0003ושמואל אמר: יכול שיאמר לו: לשחיטה מכרתיו לך, ו\u0004טעמו: \u0003לא אזלינן בתר רובא\u0004 \u0005[אין אנחנו הולכים אחר הרוב]\u0006 במקרה כזה\u0005.\u0006 \u0003כי אזלינן בתר רובא\u0004 \u0005[כאשר הולכים אנו אחר הרוב]\u0006 הרי זה דווקא \u0003ב\u0004עניינים של \u0003איסורא\u0004 \u0005[איסור\u0006 והיתר\u0005],\u0006 \u0003אבל ב\u0004עניינים של \u0003ממונא\u0004 \u0005[ממון]\u0006 כמו בענייננו \u0003לא אזלינן בתר רובא\u0004 \u0005[אין אנו הולכים אחר הרוב],\u0006 \u0003אלא המוציא מחבירו עליו הראיה.\u0004","ולעיקר הדברים שאמר רב יהודה בתחילת הסוגיה, שמשנתנו כשיטת סומכוס היא, ואין כן דעת חכמים, \u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שור שנגח את הפרה ונמצא עוברה בצדה, ואינו יודע אם עד שלא נגחה ילדה אם משנגחה ילדה\u0004 והנגיחה היא שגרמה שימות הוולד, הרי במקרה כזה \u0003משלם\u0004 בעליו של השור \u0003חצי נזק ל\u0004נזק ה\u0003פרה, ורביע\u0004 (רבע) \u0003נזק ל\u0004נזק ה\u0003ולד,\u0004 אלו \u0003דברי סומכוס, וחכמים אומרים: המוציא מחבירו עליו הראיה.\u0004","\u0003אמר ר' שמואל בר נחמני: מניין\u0004 \u0003ל\u0004כלל זה של חכמים ש\u0003המוציא מחבירו עליו הראיה\u0004 — \u0003ש\u0004כאשר מינה משה את אהרון וחור לשפוט את העם \u0003נאמר: \"מי בעל דברים יגש אלהם\"\u0004 (שמות כד, יד), כלומר, למי שיש לו דין על חבירו (\"בעל דברים\") \u0003יגיש ראיה אליהם,\u0004 ומכאן שבעל הדבר, התובע, הוא שצריך להביא את הראיה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: הא\u0004 \u0005[\u0006לדבר \u0005זה]\u0006 \u0003למה לי קרא\u0004 \u0005[כתוב]?\u0006 הלא \u0003סברא הוא: דכאיב ליה כאיבא אזיל לבי אסיא\u0004 \u0005[\u0006זה \u0005שכואב לו כאב הולך לבית הרופא],\u0006 כלומר, מי שיש לו בעיה מובן שהוא זה שצריך ללכת ולדאוג לפתרון בעייתו. ואף מי שיש לו טענה על חבירו הוא שצריך להוכיח את דבריו!","\u0003אלא קרא\u0004 \u0005[הכתוב]\u0006 בא ללמדנו \u0003לכ\u0004 פי שאמר \u0003רב נחמן אמר רבה בר אבוה,\u0004 ש\u0003אמר רב נחמן אמר רבה בר אבוה: מניין שאין\u0004 בית הדין \u0003נזקקין\u0004 (מתייחסים) \u0003אלא לתובע תחלה,\u0004 שקודם שומעים את הטענות של התובע ודנים בהן, ואחר כך שומעים את הטענות של הנתבע ודנים בהן — \u0003שנאמר: \"מי בעל דברים יגש אלהם\"\u0004 כוונתו: \u0003יגיש דבריו\u0004 \u0003אליהם\u0004 תחילה\u0003.\u0004","ומעירים, \u0003אמרי נהרדעי\u0004 \u0005[אומרים\u0006 חכמי \u0005נהרדעא]:\u0006 למרות כלל זה \u0003פעמים שנזקקין\u0004 בית דין דווקא \u0003לנתבע תחלה\u0004 ושומעים את הטענות שיש לו לטעון כדי להתגונן מפני תביעה עליו, ואין ממתינים לשמוע תחילה את טענות התובע, \u0003והיכי דמי\u0004 \u0005[וכיצד הוא]?\u0006 — במקרה \u0003דקא זילי נכסיה\u0004 \u0005[שיורד ערך נכסיו]\u0006 של הנתבע בגלל התביעה — במקרה כזה שומעים בית דין תחילה את הנתבע ומאפשרים לו לטעון את טענותיו שלו עוד לפני התובע, כדי שיוכל להיפטר מן התביעה ולמכור את נכסיו בערכם האמיתי.","שנינו במשנה: \u0003וכן פרה שנגחה את השור\u0004 ונמצא ולדה בצידה — משתלם חצי נזק מן הפרה ורביע נזק מן הוולד. ותוהים: \u0003חצי נזק ורביע נזק\u0004 מה מקום כאן לאלה? שהרי מלשון זו משמע שמשלם חצי נזק ומוסיף עוד רבע, והרי זה עולה לשלושה רבעים מן הנזק, והלא שור תם \u0003פלגא נזקא\u0004 \u0005[חצי נזק]\u0006 \u0003הוא דבעי שלומי\u0004 \u0005[שצריך לשלם],\u0006 \u0003כולי נזקא נכי רבעא מאי עבידתיה\u0004 \u0005[כל הנזק פחות רבע מה מעשהו,\u0006 מה עניינו\u0005]?\u0006","\u0003אמר אביי: חצי נזק\u0004 כוונתו: חצי מחיוב חצי הנזק, כלומר, \u0003אחד מארבעה\u0004 (רבע) \u0003בנזק,\u0004 שכיון שיש מקום לומר שיש שותף בדבר (ולד הפרה), אין בעל הפרה משלם הכל (חצי נזק, כשור תם) מן הפרה, אלא מחצית ממה שהיה עליו לשלם, דהיינו רבע נזק. \u0003ורביע נזק\u0004 שמקבל מן הוולד כוונתו \u0003אחד משמנה\u0004 (שמינית) \u0003בנזק,\u0004 שמשום השותפות עם הפרה אינו צריך לשלם אלא רבע נזק, ובגלל הספק אם נולד קודם הנגיחה — משלם מחצית מכך, דהיינו שמינית. ונמצא בעל השור מקבל סך הכל שלוש שמיניות של הנזק.","ומעירים: \u0003ואי\u0004 \u0005[ואם]\u0006 ה\u0003פרה ו\u0004ה\u0003ולד דחד נינהו\u0004 \u0005[של\u0006 אדם \u0005אחד הם]\u0006 \u0003הכי נמי דמצי אמר ליה\u0004 \u0005[כך גם כן שיכול לומר לו]\u0006 הניזק \u0003לבעל פרה: ממה נפשך\u0004 \u0005[כרצונך],\u0006 בכל אופן שהוא \u0003חצי נזק הב\u0004 (תן) \u0003לי\u0004 בין מן הפרה בין מן הוולד, שהם שניהם שלך. \u0003אלא, לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו שבמשנתנו אלא בזמן שהיתה \u0003פרה דחד\u0004 \u0005[של אחד]\u0006 \u0003וולד דחד\u0004 \u0005[של אחד,\u0006 אחר\u0005],\u0006 שיכול כל אחד לטעון שאינו אלא שותף בנזק.","\u0003ו\u0004אף במקרה זה \u0003אי דקדים תבעיה\u0004 \u0005[אם שקדם\u0006 הניזק \u0005ותבעו]\u0006 \u0003לבעל פרה תחלה\u0004 — \u0003הכי נמי דאמר ליה\u0004 \u0005[כך גם כן שיכול לומר לו]\u0006 \u0003לבעל\u0004 ה\u0003פרה:\u0004 ה\u0003פרה דידך\u0004 \u0005[שלך]\u0006 בוודאי היא \u0003אזיקתן\u0004 \u0005[הזיקה אותי],\u0006 \u0003הב\u0004 (תן) \u0003לי ראיה דאית\u0004 \u0005[שיש]\u0006 \u0003לך שותפי\u0004 \u0005[שותפים],\u0006 כלומר, אתה צריך להוכיח שוולד זה היה שותף במעשה על מנת להיפטר ממלוא התשלום, ואם לא כן — צריך לשלם כל חצי הנזק.","\u0003אלא\u0004 כאן מדובר \u0003דקדים תבעיה\u0004 \u0005[שקדם\u0006 הניזק, \u0005ותבעו]\u0006 \u0003לבעל ולד תחלה, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הפרה: \u0003גלית\u0004 בכך \u0003אדעתך\u0004 \u0005[את דעתך]\u0006 שאתה סבור \u0003דשותפא אית\u0004 \u0005[ששותף יש]\u0006 \u0003לי,\u0004 שהרי תבעת גם מבעל הוולד, ולכן לא אשלם את כל המגיע ממני (חצי נזק) אלא את חציו בלבד.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אף על גב דקדים תבעיה\u0004 \u0005[אף על פי שקדם\u0006 ו\u0005תבעו]\u0006 הניזק \u0003לבעל פרה תחלה, מצי מדחי ליה\u0004 \u0005[יכול\u0006 בעל הפרה \u0005לדחות אותו],\u0006 בטענה \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003מידע ידעי אנא דשותפא אית\u0004 \u0005[יודע אני ששותף יש]\u0006 \u0003לי\u0004 שהוא בעל הוולד.","על הסברו זה של אביי מקשה \u0003רבא: אטו\u0004 \u0005[וכי]\u0006 \u0003\"אחד מארבעה בנזק\" ו\"אחד משמנה בנזק\" קתני\u0004 \u0005[שנה]\u0006 התנא במשנתנו? הלא \u0003\"חצי נזק\" ו\"רביע נזק\" קתני\u0004 \u0005[שנה]!\u0006 \u0003אלא אמר רבא\u0004 יש לדחות הסבר זה ולומר הסבר אחר: \u0003לעולם\u0004 מדובר במשנתנו \u0003בפרה וולד דחד\u0004 \u0005[של\u0006 אדם \u0005אחד],\u0006 \u0003והכי קאמרינן\u0004 \u0005[וכך אנו אומרים]:\u0006 \u0003איתה\u0004 \u0005[\u0006אם \u0005יש]\u0006 את ה\u0003פרה\u0004 לפנינו — \u0003משתלם חצי נזק מפרה\u0004 עצמה."],["\u0003ליתא\u0004 \u0005[\u0006אם \u0005אין]\u0006 את ה\u0003פרה\u0004 לפנינו, כגון שברחה — \u0003משתלם רביע נזק מולד.\u0004","ומעירים: מדברי רבא אלו עולה כי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003לא ידעינן אי הוה\u0004 \u0005[יודעים אנו אם היה]\u0006 \u0003ולד בהדה\u0004 \u0005[עימה]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003נגחה אי\u0004 \u0005[או]\u0006 \u0003לא הוה\u0004 \u0005[היה],\u0006 ולכן משלם רבע נזק. \u0003אבל אי פשיטא לן דהוה\u0004 \u0005[אם\u0006 \u0005פשוט,\u0006 ברור \u0005לנו שהיה]\u0006 \u0003ולד בהדה\u0004 \u0005[עימה]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003נגחה\u0004 — \u0003משתלם כוליה\u0004 \u0005[כל]\u0006 \u0003חצי\u0004 ה\u0003נזק מ\u0004גוף ה\u0003ולד\u0004 אם הפרה איננה.","ומעירים, כי \u0003רבא\u0004 הולך כאן \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: פרה שהזיקה\u0004 כשהיתה מעוברת — \u0003גובה מולדה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003גופה היא\u0004 והוא כחלק ממנה, וכיון שהיה חלק מגופה יכול לגבות ממנו. לעומת זאת \u0003תרנגולת שהזיקה\u0004 — \u0003אינו גובה מביצתה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003פירשא בעלמא\u0004 \u0005[פרש סתם]\u0006 \u0003הוא,\u0004 כלומר, אין הביצה חלק מגופה של התרנגולת אלא דבר נפרד ממנה, ולכן אינו יכול לגבות תשלום שגובים רק מגוף התרנגולת.","\u0003ו\u0004עוד \u0003אמר רבא:\u0004 כאשר צריכים להעריך את הנזקים בשור שנגח את הפרה ונמצא עוברה מת לצדה \u0003אין שמין ל\u0004נזק ה\u0003פרה בפני עצמה, ולולד בפני עצמו. אלא שמין לולד על גב\u0004 ה\u0003פרה,\u0004 שמעריכים את הנזק של פרה מעוברת, ועל ידי כך נמצא סכום הנזק פוחת קצת. \u0003שאם אי\u0004 (אין) \u0003אתה אומר כן\u0004 — \u0003נמצא אתה מכחיש\u0004 (מפסיד) \u0003את המזיק.\u0004","\u0003וכן אתה מוצא בקוטע יד עבדו של חבירו\u0004 שאין מעריכים כמה אדם מוכן לקבל בעד קטיעת יד של עבדו, אלא מעריכים מה הבדל המחיר בין עבד שלם ועבד קטוע יד. \u0003וכן אתה מוצא דבמזיק\u0004 חלק מ\u0003שדה של חבירו\u0004 שאין מעריכים את הנזק של מקום הנזק לבד כמה הוא שווה אילו היה נמכר בעצמו, אלא מעריכים את הפחת ביחס לשווי חלקת אדמה גדולה יותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 עיקר טענתו של רבא הוא שהמזיק נמצא מפסיד, \u0003ו\u0004אולם \u0003אי דינא\u0004 \u0005[אם הדין]\u0006 \u0003הוא\u0004 כך — \u0003ליכחוש\u0004 \u0005[שיפסיד]\u0006 \u0003מזיק\u0004 ומה טעם הוא זה?","אמר רב אשי: \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המזיק: \u0003פרה מעברתא אזיקתך, פרה מעברתא שיימנא\u0004 \u0005[פרה מעוברת הזקתיך, פרה מעוברת אני מעריך]\u0006 \u0003לך,\u0004 ואין זה מן הדין להעריך את הפרה לעצמה ואת העובר לעצמו.","אגב כך דנים בבעיה הבאה, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 לנו שאם היתה ה\u0003פרה\u0004 בבעלות \u0003דחד\u0004 \u0005[של\u0006 אדם \u0005אחד]\u0006 \u0003וולד דחד\u0004 \u0005[של\u0006 אדם \u0005אחד,\u0006 אחר\u0005]\u0006 — הרי הפיצוי עבור \u0003פיטמא\u0004 \u0005[הפיטום],\u0006 ערכה של הפרה המעוברת מחמת פיטומה, בוודאי משלמים \u0003לבעל פרה.\u0004 והשאלה היא: \u0003נפחא מאי\u0004 \u0005[הנפח מה\u0006 הוא\u0005],\u0006 כלומר, מה שפחת מחירה משום שעכשיו היא נראית פחות גדולה, למי משלמים? \u0003רב פפא אמר:\u0004 אף זה משלמים \u0003לבעל\u0004 ה\u0003פרה. רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: חולקין.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003חולקין.\u0004","\u0003הקדר שהכניס קדרותיו לחצר בעל הבית שלא ברשות\u0004 בעל הבית, \u0003ושברה בהמתו של בעל הבית\u0004 את הקדירות — \u0003פטור\u0004 בעל הבית. \u0003ואם הוזקה\u0004 בהמתו של בעל הבית \u0003בהן,\u0004 בקדירות — \u0003בעל הקדרות חייב. ו\u0004אולם \u0003אם הכניס\u0004 את הקדירות \u0003ברשות\u0004 — \u0003בעל החצר חייב\u0004 במה שהזיקה בהמתו את הקדירות.","וכן מי ש\u0003הכניס פירותיו לחצר בעל הבית שלא ברשות, ואכלתן בהמתו של בעל הבית\u0004 — \u0003פטור\u0004 בעל הבית. \u0003ואם הוזקה\u0004 בהמתו \u0003בהן\u0004 כגון שהחליקה עליהם — \u0003בעל הפירות חייב.\u0004 \u0003ואם הכניס ברשות\u0004 את פירותיו — \u0003בעל החצר חייב\u0004 במה שניזוקו על ידי בהמתו.","וכן אם \u0003הכניס שורו לחצר בעל הבית שלא\u0004"],["\u0003ברשות, ונגחו שורו של בעל הבית, או שנשכו כלבו של בעל הבית\u0004 — \u0003פטור\u0004 בעל הבית. \u0003נגח הוא,\u0004 שורו, את \u0003שורו של בעל הבית\u0004 — \u0003חייב. נפל\u0004 השור שהוכנס שלא ברשות \u0003לבורו\u0004 של בעל הבית, \u0003והבאיש\u0004 (קלקל, הסריח) את \u0003מימיו\u0004 של הבור — \u0003חייב\u0004 בעל השור לשלם על קלקול המים. \u0003היה אביו או בנו\u0004 של בעל הבית \u0003לתוכו\u0004 (בתוך הבור) וכשנפל השור עליו הרגו — הרי זה \u0003משלם את הכופר. ואם הכניס\u0004 את השור \u0003ברשות\u0004 — \u0003בעל החצר חייב\u0004 בנזקים.","\u0003רבי אומר: בכולן,\u0004 בכל המקרים שנזכרו במשנה: בקדירות, בפירות ובשור — \u0003אינו חייב\u0004 בעל החצר, ואף אם נתן לאותו אדם רשות להכניס, \u0003עד שיקבל עליו\u0004 בעל הבית במפורש \u0003לשמור\u0004 את הדברים שהרשה להכניס לחצירו.","ומבררים את שיטת משנתנו. בתחילת המשנה נאמר שהקדר שהכניס קדירות לחצר בעל הבית שלא ברשות חייב בנזקים שנגרמו לבעל הבית על ידי הקדירות, ואפשר לדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שהכניס \u0003שלא ברשות\u0004 — חייב בעל הקדירות, \u0003הא\u0004 \u0005[הרי]\u0006 אם הכניס \u0003ברשות\u0004 — \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 \u0003בעל קדירות בנזקי בהמתו\u0004 של \u0003בעל\u0004 ה\u0003חצר, ולא אמרינן\u0004 \u0005[אומרים אנו]\u0006 כי \u0003קבולי קביל\u0004 \u0005[קיבל\u0006 על עצמו\u0005]\u0006 \u0003בעל\u0004 ה\u0003קדירות נטירותא\u0004 \u0005[שמירה]\u0006 של \u0003בהמתו של בעל\u0004 ה\u0003חצר\u0004 שלא תוזק בקדירותיו.","\u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 — כשיטת \u0003רבי היא,\u0004 ש\u0003אמר\u0004 בסוף המשנה: \u0003כל\u0004 נתינת רשות להכניס דבר לרשותו \u0003בסתמא\u0004 \u0005[בסתם]\u0006 וללא התנאה מפורשת לשמירה — \u0003לא קביל עליה נטירותא\u0004 \u0005[קיבל עליו\u0006 בכך בעל הבית \u0005שמירה].\u0006 והוא הדין למי שקיבל רשות להכניס דבר לחצר חבירו, שלא קיבל על עצמו יחד עם זה את שמירת הדבר שלא יוזק.","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005הסוף]\u0006 של אותה הלכה, ושם נאמר: \u0003אם הכניס ברשות\u0004 — \u0003בעל\u0004 ה\u0003חצר חייב, אתאן לרבנן\u0004 \u0005[באנו\u0006 איפוא \u0005ל\u0006שיטת \u0005חכמים]\u0006 החולקים על רבי, \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003בסתמא נמי קבולי קביל עליה נטירותא\u0004 \u0005[בסתם גם כן קיבל על עצמו שמירה],\u0006 שהרי נתן לו רק רשות להכניס, ולא פירש שהוא שומר על הקדירות מפני בהמתו, ובכל זאת הריהו מתחייב בנזקים.","\u0003ותו\u0004 \u0005[ועוד]\u0006 נאמר בסוף המשנה: \u0003רבי אומר בכולן אינו חייב עד שיקבל עליו בעל הבית לשמור,\u0004 ואם כן נמצא שמשנה זו \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 כשיטת \u0003רבי, ומציעתא\u0004 \u0005[ואמצעיתה]\u0006 \u0003רבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים!\u0006","\u0003אמר ר' זירא: תברא\u0004 \u0005[שבורה\u0006 חלוקה\u0005]\u0006 היא תחילת המשנה, שאינה לפי שיטה אחת ו\u0003מי ששנה זו לא שנה זו\u0004 ויש כאן שתי שיטות. \u0003רבא אמר:\u0004 אפשר לפרש שתחילת המשנה \u0003כולה\u0004 כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, ו\u0004כשהכניס \u0003ברשות\u0004 הרי \u0003שמירת קדירות קבל עליו בעל החצר ואפילו נשברו\u0004 הקדירות \u0003ברוח,\u0004 ולא רק על ידי בהמתו, ואילו הנכנס לא קיבל עליו שמירה כל עיקר.","שנינו במשנה שאם \u0003הכניס פירותיו לחצר בעל הבית\u0004 שלא ברשות והוזקה בהמתו של בעל הבית בפירות — חייב בעל הפירות. על כך \u0003אמר רב: לא שנו\u0004 כן \u0003אלא\u0004 בזמן \u0003שהוחלקה בהן\u0004 הבהמה ונפלה, \u0003אבל\u0004 אם \u0003אכלה\u0004 מן הפירות וניזוקה מחמת כך — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003הוה\u0004 \u0005[היה]\u0006 \u0003לה\u0004 \u0003שלא תאכל,\u0004 שדבר זה לא בעל הפירות עשה, אלא הבהמה מעצמה עשתה.","\u0003אמר רב ששת: אמינא\u0004 \u0005[אומר אני]\u0006 \u0003כי ניים ושכיב\u0004 \u0005[כאשר נמנם ושכב]\u0006 \u0003רב אמר להא שמעתא\u0004 \u0005[את ההלכה הזו]\u0006 כלומר, אין ההלכה מדוייקת כל צרכה. \u0003דתניא\u0004 \u0005[ש\u0006הרי שנינו בברייתא\u0005]:\u0006 \u0003הנותן סם המות לפני בהמת חבירו\u0004 — \u0003פטור\u0004 על כך \u0003מדיני אדם, וחייב בדיני שמים.\u0004 ונדייק: \u0003סם המות הוא\u0004 שפטור אם נתן לפניה — משום ש\u0003לא עבידא דאכלה\u0004 \u0005[עשויה\u0006 כרגיל \u0005לאכול]\u0006 ולכן אינו חייב בדיני אדם, \u0003אבל\u0004 אם נתן לפניה \u0003פירות דעבידא דאכלה\u0004 \u0005[שעשויה לאכול]\u0006 ומתה מאכילתם — \u0003בדיני אדם נמי מיחייב\u0004 \u0005[גם כן יהיה חייב],\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 והלא לשיטת רב נאמר גם כאן: \u0003הויא\u0004 \u0005[היה]\u0006 \u0003לה שלא תאכל,\u0004 ואם כן, הרי זו קושיה לשיטת רב!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ומיישבים את דברי רב: \u0003הוא הדין אפילו\u0004 ניזוקה באכילת \u0003פירות נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור מדיני אדם, והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 בברייתא, ש\u0003אפילו סם המות נמי\u0004 \u0005[גם כן]\u0006 ש\u0003לא עבידא דאכלה\u0004 \u0005[עשויה\u0006 \u0005לאכול]\u0006 — בכל זאת \u0003חייב\u0004 על כך \u0003בדיני שמים.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 ותרץ באופן אחר\u0005]:\u0006 \u0003סם המות\u0004 שחייב עליו אם נותנו לפני בהמת חבירו \u0003נמי\u0004 \u0005[גם כן]\u0006 מדובר \u0003באפרזתא\u0004 (מין עשב, הנראה כמאכל בהמה ואולם הוא רעל), \u0003דהיינו פירי\u0004 \u0005[שזהו כ\u0006שאר \u0005פירות]\u0006 שאף עליהם פטור מדיני אדם אם אכלתם הבהמה ומתה, וכשיטת רב שהיה לה שלא תאכל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב, ממה ששנינו בברייתא: \u0003האשה שנכנסה לטחון חטים אצל בעל הבית שלא ברשות, ואכלתן\u0004 את אותן חיטים \u0003בהמתו של בעל הבית\u0004 — \u0003פטור\u0004 בעל הבית. \u0003אם הוזקה\u0004 בהמתו של בעל הבית בחיטים הללו — \u0003חייבת\u0004 האשה. \u0003ו\u0004לשיטת רב \u0003אמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003הוה\u0004 \u0005[היה]\u0006 \u0003לה\u0004 לבהמה \u0003שלא תאכל!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתירוץ הדברים: מה הקושיה בכך? \u0003ומי עדיפא ממתניתין\u0004 \u0005[והאם\u0006 ברייתא זו \u0005עדיפה ממשנתנו]\u0006 \u0003דאוקימנא\u0004 \u0005[שהעמדנו,\u0006 פירשנו אותה\u0005]\u0006 \u0003שהוחלקה בהן?\u0004 אף בברייתא מדובר שניזוקה הבהמה בהחלקה על הפירות ולא באכילתם.","ותוהים: ובאמת, \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ו\u0006זה \u0005שהקשה אותה\u0006 קושיה \u0005מה הקשה אותה]?\u0006 הרי ברור שאפשר לתרץ כך! ומשיבים, \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 המקשה: \u0003בשלמא מתניתין קתני\u0004 \u0005[נניח משנתנו\u0006 ש\u0005שנה\u0006 בה\u0005]\u0006 \u0003\"אם הוזקה בהן\"\u0004 אפשר לפרש \u0003שהוחלקה בהן הוא, אבל הכא\u0004 \u0005[כאן\u0006 בברייתא\u0005]\u0006 לאחר שנאמר \"ואכלתן בהמתו של בעל הבית\" \u0003קתני\u0004 \u0005[שנה]\u0006 \"ו \u0003אם הוזקה\", ולא קתני\u0004 \u0005[שנינו]\u0006 \u0003\"בהן\",\u0004 הואיל ו\u0003אכילה הוא דקתני\u0004 \u0005[ששנה]\u0006 מקודם מסתבר לומר שהנזק של הבהמה היה באופן זה של אכילה שהוזכר מקודם.","ומעירים: \u0003ואידך, אמר\u0004 \u0005[והאחר,\u0006 המתרץ יכול \u0005לומר]\u0006 \u0003לך:\u0004 \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם אמר \"הוזקה\" או \"הוזקה בהן\", בשניהם אפשר לומר שהוזקה בהחלקה ולא באכילה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא במקום אחר: \u0003הכניס שורו לחצר בעל הבית שלא ברשות ואכל\u0004 השור \u0003חטין\u0004 של בעל הבית \u0003ו\u0004כתוצאה מכך \u0003התריז\u0004 (שילשל) \u0003ומת\u0004 — \u0003פטור\u0004 בעל הבית, \u0003ואם הכניס ברשות\u0004 — \u0003בעל החצר חייב. ואמאי\u0004 \u0005[ומדוע]\u0006 חייב בעל הבית בנזק השור? נאמר כשיטת רב: \u0003הוה ליה\u0004 \u0005[היה לו]\u0006 לשור \u0003שלא יאכל,\u0004 ואם אכל הוא הזיק את עצמו!","\u0003אמר רבא: ברשות\u0004 על \u0003שלא ברשות קרמית\u0004 \u0005[אתה מקשה]?\u0006 אין זו סתירה, שאם הכניסו \u0003ברשות\u0004 — \u0003שמירת שורו\u0004 של המכניס \u0003קבל עליו, ואפילו חנק\u0004 השור \u0003את עצמו\u0004 הרי הוא חייב באחריות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003היכא דקביל עליה נטירותא\u0004 \u0005[במקום שקיבל עליו\u0006 בעל החצר \u0005שמירה]\u0006 של הדברים הנכנסים ברשותו \u0003מהו?\u0004 האם רק שמירה \u0003דנפשיה\u0004 \u0005[של\u0006 נזקי \u0005עצמו]\u0006 ובהמותיו \u0003הוא דקביל עליה\u0004 \u0005[שקיבל עליו],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו נטירותא דעלמא קביל עליה\u0004 \u0005[שמירה בכלל של\u0006 נזקים מבחוץ \u0005קיבל עליו]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יהודה בר סימון\u0004 ששנו \u0003ב\u0004מסכת \u0003נזקין דבי\u0004 \u0005[בבית]\u0006 מדרשו של החכם \u0003קרנא,\u0004 וכך שנה: \u0003הכניס פירותיו לחצר בעל הבית שלא ברשות, ובא שור ממקום אחר ואכלן\u0004 — \u0003פטור, ואם הכניס ברשות\u0004 — \u0003חייב.\u0004 ונברר: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003פטור ומאן\u0004 \u0005[ומי\u0006 הוא\u0005]\u0006 ה\u0003חייב\u0004 כאן? \u0003לאו\u0004 \u0005[האם לא]\u0006 נפרש \u0003פטור\u0004 — \u0003בעל\u0004 ה\u0003חצר, [וחייב\u0004 — \u0003בעל\u0004 ה\u0003חצר]?\u0004 משמע שאם קיבל עליו שמירה (לדעת חכמים, שהרי הכניס ברשות) — חייב אפילו אם הזיק שור זר.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 שאפשר לדחות: \u0003לא, פטור\u0004 כוונתו \u0003בעל השור\u0004 המזיק, \u0003וחייב\u0004 — \u0003בעל השור\u0004 המזיק","\u0003.\u0004 ומקשים: \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר ב\u0003בעל השור\u0004,"],["\u0003מאי\u0004 \u0005[מה]\u0006 \u0003ברשות ומאי\u0004 \u0005[ומה]\u0006 \u0003שלא ברשות איכא\u0004 \u0005[יש כאן]?\u0006 שלגבי שורו של אדם זר אין הבדל אם הכניס זה את פירותיו לחצר חבירו ברשותו או שלא ברשותו!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: אם \u0003ברשות\u0004 הכניס — \u0003הויא לה\u0004 \u0005[הריהי]\u0006 לגבי אותו שור בכלל נזקי \u0003שן ברשות הניזק\u0004 שלענין הפירות הריהי כחצר שלו, \u0003ושן ברשות הניזק חייבת.\u0004 ואם הכניס \u0003שלא ברשות\u0004 — אם כן \u0003הויא לה\u0004 \u0005[הריהי]\u0006 כ\u0003שן ברשות הרבים, ושן ברשות הרבים פטורה.\u0004 על כל פנים מכאן לא למדנו דבר לענייננו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר, ששנינו בברייתא: \u0003הכניס שורו לחצר בעל הבית שלא ברשות, ובא שור ממקום אחר ונגחו\u0004 — \u0003פטור, ואם הכניס ברשות\u0004 — \u0003חייב.\u0004 ונברר: \u0003מאן\u0004 \u0005[מי]\u0006 \u0003פטור ומאן\u0004 \u0005[ומי]\u0006 \u0003חייב? לאו\u0004 \u0005[האם לא]\u0006 \u0003פטור\u0004 כוונתו \u0003בעל חצר, וחייב בעל חצר?\u0004 ומכאן יש ראיה ששמירת כל הנזקים קיבל עליו בעל הבית.","ודוחים: \u0003לא, פטור בעל השור\u0004 המזיק, \u0003וחייב בעל השור\u0004 המזיק. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003ברשות ומאי\u0004 \u0005[ומה]\u0006 \u0003שלא ברשות איכא\u0004 \u0005[יש כאן],\u0006 ומה ההבדל לגבי שור מזיק זה? שהרי בנזקי קרן חייב על נגיחה בכל מקום, ואף ברשות הרבים!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' טרפון היא,\u0004 ש\u0003אמר: משונה\u0004 (דין שונה יש) ל\u0003קרן בחצר הניזק\u0004 — \u0003נזק שלם משלם.\u0004 ולפי שיטתו כך פירושה של הברייתא: אם \u0003ברשות\u0004 הכניס הניזק את שורו — \u0003הויא לה\u0004 \u0005[הריהי]\u0006 \u0003קרן בחצר הניזק, ומשלם\u0004 המזיק \u0003נזק שלם,\u0004 אם ש\u0003לא ברשות\u0004 נכנס — \u0003הויא לה\u0004 \u0005[הריהי]\u0006 \u0003קרן ברשות הרבים,\u0004 ופטור מנזק שלם, \u0003ולא משלמא\u0004 \u0005[משלמת]\u0006 \u0003אלא חצי נזק.\u0004","מסופר: \u0003ההיא איתתא דעלתה למיפא בההוא ביתא\u0004 \u0005[אשה אחת שנכנסה לאפות בבית אחד]\u0006 ובידה עיסת בצק, \u0003אתא ברחא דמרי דביתא אכלה ללישא חביל ומית\u0004 \u0005[בא התיש של בעל הבית אכל את העיסה\u0006 של האשה וכתוצאה מכך \u0005התחמם ומת],\u0006 \u0003חייבה רבא\u0004 את האשה \u0003לשלומי\u0004 \u0005[לשלם]\u0006 את \u0003דמי ברחא\u0004 \u0005[התיש].\u0006","ושואלים: \u0003לימא פליגא\u0004 \u0005[האם לומר\u0006 כי \u0005חלוק]\u0006 רבא על \u0003רב,\u0004 שהרי \u0003אמר רב\u0004 במכניס פירותיו לחצר חבירו שלא ברשות והוזקה בהמת חבירו באכילתם, שפטור בעל הבית, משום \u0003הויא\u0004 \u0005[\u0006ש\u0005היה]\u0006 \u0003לה שלא תאכל?\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003הכי השתא\u0004 \u0005[וכי כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 שהכניס פירותיו \u0003שלא ברשות\u0004 — \u0003לא קביל עליה נטירותא\u0004 \u0005[קיבל על עצמו שמירה]\u0006 שלא יזיקו, \u0003הכא\u0004 \u0005[כאן]\u0006 שהיה הדבר \u0003ברשות\u0004 — \u0003קביל עליה נטירותא\u0004 \u0005[קיבל על עצמו,\u0006 כלומר, האשה, \u0005שמירה].\u0006","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 זה \u0003מ\u0004מה ששנינו בברייתא: \u0003האשה שנכנסה לטחון חטין אצל בעל הבית שלא ברשות ואכלתן בהמתו של בעל הבית\u0004 — \u0003פטור\u0004 בעל הבית מלשלם לה, \u0003ואם הוזקה\u0004 בהן הבהמה — \u0003חייבת\u0004 האשה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שנכנסה \u0003שלא ברשות, הא\u0004 \u0005[הרי]\u0006 אם נכנסה \u0003ברשות\u0004 — היה דינה: \u0003פטור!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: אם נכנסה \u0003לטחון חטים, כיון\u0004 \u0003דלא בעיא צניעותא מידי\u0004 \u0005[שאינה צריכה צניעות כלל]\u0006 — \u0003לא בעי מסלקי מרוותא דחצר נפשייהו, ועליה דידיה רמי נטירותא\u0004 \u0005[אין צריכים בעלי החצר לסלק עצמם\u0006 משם, \u0005ועליו עצמו מוטלת השמירה].\u0006 \u0003אבל\u0004 אם נכנסת \u0003למיפא\u0004 \u0005[לאפות],\u0006 \u0003כיון דבעיא\u0004 \u0005[שצריכה]\u0006 \u0003היא צניעותא\u0004 \u0005[צניעות]\u0006 משום שהיא מגלה את זרועותיה תוך כדי לישה, משום כך \u0003מרוותא\u0004 \u0005[בעלי]\u0006 ה\u0003חצר\u0004 \u0003מסלקי נפשייהו\u0004 \u0005[מסלקים\u0006 את \u0005עצמם]\u0006 משם, כדי שתוכל לאפות, \u0003הלכך עלה דידה רמיא נטירותא\u0004 \u0005[על כן עליה עצמה מוטלת השמירה]\u0006 של כל הנמצא בחצר.","שנינו במשנה: \u0003הכניס שורו לחצר בעל הבית\u0004 שלא ברשות וכו'. ועוד בענין זה של שור הנכנס לחצר בעל הבית שלא ברשות וגרם בכניסתו זו לנזק, \u0003אמר רבא: הכניס שורו לחצר בעל הבית שלא ברשות, וחפר בה\u0004 השור \u0003בורות שיחין ומערות\u0004 — \u0003בעל השור חייב בנזקי\u0004 ה\u0003חצר,\u0004 במה שקילקל שורו את החצר, \u0003ובעל\u0004 ה\u0003חצר חייב בנזקי הבור\u0004 אם נתקל מישהו ונפל בבור זה.","\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שיש לפרש את הכתוב \u0003\"כי יכרה איש בר\"\u0004 (שמות כא, לג) כהדגשה למיעוט: \"איש\" — \u0003ולא שור\u0004 שכרה \u0003בור,\u0004 והיה צריך איפוא בעל החצר להיות פטור על בור זה, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דאית ליה להאיך\u0004 \u0005[שיש לו לזה],\u0006 לבעל החצר חובה \u0003למלוייה\u0004 \u0005[למלאותו]\u0006 את הבור בעפר \u0003ולא קא מלייה\u0004 \u0005[מילאו]\u0006 — \u0003כמאן דכרייה דמי\u0004 \u0005[כמי שכרה\u0006 את הבור הוא \u0005נחשב].\u0006","\u0003ו\u0004עוד \u0003אמר רבא\u0004 בענין דומה: \u0003הכניס שורו לחצר בעל הבית שלא ברשות, והזיק\u0004 השור \u0003את בעל הבית, או בעל הבית\u0004 נתקל ו\u0003הוזק בו\u0004 — \u0003חייב\u0004 בעל השור. \u0003רבץ\u0004 השור והזיק בכך — \u0003פטור.\u0004","ותמהים: \u0003ומשום\u0004 ש\u0003רבץ\u0004 והזיק ברביצתו הוא \u0003פטור? אמר רב פפא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רבץ\"\u0004 — הכוונה היא \u0003שהרביץ\u0004 (הטיל) על האדמה \u0003גללים ו\u0004אחרי כן \u0003נטנפו\u0004 בהם \u0003כליו\u0004 (בגדיו) \u0003של בעל הבית,\u0004 \u0003דהויא\u0004 \u0005[שהריהם\u0006 נעשו\u0005]\u0006 ה\u0003גללים\u0004 כהיזק \u0003בור, ולא מצינו\u0004 (מצאנו) \u0003בור שחייב בו את\u0004 נזקי \u0003הכלים.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר: כל תקלה\u0004 בכלל נזק \u0003בור הוא,\u0004 שיש לה דיני בור לפוטרו מנזקי כלים. \u0003אלא ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 שאין רכושו של אדם נחשב לבור \u0003עד\u0004 (אלא אם כן) הוא \u0003מפקר ליה\u0004 \u0005[מפקיר אותו],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003סתם גללים אפקורי מפקיר להו\u0004 \u0005[מפקיר אותם]\u0006 בעל השור, ואם כן הרי זה בור גמור גם לדעת רב.","\u0003ו\u0004עוד הלכה בענין דומה \u0003אמר רבא:\u0004 אדם או בעל חיים ש\u0003נכנס לחצר בעל הבית שלא ברשות, והזיק את בעל הבית או בעל הבית הוזק בו,\u0004 שנתקל בו — \u0003חייב,\u0004 ואם \u0003הזיקו בעל הבית\u0004 — \u0003פטור.\u0004","\u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כש\u0003לא הוה ידע ביה\u0004 \u0005[היה\u0006 בעל הבית \u0005יודע בו]\u0006 שנכנס, \u0003אבל\u0004 אם \u0003הוה ידע ביה\u0004 \u0005[היה יודע בו]\u0006 שנכנס, אף שנכנס בלא רשות, אם \u0003הזיקו בעל הבית\u0004 — \u0003חייב.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003משום דאמר ליה\u0004 \u0005[שאומר לו\u0006 הניזק לבעל החצר\u0005]:\u0006 \u0003נהי דאית\u0004 \u0005[אמנם יש]\u0006 \u0003לך רשותא לאפוקי\u0004 \u0005[רשות להוציא אותי ],\u0006 מחצרך, אבל \u0003לאזוקי לית\u0004 \u0005[להזיק אותי אין]\u0006 \u0003לך רשותא\u0004 \u0005[רשות].\u0006","ומעירים: \u0003ו\u0004בשיטתם זו, שמחייבים בכל מקרה את הנכנס שלא ברשות על נזקי בעל הבית, \u0003אזדו לטעמייהו\u0004 \u0005[הולכים\u0006 הם, רבא ורב פפא, \u0005לשיטתם],\u0006 ש\u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא:\u0004"],["\u0003שניהם,\u0004 שני אנשים שהיו באותו מקום \u0003ברשות, או\u0004 ש\u0003שניהם\u0004 היו במקום אחד \u0003שלא ברשות.\u0004 אם \u0003הזיקו זה את זה,\u0004 שפגעו במישרין — \u0003חייבין\u0004 שניהם. אם נתקלו ו\u0003הוזקו זה בזה\u0004 — \u0003פטורין.\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 כש\u0003שניהם\u0004 נכנסו \u0003ברשות או שניהם שלא ברשות, אבל\u0004 אם \u0003אחד\u0004 נמצא במקום \u0003ברשות\u0004 כגון בעל הבית, שהחצר שלו, \u0003ואחד שלא ברשות,\u0004 כגון זה שנכנס, זה ש\u0003ברשות\u0004 אם הזיק — \u0003פטור,\u0004 וזה \u0003שלא ברשות\u0004 — \u0003חייב\u0004 בנזקי השני, וכדברי רבא ורב פפא.","עוד שנינו במשנה: שור שנכנס שלא ברשות ו\u0003נפל לבור והבאיש\u0004 את \u0003מימיו\u0004 — \u0003חייב.\u0004 ובהסבר הלכה זו \u0003אמר רבא: לא שנו\u0004 הלכה זו \u0003אלא שהבאיש\u0004 השור את המים \u0003בשעת נפילה, אבל\u0004 אם \u0003לאחר נפילה\u0004 הובאשו המים מחמתו, כגון שמת שם והסריחה הנבילה — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003הוי\u0004 \u0005[נהיה\u0006 נעשה\u0005]\u0006 ה\u0003שור\u0004 \u0003בור\u0004 (כלומר, תקלה), \u0003ומים\u0004 הריהם כ\u0003כלים\u0004 שנפלו לבור, \u0003ולא מצינו\u0004 (מצאנו) \u0003בור שחייב בו את\u0004 נזקי \u0003הכלים.\u0004","ומעירים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת \u0003שמואל,\u0004 ש\u0003אמר: כל תקלה בור הוא,\u0004 ויש לה כל דיני בור, ואף לפוטרו מנזקי כלים. \u0003אלא ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 שאינו נקרא בור \u0003עד דמפקר ליה\u0004 \u0005[שמפקיר אותו],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש כאן לומר]?\u0006 שמן הסתם אין הבעלים מפקיר את השור או אף את נבלתו!","\u0003אלא, אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר, \u0005כך נאמר]\u0006 \u0003אמר רבא: לא שנו\u0004 הלכה זו \u0003אלא שהבאיש\u0004 השור את מימי הבור \u0003מגופו\u0004 (נבלתו), \u0003אבל הבאיש\u0004 השור את המים \u0003מריחו\u0004 — \u0003פטור\u0004 הבעלים. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003גרמא בעלמא\u0004 \u0005[גרימה בלבד]\u0006 \u0003הוא,\u0004 שאמנם הוא אחראי לנפילה, אך הסרחון לא נעשה על ידי מעשה שורו עצמו, אלא מאליו, \u0003ו\u0004על \u0003גרמא בעלמא\u0004 \u0005[גרימת\u0006 נזק \u0005בסתם]\u0006 \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 אדם לשלם, אלא רק אם הוא מזיק בפועל.","עוד שנינו במשנה: \u0003היה אביו או בנו לתוכו\u0004 של הבור, ונפל השור עליו והרגו — \u0003משלם\u0004 בעל השור \u0003את הכופר.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 משלם כופר? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003תם הוא\u0004 השור, ותם פטור מתשלום כופר! \u0003אמר רב: ב\u0004שור ה\u0003מועד ליפול על בני אדם בבורות עסקינן\u0004 \u0005[עוסקים אנו]\u0006 כאן.","ושואלים: \u0003אי הכי, בר קטלא\u0004 \u0005[אם כך, בן מוות]\u0006 \u0003הוא\u0004 השור, שאם שור הוא מועד לדבר זה הרי הוא כמזיק ביודעין וחייב מיתה! ומשיבים, \u0003אמר רב יוסף:\u0004 מדובר כאן \u0003דחזא ירוקא\u0004 \u0005[שראה ירק]\u0006 על פי הבור \u0003ונפל,\u0004 שלא התכוון במקרה זה להזיק בנפילה, אלא לאכול, אלא שמועד הוא ליפול כך, ולכן משלם כופר.","\u0003שמואל אמר:\u0004 אכן, שור זה שבמשנתנו תם הוא, ואולם \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יוסי\u0004 \u0003הגלילי היא,\u0004 ש\u0003אמר:\u0004 \u0003תם\u0004 — \u0003משלם חצי כופר.\u0004 ואף במשנתנו יש להבין שהכוונה היא לחצי כופר.","\u0003עולא אמר:\u0004 אכן משנתנו כשיטת \u0003ר' יוסי הגלילי היא\u0004 הסבור שאף שור תם שייך בתשלום כופר, אלא שהוא מחייב במלוא תשלום הכופר, שכן ר' יוסי הגלילי \u0003אמר כ\u0004שיטת \u0003ר' טרפון\u0004 ש\u0003אמר: קרן\u0004 תמה שהזיקה \u0003בחצר הניזק\u0004 — \u0003נזק שלם משלם\u0004 בעליה לניזק, \u0003הכי נמי\u0004 \u0005[כך\u0006 כאן \u0005גם כן]\u0006 \u0003כופר שלם משלם\u0004 למרות שהוא תם.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 להסברו של \u0003עולא היינו דקתני\u0004 \u0005[זו ששנינו]\u0006 \u0003היה אביו או בנו לתוכו\u0004 לפי שהיתה זו קרן בחצר הניזק, אלא \u0003ל\u0004הסברו של \u0003שמואל מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע הוזכרו דווקא \u0003אביו או בנו? אפילו אחר נמי\u0004 \u0005[גם כן]\u0006 צריך לשלם עליו חצי כופר, ואף אם היה זה ברשות הרבים!","ומשיבים: אכן כך, אלא ש\u0003אורחיה דמילתא קתני\u0004 \u0005[דרך הדברים\u0006 המצויה \u0005שנה],\u0006 שמן הסתם היה בבור מישהו ממשפחת בעל החצר.","עוד שנינו במשנה ש\u0003אם הכניס ברשות\u0004 — \u0003בעל\u0004 ה\u0003חצר חייב.\u0004 רבי אומר: בכולן אינו חייב עד שיקבל עליו לשמור. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בפסק ההלכה שבמחלוקת זו: \u0003רב אמר: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כתנא קמא, ושמואל אמר: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרבי.\u0004","ובאותו ענין שבמשנתנו עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר בעל החצר לבעל השור \u0003\"כנוס\u0004 (הכנס) \u0003שורך\u0004 לחצרי \u0003ושמרו\u0004 (שמור אותו אתה) \u0003\",\u0004 אם \u0003הזיק\u0004 השור את בעל החצר — \u0003חייב\u0004 בעליו, אם \u0003הוזק\u0004 — \u0003פטור\u0004 בעל החצר. אם אמר לו \u0003\"כנוס שורך ואני אשמרנו\",\u0004 אם \u0003הוזק\u0004 השור — \u0003חייב\u0004 בעל החצר, \u0003הזיק\u0004 השור — \u0003פטור\u0004 בעל השור.","תחילה מעירים לגופם של דברים, \u0003הא גופא קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה],\u0006 שכן \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 בתחילת הברייתא שאם אמר לו \u0003\"כנוס שורך ושמרו\"\u0004 אם \u0003הזיק\u0004 השור — \u0003חייב,\u0004 אם \u0003הוזק\u0004 — \u0003פטור.\u0004","ונדייק בדבר: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל החצר לבעל השור \u0003\"שמרו\",\u0004 אז \u0003חייב בעל השור ופטור בעל חצר, הא סתמא\u0004 \u0005[הרי סתם]\u0006 נתינת רשות להכניס את שורו בלא אמירה מפורשת \"שמור אתה אותו\" — היינו מבינים ש\u0003חייב בעל חצר\u0004 אם הוזק השור, \u0003ופטור בעל השור\u0004 אם הזיק, וטעמו של דבר כשיטת חכמים במשנה, כי \u0003בסתמא\u0004 \u0005[בסתם]\u0006 \u0003מקבל עליה נטירותא\u0004 \u0005[עליו\u0006 בעל החצר \u0005שמירה]\u0006 כאשר מתיר לו להיכנס לחצירו.","לעומת זאת, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף]\u0006 הברייתא: אמר לו \u0003\"כנוס שורך ואני אשמרנו\",\u0004 אם \u0003הוזק\u0004 — \u0003חייב,\u0004 ואם \u0003הזיק\u0004 — \u0003פטור.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל החצר לבעל השור \u0003\"ואני אשמרנו\" הוא דמחייב\u0004 \u0005[שמתחייב]\u0006 \u0003בעל החצר ופטור בעל השור, הא סתמא\u0004 \u0005[הרי סתם]\u0006 נתינת רשות בלא שקיבל עליו שמירתו במפורש — \u0003חייב בעל השור ופטור בעל\u0004 ה\u0003חצר,\u0004 משום \u0003דבסתמא\u0004 \u0005[שבסתם]\u0006 בעל החצר \u0003לא מקבל עליה נטירותא\u0004 \u0005[עליו שמירה],\u0006 ובזה","\u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003רבי,\u0004 ש\u0003אמר\u0004 שאין חייב \u0003עד ש\u0004במפורש \u0003יקבל עליה נטירותא\u0004 \u0005[עליו שמירה]\u0006 \u0003בעל הבית לשמור,\u0004 ונמצא כי \u0003רישא\u0004 \u0005[תחילת]\u0006 הברייתא כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כדעת \u0003רבי!\u0004","\u0003אמר ר' אלעזר: תברא\u0004 \u0005[שבורה,\u0006 חצויה\u0005],\u0006 כלומר, אין ברייתא זו לפי שיטה אחת, אלא \u0003מי ששנה זו לא שנה זו. רבא אמר:\u0004 כל הברייתא \u0003כולה\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 ואין לדייק מן הלשון \"אשמרנו\", בסופה, שכן \u0003איידי דנסיב רישא\u0004 \u0005[מתוך שנקט\u0006 ב\u0005תחילה]\u0006 בדברי בעל החצר את הביטוי \u0003\"שמרו\", תנא סיפא\u0004 \u0005[שנה\u0006 ב\u0005סופה]\u0006 \u0003\"ואני אשמרנו\".\u0004 אבל הוא הדין גם אם לא אמר כן, ונתן לו רשות בסתם להכניס לחצירו, שלדעת חכמים סתם נתינת רשות להיכנס היא גם קבלת אחריות על שמירה.","ואילו \u0003רב פפא אמר:\u0004 כל הברייתא \u0003כולה\u0004 כשיטת \u0003רבי היא,\u0004 שבסתם אינה מקבל עליו שמירה, וכדיוק הדברים מסוף הברייתא. \u0003ו\u0004באשר לדיוק הדברים בתחילתה: \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003לה כ\u0004שיטת \u0003ר' טרפון,\u0004 ש\u0003אמר: קרן בחצר הניזק\u0004 — \u0003נזק שלם משלם.\u0004","\u0003הלכך\u0004 \u0005[על כן],\u0006 אם \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"שמרו\"\u0004 — \u0003לא מקני ליה\u0004 \u0005[מקנה לו]\u0006 על ידי כך \u0003מקום\u0004 (חלק כלשהו) \u0003בחצר,\u0004 שהרי אינו נותן לו אפשרות להתנהג בחצר (לענין השור) כאילו היתה זו חצירו, \u0003והויא ליה\u0004 \u0005[והרי היא]\u0006 נגיחה שנוגח השור את בהמתו של בעל החצר \u0003קרן בחצר הניזק, וקרן בחצר הניזק משלם נזק שלם.\u0004","ואולם אם \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"שמרו\"\u0004 — הרי על ידי מתן הרשות להכניס את השור \u0003אקנויי אקני ליה\u0004 \u0005[הקנה לו]\u0006 \u0003מקום\u0004 (חלק כלשהו) \u0003בחצר\u0004 לענין נזיקין, \u0003והויא ליה\u0004 \u0005[והרי היא]\u0006 \u0003חצר השותפין, וקרן בחצר השותפין אינו משלם אלא חצי נזק.\u0004","\u0003שור שהיה מתכוין ל\u0004נגוח את \u0003חבירו, והכה\u0004 \u0003את\u0004 \u0003האשה\u0004 המעוברת \u0003ו\u0004כתוצאה מכך \u0003יצאו ילדיה\u0004 (ולדותיה) מתים — \u0003פטור\u0004 בעל השור \u0003מדמי ולדות. ו\u0004אילו \u0003אדם שהיה מתכוין ל\u0004הכות את \u0003חבירו והכה\u0004 את \u0003האשה\u0004 המעוברת, \u0003ויצאו ילדיה\u0004 מתים — \u0003משלם דמי ולדות.\u0004","\u0003כיצד\u0004 \u0003משלם דמי ולדות?\u0004 כלומר, כיצד מעריכים את שוויים של הוולדות? \u0003שמין\u0004 (מעריכים) את \u0003האשה כמה היא יפה\u0004 (שווה), אילו היתה נמכרת כשפחה \u0003עד שלא\u0004 (בטרם) \u0003ילדה, וכמה היא יפה משילדה,\u0004 ונותנים את ההפרש לבעלה של האשה. \u0003אמר רבן שמעון בן גמליאל\u0004 \u0003:\u0004"],["\u0003אם כן\u0004 תגיע לתוצאות תמוהות שהרי \u0003משהאשה יולדת משבחת\u0004 ועולה ערכה. \u0003אלא שמין\u0004 (מעריכים) \u0003את הולדות כמה הן יפין\u0004 (שווים), \u0003ונותן לבעל. ואם אין לה בעל,\u0004 וכגון שמת — \u0003נותן ליורשיו.\u0004","\u0003היתה\u0004 זו האשה המעוברת \u0003שפחה ונשתחררה, או גיורת,\u0004 והיתה נשואה לגר או לעבד משוחרר, ומת הבעל, ואין לו יורשים כלל — הרי זה \u0003פטור\u0004 מתשלום דמי ולדות, שכן אין תשלום זה ניתן לאשה אלא לבעלה דווקא.","שנינו במשנה שאם היה השור מתכוון לנגוח שור אחר ונגח את האשה — פטור מדמי ולדות. ומדייקים מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003מתכוין לחבירו\u0004 — פטור, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה השור \u0003מתכוין לאשה\u0004 — \u0003משלם\u0004 אף \u0003דמי ולדות. לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהיה\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003רב אדא בר אהבה,\u0004 ש\u0003אמר רב אדא בר אהבה: שוורים שנתכוונו ל\u0004נגוח את ה\u0003אשה\u0004 — \u0003פטורים מדמי ולדות?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רב אדא בר אהבה\u0004 בתשובה על כך: \u0003הוא הדין\u0004 ש\u0003אפילו נתכוונו לאשה נמי\u0004 \u0005[גם כן]\u0006 \u0003פטורים מדמי ולדות, והא דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003שור שהיה מתכוין לחבירו,\u0004 טעם הדבר הוא: \u0003איידי דקא בעי למיתנא סיפא\u0004 \u0005[מתוך שרצה לשנות\u0006 ב\u0005סוף,\u0006 בהמשך המשנה\u0005]\u0006 \u0003\"אדם שהיה מתכוין לחבירו\", דהכי כתיב קרא\u0004 \u0005[שכך נאמר\u0006 ב\u0005כתוב]\u0006 במפורש: \"כי ינצו אנשים ונגפו אשה הרה ויצאו ילדיה\" (שמות כא, כב), והרי זה מקרה של המתכוון לחבירו והכה את האשה, \u0003קתני רישא נמי\u0004 \u0005[שנה\u0006 ב\u0005תחילה גם כן]\u0006 בדומה לכך: \u0003שור שהיה מתכוין לחבירו.\u0004","ועוד בענין זה של דין שור בדמי ולדות, \u0003אמר רב פפא: שור שנגח את השפחה ויצאו ילדיה\u0004 — \u0003משלם דמי ולדות. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003חמרתא מעברתא בעלמא\u0004 \u0005[אתון מעוברת סתם]\u0006 \u0003הוא דאזיק\u0004 \u0005[שהזיק],\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי העבדים: \u0003\"שבו לכם פה עם החמור\"\u0004 (בראשית כב,ה), ודרשו: \u0003עם הדומה לחמור\u0004 ואין זה בכלל הפרשה האמורה בתורה שנתמעט בה שור מתשלום דמי ולדות.","שנינו במשנה: \u0003כיצד משלם דמי ולדות\u0004 — שמין את האשה כמה עלה ערכה ושבחה בגלל הוולדות. ותוהים: וכי מדובר פה בהערכה של \u0003דמי ולדות?\u0004 \u0003\"\u0004כיצד משלם \u0003שבח ולדות\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כלומר, כך התכוונה המשנה לומר: \u0003כיצד משלם דמי ולדות ושבח ולדות\u0004 — מלבד הערכת דמי הוולדות \u0003שמין את האשה כמה היא יפה\u0004 (שווה) \u0003עד שלא\u0004 (בטרם) \u0003ילדה, וכמה היא יפה משילדה.\u0004","עוד שנינו במשנה ש\u0003אמר רבן שמעון בן גמליאל: אם כן, משהאשה יולדת משבחת.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 כיצד יש להבין את הדברים? \u0003אמר רבה: הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 בלשון שאלה: לשיטה זו של הערכה \u0003וכי אשה\u0004 מעוברת \u0003משבחת קודם שתלד יותר מלאחר שתלד? והלא אשה משבחת\u0004 ועולה מחירה \u0003לאחר שתלד יותר מקודם שתלד,\u0004 שכן כאשר היא מעוברת יש סכנה שמא תמות בלידה ולכן מחירה יורד בגלל הסיכון, ואילו לאחר שילדה עולה מחירה! \u0003אלא,\u0004 רק \u0003שמין\u0004 (מעריכים) \u0003את הולדות\u0004 כמה הן שווים \u0003ונותנין\u0004 דמיהם \u0003לבעל.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כהסברו של רבה בדברי רבן שמעון בן גמליאל: \u0003וכי אשה משבחת קודם שתלד יותר מלאחר שתלד? והלא אשה משבחת לאחר שתלד יותר\u0004 \u0003מקודם שתלד! אלא שמין את הולדות ונותנין לבעל.\u0004","\u0003רבא אמר: הכי קתני\u0004 \u0005[כך שנה]\u0006 במשנה, כך יש להבין את דברי רבן שמעון בן גמליאל: \u0003וכי אשה\u0004 רק \u0003למי שיולדת\u0004 עבורו \u0003משבחת\u0004 וערכה כאשה מעוברת עולה רק עבור הבעל, \u0003ואין לעצמה בשבח\u0004 שהשביח גופה מחמת \u0003ולדות כלום?\u0004 אינו כן, \u0003אלא שמין את הולדות ונותנין\u0004 את דמיהם \u0003לבעל\u0004 בלבד או ליורשיו, \u0003ו\u0004אולם את ה\u0003שבח\u0004 שהשביח גופה מחמת ה\u0003ולדות\u0004 \u0003חולקין\u0004 הבעל והאשה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כהסברו של רבא בדברי רבן שמעון בן גמליאל, \u0003אמר רבן שמעון בן גמליאל: וכי אשה למי שיולדת משבחת ואין לעצמה בשבח ולדות כלום? אלא, שמין נזק בפני עצמו, וצער בפני עצמו, ושמין את הולדות ונותנין לבעל, ושבח ולדות חולקין.\u0004","לגוף הענין שואלים: \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבן שמעון בן גמליאל\u0004 שבברייתא הקודמת לשיטת רבה, שאין ערכה עולה, על דברי \u0003רבן שמעון בן גמליאל\u0004 שבברייתא זו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 שכן כל ברייתא עוסקת במקרה אחר, ובאופן זה: \u0003כאן\u0004 בברייתא שנאמר בה שערכה של אשה מעוברת עולה לאחר שתלד הוא \u0003במבכרת\u0004 (יולדת לידה ראשונה), שערכה יורד קודם הלידה, מחשש שמא תמות בלידתה. ו\u0003כאן\u0004 בברייתא השניה שהובאה, שערכה כמעוברת עולה, מדובר \u0003ב\u0004מי \u0003שאינה מבכרת.\u0004","שואלים: ולפי הברייתא השניה \u0003ורבנן\u0004 \u0003דאמרי\u0004 \u0005[וחכמים שאומרים]:\u0006 \u0003שבח ולדות נמי\u0004 \u0005[גם כן]\u0006 \u0003לבעל, מאי טעמא\u0004 \u0005[מה טעם,\u0006 מקור הדבר\u0005]?\u0006 ומשיבים, מייתור הכתובים, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \"ונגפו אשה הרה ויצאו ילדיה\" (שמות כא, כב), ויש לשאול: \u0003ממשמע שנאמר\u0004 \u0003\"ויצאו ילדיה\"\u0004 \u0003איני יודע שהיא הרה?\u0004 אם כן \u0003מה תלמוד לומר \"\u0004ונגפו אשה \u0003הרה\"?\u0004 — \u0003לומר לך\u0004 כי \u0003שבח הריון,\u0004 כל תוספת בערכה שבאה מחמת ההריון, שייכת \u0003לבעל.\u0004","ושואלים: \u0003ורבן שמעון בן גמליאל, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"הרה\" מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מבעי ליה לכדתניא\u0004 \u0005[דרוש\u0006 הוא \u0005לו לכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: לעולם\u0004 המכה את האשה \u0003אינו חייב\u0004 בתשלום זה של ולדות \u0003עד שיכנה כנגד בית ההריון,\u0004 כלומר, על בטנה. \u0003אמר רב פפא: לא תימא\u0004 \u0005[אל תאמר]\u0006 עד שיכה אותה \u0003כנגד בית הריון ממש,\u0004 כלומר, דווקא במישרין על בטנה, \u0003אלא כל\u0004 \u0003היכא דסליק ביה שיחמא\u0004 \u0005[מקום שתגיע בו מכה]\u0006 \u0003לולד,\u0004 כלומר, בכל חלל הגוף, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 אם היכה את האשה ב\u0003יד\u0004 או ב\u0003רגל\u0004 וכתוצאה מכך הפילה — שהוא \u0003לא\u0004 חייב בתשלום דמי הוולדות, כיון שאנו אומרים שלא מחמת המכה הפילה.","שנינו במשנה: אם \u0003היתה שפחה ונשתחררה או גיורת\u0004 שהיתה נשואה לגר ומת בעלה — \u0003פטור\u0004 המכה מתשלום דמי ולדות. \u0003אמר רבה: לא שנו\u0004 הלכה זו \u0003אלא\u0004 באופן \u0003שחבל בה בחיי\u0004 בעלה \u0003הגר, ו\u0004לפני ששילם \u0003מת הגר,\u0004 ש\u0003כיון\u0004 ש\u0003חבל בה בחיי הגר\u0004 — \u0003זכה בהו\u0004 \u0005[בהן],\u0006 במעות, אותו \u0003גר, וכיון\u0004 ש\u0003מת הגר\u0004 ואין לו יורשים — \u0003זכה בהו\u0004 \u0005[בהם]\u0006 המזיק \u0003מן הגר,\u0004 שנחשב המזיק שהכסף בידיו כאילו זכה ולקח מן ההפקר. \u0003אבל\u0004 אם \u0003חבל בה לאחר מיתת\u0004 בעלה \u0003הגר\u0004 — \u0003זכיא לה איהי בגוייהו\u0004 \u0005[זוכה היא בהן]\u0006 במעות, \u0003ומיחייב לשלומי\u0004 \u0005[וחייב לשלם]\u0006 \u0003לה לדידה\u0004 \u0005[לעצמה].\u0006","\u0003אמר רב חסדא\u0004 בתמיהה: \u0003מרי דיכי\u0004 \u0005[אדוניה של\u0006 שמועה \u0005זו]!\u0006 כלומר, כיצד אפשר לומר דבר כזה? \u0003אטו\u0004 \u0005[וכי]\u0006 דמי \u0003ה\u0004\u0003ולדות צררי נינהו וזכיא בהו\u0004 \u0005[\u0006מעות \u0005צרורות\u0006 הן \u0005שהיא זוכה בהם]\u0006 בירושה? אין הדבר כן, \u0003אלא\u0004 אם \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003לבעל,\u0004 שהוא חי — \u0003זכה ליה רחמנא\u0004 \u0005[זיכתה לו התורה]\u0006 דמי ולדות, ואם \u0003ליתיה\u0004 \u0005[אינו]\u0006 \u0003לבעל\u0004 — \u0003לא\u0004 זיכתה התורה דמי הוולדות לאחר, ואפילו לא לאשתו.","וכן \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רבה, ממה ששנינו: \u0003הכה את האשה ויצאו ילדיה\u0004 — \u0003נותן נזק וצער לאשה ודמי ולדות לבעל, אין הבעל\u0004 קיים — \u0003נותן\u0004 דמי ולדות \u0003ליורשיו, אין האשה\u0004 קיימת — \u0003נותן\u0004 את התשלומים המגיעים לה \u0003ליורשיה. היתה שפחה ונשתחררה או גיורת\u0004 — \u0003זכה\u0004 המכה. משמע שאם אין הבעל קיים — אין לאישה דבר!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003ומי עדיפא ממתניתין\u0004 \u0005[והאם עדיפה\u0006 הברייתא \u0005ממשנתנו\u0006 שלנו\u0005]\u0006 שאף בה שנינו שאין האשה מקבלת דמי ולדות \u0003דאוקימנא\u0004 \u0005[שהעמדנו,\u0006 הסברנו\u0005]\u0006 אותה שמדובר בה \u0003שחבל בה בחיי הגר ומת הגר? הכא נמי\u0004 \u0005[כאן גם כן]\u0006 צריך לפרש \u0003שחבל בה בחיי הגר ומת הגר. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ותפרש אפילו חבל בה \u0003לאחר מיתת הגר\u0004,"],["\u0003ותני\u0004 \u0005[ושנה]\u0006 בברייתא זו במקום \"זכה\" — \u0003\"זכתה\".\u0004 כלומר, לא זכה המכה, אלא זכתה האשה.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי מחלוקת רבה ורב חסדא היא \u0003כתנאי\u0004 \u0005[\u0006כמחלוקת \u0005תנאים]\u0006 שנחלקו בשאלה זו, שכך שנינו: \u0003בת ישראל שנישאת לגר ונתעברה ממנו, וחבל בה\u0004 אדם \u0003בחיי הגר\u0004 ויצאו ממנה הוולדות — \u0003נותן דמי ולדות לגר,\u0004 בעלה. חבל בה \u0003לאחר מיתת הגר, תני חדא\u0004 \u0005[שנוייה\u0006 ברייתא \u0005אחת]:\u0006 \u0003חייב, ותני חדא\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003פטור, מאי לאו תנאי נינהו\u0004 \u0005[האם לא\u0006 במחלוקת \u0005תנאים\u0006 שנויות \u0005הן]\u0006 ברייתות אלה? \u0003ל\u0004פי שיטת \u0003רבה ודאי\u0004 חייבים לומר כי \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. אלא ל\u0004שיטת \u0003רב חסדא מי לימא תנאי\u0004 \u0005[האם\u0006 יש \u0005לומר\u0006 כי מחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004","ומשיבים: לדעת רב חסדא אפשר לומר כי שתי הברייתות סבורות כמוהו, ומה שנחלקו הברייתות \u0003לא קשיא\u0004 \u0005[קשה]\u0006 לרב חסדא, שכן ניתן לפרש דבר זה לא בדמי ולדות, אלא בשבח ולדות — בשבח שהשביח גוף האשה מחמת היותה מעוברת, שנחלקו בו במשנתנו; \u0003הא\u0004 \u0005[זו]\u0006 ששנה פטור — כדברי \u0003רבנן\u0004 \u0005[חכמים],\u0006 שלדעתם שבח ולדות לבעל, ו\u0003הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 ששנה חייב — כדברי \u0003רבן שמעון בן גמליאל\u0004 שאשה זוכה בשבח שהשביח גופה מחמת הוולדות, וזה נותן המזיק לאשה גם אם חבל בה לאחר מיתת הבעל.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003רבן שמעון בן גמליאל, מאי אריא\u0004 \u0005[מדוע דווקא]\u0006 נאמר דין זה \u0003לאחר מיתה?\u0004 \u0003אפילו מחיים\u0004 של הבעל \u0003נמי אית\u0004 \u0005[גם כן יש]\u0006 \u0003לה פלגא\u0004 \u0005[מחצה]\u0006 (כפי שנאמר בסוגיה הקודמת)! ומשיבים: \u0003מחיים אית לה פלגא\u0004 \u0005[יש לה חצי],\u0006 \u0003לאחר מיתה\u0004 יש לה \u0003כוליה\u0004 \u0005[הכל].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 יכול אתה לפרש כי \u0003הא והא\u0004 \u0005[זו וזו],\u0006 שתי הברייתות כדעת \u0003רבן שמעון בן גמליאל,\u0004 אלא מדובר בעניינים שונים: \u0003כאן\u0004 ששנינו חייב — מדובר \u0003בשבח ולדות\u0004 ששייך בחלקו לאשה, ואם מת בעלה — זוכה היא בכולו. ו\u0003כאן\u0004 ששנינו פטור — מדובר \u0003בדמי ולדות\u0004 ששייכים לבעל, ולאחר מיתת בעלה הגר פטור המזיק מן התשלום.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 ומדוע יש הבדל בין הדברים? — \u0003משבח ולדות,\u0004 כלומר, חלקו של הבעל שהאשה זוכה בו לאחר מותו \u0003לישמע\u0004 \u0005[נלמד]\u0006 גם את הדין לגבי \u0003דמי ולדות,\u0004 שתזכה האשה גם בהם אם נחבלה לאחר מיתת הבעל, לדעת רבן שמעון בן גמליאל, \u0003ומ\u0004דעת \u0003רבן שמעון בן גמליאל לישמע לרבנן\u0004 \u0005[נלמד ל\u0006דעת \u0005חכמים]\u0006 שהרי לגבי דמי ולדות בחיי הבעל אין ביניהם מחלוקת!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא,\u0004 אין מקום להנחה הראשונה של קושיה זו, ומדוע — \u0003שבח ולדות דשייכא\u0004 \u0005[ששייכת]\u0006 \u0003ידה\u0004 (חזקתה) \u0003בגוייהו\u0004 \u0005[בהם]\u0006 כבר מתחילה — \u0003זכיא בהו בכולהו\u0004 \u0005[זוכה בהם בכולם]\u0006 לאחר מות בעלה, משום שהיתה לה כבר מקצת זכיה בהם, ואילו \u0003דמי ולדות\u0004 ש\u0003לא שייכא\u0004 \u0005[שייכת]\u0006 \u0003ידה בגוייהו\u0004 \u0005[בהם]\u0006 מתחילה \u0003לא זכיא בהו\u0004 \u0005[זוכה בהם]\u0006 \u0003כלל,\u0004 לפי שלענין זה אין לה יותר זכות מאשר לכל אדם אחר.","\u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב ייבא סבא\u0004 \u0005[הזקן]\u0006 את \u0003רב נחמן: המחזיק בשטרותיו של גר מהו\u0004 דינו לאחר מיתת הגר? האם נאמר כי \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003מחזיק בשטרא\u0004 \u0005[בשטר]\u0006 — \u0003אדעתיה דארעא\u0004 \u0005[על דעת הקרקע]\u0006 המשועבדת בשטר אלה \u0003הוא\u0004 ש\u0003מחזיק, ובארעא הא\u0004 \u0005[ובקרקע\u0006 עצמה \u0005הרי]\u0006 \u0003לא אחזיק\u0004 \u0005[החזיק]\u0006 ואותה בוודאי לא קנה, \u0003ושטרא נמי\u0004 \u0005[ו\u0006אם כן \u0005שטר\u0006 עצמו \u0005גם כן]\u0006 \u0003לא קנה\u0004 אפילו את הנייר, משום \u0003דלאו דעתיה אשטרא\u0004 \u0005[שאין דעתו על השטר\u0006 לקנותו\u0005]\u0006 אלא על הדבר הכתוב בו, וכיוון שמת הגר, בטל שעבודו ואינו יכול לגבות. \u0003או דלמא דעתיה נמי אשטרא\u0004 \u0005[שמא דעתו גם כן על השטר],\u0006 ונייר השטר שייך לו?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עני מורי\u0004 \u0005[ענה אדוני],\u0006 \u0003וכי לצור על פי צלוחיתו הוא צריך,\u0004 וכי דעתו על השטר שיוכל להשתמש בו כנייר, לכסות בו פי צלוחית? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לצור ולצור,\u0004 שדעתו של האדם גם על שימוש פעוט זה.","ועוד בענייני גר שמת, \u0003אמר רבה:\u0004 היה \u0003משכונו של ישראל ביד גר, ומת הגר, ובא ישראל אחר והחזיק בו\u0004 במשכון, שהרי אין יורשים לגר — \u0003מוציאין אותו,\u0004 את המשכון \u0003מידו\u0004 ומחזירים אותו לבעליו, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003כיון דמית ליה\u0004 \u0005[שמת לו]\u0006 ה\u0003גר\u0004 — \u0003פקע ליה שעבודיה\u0004 \u0005[לו שיעבודו]\u0006 על המשכון, וממילא חוזר המשכון לבעליו הראשונים, ואין רשות לאחר לקחתו.","ודין נוסף: אם היה \u0003משכונו של גר ביד ישראל ומת הגר, ובא ישראל אחר והחזיק בו\u0004 — \u0003זה,\u0004 המלווה \u0003קנה\u0004 במשכון חלק \u0003כנגד מעותיו\u0004 שהלווה לגר, \u0003וזה\u0004 האחר שהחזיק במשכון \u0003קנה את השאר.\u0004","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 לא נאמר שיזכה המלווה בכל המשכון? \u0003תקני ליה\u0004 \u0005[תקנה לו]\u0006 \u0003חצירו,\u0004 כי מכיוון שהמשכון היה מונח ברשותו הרי רשותו קונה לו, \u0003דהאמר\u0004 \u0005[שהרי אמר]\u0006 \u0003ר' יוסי בר חנינא: חצירו של אדם קונה לו\u0004 אפילו \u0003שלא מדעתו!\u0004","\u0003אמרי:\u0004 \u0005[אומרים]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 באופן \u0003דליתיה\u0004 \u0005[ש\u0006המלווה \u0005איננו]\u0006 ליד החצר, ומסבירים: \u0003כל היכא\u0004 \u0003דאיתא לדידיה\u0004 \u0005[מקום שהוא עצמו ישנו],\u0006 \u0003דאי בעי מקני\u0004 \u0005[שאילו היה רוצה לקנות]\u0006, אם היה נוטל לידיו את המשכון, \u0003מצי קני\u0004 \u0005[יכול היה לקנות\u0006 בעצמו\u0005]\u0006 — \u0003קניא ליה נמי\u0004 \u0005[קונה לו גם כן]\u0006 \u0003חצירו,\u0004 ואולם \u0003כל היכא דליתיה לדידיה\u0004 \u0005[מקום שהוא עצמו איננו]\u0006 \u0003דאי בעי\u0004 \u0005[שאם רוצה]\u0006 \u0003הוא\u0004 עצמו \u0003למיקני\u0004 \u0005[לקנות]\u0006 את המשכון \u0003לא מצי קני\u0004 \u0005[אינו יכול לקנות]\u0006 — \u0003חצירו נמי לא קניא\u0004 \u0005[גם כן אינה קונה].\u0006","ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: במקרה \u0003דליתיה\u0004 \u0005[ש\u0006המלווה אינו] \u0003בחצירו\u0004 ש\u0003לא קנה\u0004 את שאר המשכון.","\u0003החופר בור\u0004 באופן שחללו \u0003ברשות היחיד ופתחו\u0004 באופן שהכניסה לבור היא ב\u0003רשות הרבים, או\u0004 שחפר בור \u0003ברשות הרבים ופתחו לרשות היחיד,\u0004 או שחפר \u0003ברשות היחיד\u0004 שלו \u0003ופתחו לרשות היחיד\u0004 של \u0003אחר\u0004 — הרי זה \u0003חייב\u0004 בכל אלה בנזקי הבור.","באותו ענין ששנינו במשנה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003החופר בור\u0004 שחללו \u0003ברשות היחיד ופתחו לרשות הרבים, (ברשות הרבים ופתחו לרשות היחיד)\u0004 — \u0003חייב, וזהו בור האמור בתורה,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר:\u0004 מי ש\u0003הפקיר רשותו\u0004 שהבור נמצא בה \u0003ולא הפקיר בורו\u0004 — \u0003זהו בור האמור בתורה.\u0004","ובהסבר מחלוקתם \u0003אמר רבה: בבור\u0004 שחפר אדם \u0003ברשות הרבים\u0004 או פתח את בורו לשם — \u0003כולי עלמא\u0004 \u0005[הכל],\u0006 ר' ישמעאל ור' עקיבא, \u0003לא פליגי\u0004 \u0005[חלוקים]\u0006 \u0003דמיחייב\u0004 \u0005[שהוא מתחייב]\u0006 בנזיקין, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר]? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"\u0003וכי יפתח\u0004 איש בור\", \u0003ו\u0004הוסיף וכתב: \"או \u0003כי יכרה\u0004 איש בור\" (שמות כא, לג), ויש לשאול: \u0003אם על פתיחה,\u0004 כלומר, הסרת הכיסוי של בור החפור מכבר — \u0003חייב, על כרייה\u0004 של בור חדש \u0003לא כל שכן\u0004 שחייב?! ואם כן, מה בא הכתוב ללמדנו? \u0003אלא\u0004 כך יש להבין \u0003שעל עסקי פתיחה ועל עסקי כרייה באה לו\u0004 האחריות לבור, שאף אם אין הוא הבעלים של המקום — יש לו אחריות משום שעשה דבר המזיק. \u0003לא נחלקו אלא\u0004"]]};
